// intended for benchmarking/diagnostics and is disabled by default.
func SetIteratorDebug(enabled bool) {
	iteratorDebugEnabled.Store(enabled)
}

// SetPointSuccessorDebug toggles timestamp attribution for SeekGE. It is for
// benchmarks and diagnostics only; normal point reads do no clock sampling.
func SetPointSuccessorDebug(enabled bool) {
	pointSuccessorDebugEnabled.Store(enabled)
}

func envBool(name string) bool {
	v, ok := os.LookupEnv(name)
	if !ok {
		return false
	}
	v = strings.TrimSpace(strings.ToLower(v))
	if v == "" {
		return true
	}
	switch v {
	case "1", "true", "t", "yes", "y", "on":
		return true
	case "0", "false", "f", "no", "n", "off":
		return false
	}
	if n, err := strconv.Atoi(v); err == nil {
		return n != 0
	}
	return false
}

func envUint64(name string, fallback uint64) uint64 {
	v, ok := os.LookupEnv(name)
	if !ok {
		return fallback
	}
	v = strings.TrimSpace(v)
	if v == "" {
		return fallback
	}
	n, err := strconv.ParseUint(v, 10, 64)
	if err != nil {
		return fallback
	}
	return n
}

func envUint64Optional(name string) (uint64, bool) {
	v, ok := os.LookupEnv(name)
	if !ok {
		return 0, false
	}
	v = strings.TrimSpace(v)
	if v == "" {
		return 0, false
	}
	n, err := strconv.ParseUint(v, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, true
}

func updateAtomicMaxUint64(dst *atomic.Uint64, value uint64) {
	for {
		cur := dst.Load()
		if value <= cur {
			return
		}
		if dst.CompareAndSwap(cur, value) {
			return
		}
	}
}

func (db *DB) hasDirtyValueLogLanes() bool {
	if db == nil || !db.valueLogEnabled() {
		return false
	}
	for i := range db.lanes {
		if db.lanes[i].vlogDirty.Load() || db.lanes[i].vlogSyncPending.Load() {
			return true
		}
	}
	return false
}

func (db *DB) markLaneValueLogBoundary(l *lane, totalBytes int64, flushedBoundary, syncedBoundary bool) {
	if l == nil {
		return
	}
	if syncedBoundary {
		l.vlogDirty.Store(false)
		l.vlogSyncPending.Store(false)
		return
	}
	if totalBytes <= 0 {
		return
	}
	if flushedBoundary {
		l.vlogDirty.Store(false)
	} else {
		l.vlogDirty.Store(true)
	}
	if db == nil || db.relaxedSync {
		l.vlogSyncPending.Store(false)
		return
	}
	l.vlogSyncPending.Store(true)
}

type valueLogSyncPath uint8

const (
	valueLogSyncPathMaterialization valueLogSyncPath = iota
	valueLogSyncPathExternalRef
	valueLogSyncPathPendingBarrier
	valueLogSyncPathCheckpoint
	valueLogSyncPathCount
)

func (p valueLogSyncPath) statName() string {
	switch p {
	case valueLogSyncPathMaterialization:
		return "materialization"
	case valueLogSyncPathExternalRef:
		return "external_ref"
	case valueLogSyncPathPendingBarrier:
		return "pending_barrier"
	case valueLogSyncPathCheckpoint:
		return "checkpoint"
	default:
		return "unknown"
	}
}

func (db *DB) observeValueLogSync(path valueLogSyncPath, waited, elapsed time.Duration, err error) {
	if db == nil || path >= valueLogSyncPathCount {
		return
	}
	db.valueLogSyncPathCalls[path].Add(1)
	if ns := elapsed.Nanoseconds(); ns > 0 {
		db.valueLogSyncPathNs[path].Add(uint64(ns))
	}
	if ns := waited.Nanoseconds(); ns > 0 {
		db.valueLogSyncPathWaitNs[path].Add(uint64(ns))
	}
	if err != nil {
		db.valueLogSyncPathErrors[path].Add(1)
	}
}

// recordValueLogMaterializationSyncCoverageMuHeld records the append-only
// writer boundary covered by a successful materialization sync. Callers hold
// l.vlogMu; reuse additionally requires the lane's sync reservation to remain
// held until the command-WAL external-reference ordering step.
func (db *DB) recordValueLogMaterializationSyncCoverageMuHeld(l *lane, w valueWriter) {
	if l == nil {
		return
	}
	l.vlogMaterializationSyncValid = false
	if db == nil || w == nil || l.id < 0 || l.vlogSeq <= 0 {
		return
	}
	fileID, err := valuelog.EncodeFileID(uint32(l.id), uint32(l.vlogSeq))
	if err != nil {
		return
	}
	size := w.Size()
	if size < 0 {
		return
	}
	l.vlogMaterializationSyncFileID = fileID
	l.vlogMaterializationSyncSeq = l.vlogSeq
	l.vlogMaterializationSyncSize = size
	l.vlogMaterializationSyncValid = true
}

func (db *DB) flushPendingValueLogLanes(sync bool, syncPath valueLogSyncPath) error {
	if db == nil || !db.splitValueLogEnabled() {
		return nil
	}
	actualSync := sync && !db.relaxedSync
	for i := range db.lanes {
		l := &db.lanes[i]
		if !l.vlogDirty.Load() && !(actualSync && l.vlogSyncPending.Load()) {
			continue
		}
		waitStart := time.Now()
		l.vlogMu.Lock()
		waited := time.Since(waitStart)
		w := l.vlog
		var err error
		syncBoundary := actualSync && l.vlogSyncPending.Load()
		if w != nil {
			if syncBoundary {
				start := time.Now()
				err = w.Sync()
				db.observeValueLogSync(syncPath, waited, time.Since(start), err)
			} else {
				err = w.Flush()
			}
		}
		if err == nil {
			l.vlogDirty.Store(false)
			if syncBoundary || db.relaxedSync {
				l.vlogSyncPending.Store(false)
			}
			l.backendReadFlushedSeq.Store(l.backendReadDirtySeq.Load())
		}
		l.vlogMu.Unlock()
		if err != nil {
			return err
		}
	}
	return nil
}

func (db *DB) checkpointFlushValueLogLanes() error {
	// Checkpoint is a durability boundary for cached mode. Ensure any buffered
	// value-log bytes are visible before publishing pointers durably to the backend.
	return db.flushPendingValueLogLanes(true, valueLogSyncPathCheckpoint)
}

func (db *DB) syncDirBestEffort(dir string, resource durabilitycut.Resource) {
	if dir == "" || runtime.GOOS == "windows" {
		return
	}
	reportObservationFailure := func(err error) {
		if err == nil {
			return
		}
		if resource == durabilitycut.ResourceCommandWAL {
			if marker, ok := db.backend.(interface{ MarkCommandWALRecoveryRequired() }); ok {
				marker.MarkCommandWALRecoveryRequired()
			}
		}
		db.reportError(errors.Join(err, backenddb.ErrRecoveryRequired))
	}
	if err := durabilitycut.EmitPath(durabilitycut.BeforeDeletionDirectorySync, resource, dir, dir); err != nil {
		reportObservationFailure(err)
		return
	}
	f, err := os.Open(dir)
	if err != nil {
		reportObservationFailure(fmt.Errorf("cachingdb: failed to open dir %q for sync: %w", dir, err))
		return
	}
	if err := f.Sync(); err != nil {
		reportObservationFailure(fmt.Errorf("cachingdb: failed to sync dir %q: %w", dir, err))
	} else {
		if err := durabilitycut.EmitPath(durabilitycut.AfterDeletionDirectorySync, resource, dir, dir); err != nil {
			reportObservationFailure(err)
		}
	}
	if err := f.Close(); err != nil {
		db.reportError(fmt.Errorf("cachingdb: failed to close dir %q after sync: %w", dir, err))
	}
}

func persistentLogResourceForPath(path string) durabilitycut.Resource {
	if _, _, valueLog, ok := parseLogSeq(filepath.Base(path)); ok && valueLog {
		if filepath.Base(filepath.Dir(filepath.Clean(path))) == "leaf_vlog" {
			return durabilitycut.ResourceOuterLeaf
		}
		return durabilitycut.ResourceValueLog
	}
	return durabilitycut.ResourceCommandWAL
}

func (db *DB) removeFileRetry(path string) error {
	var err error
	backoff := 25 * time.Millisecond
	for i := 0; i < 40; i++ {
		err = os.Remove(path)
		if err == nil {
			resource := persistentLogResourceForPath(path)
			if observeErr := durabilitycut.EmitNamespace(
				durabilitycut.NamespaceUnlink,
				resource,
				filepath.Dir(path),
				path,
				"",
			); observeErr != nil {
				if resource == durabilitycut.ResourceCommandWAL {
					if marker, ok := db.backend.(interface{ MarkCommandWALRecoveryRequired() }); ok {
						marker.MarkCommandWALRecoveryRequired()
					}
				}
				return errors.Join(observeErr, backenddb.ErrRecoveryRequired)
			}
			return nil
		}
		if os.IsNotExist(err) {
			return nil
		}
		if runtime.GOOS != "windows" {
			return err
		}
		if !isWindowsSharingViolationError(err) {
			return err
		}
		time.Sleep(backoff)
		if backoff < 200*time.Millisecond {
			backoff *= 2
		}
	}
	return err
}

func isWindowsSharingViolationError(err error) bool {
	if runtime.GOOS != "windows" || err == nil {
		return false
	}
	var pathErr *os.PathError
	if errors.As(err, &pathErr) && pathErr.Err != nil {
		err = pathErr.Err
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "sharing violation") || strings.Contains(msg, "used by another process")
}

func warnInsecureDir(dir string, notify func(error)) {
	if dir == "" || notify == nil || runtime.GOOS == "windows" {
		return
	}
	info, err := os.Lstat(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return
		}
		notify(fmt.Errorf("cachingdb: failed to stat dir %q: %w", dir, err))
		return
	}
	if info.Mode()&os.ModeSymlink != 0 {
		notify(fmt.Errorf("cachingdb: dir %q is a symlink; verify target permissions", dir))
		info, err = os.Stat(dir)
		if err != nil {
			notify(fmt.Errorf("cachingdb: failed to stat symlink target %q: %w", dir, err))
			return
		}
	}
	if !info.IsDir() {
		notify(fmt.Errorf("cachingdb: path %q is not a directory", dir))
		return
	}
	perms := info.Mode().Perm()
	if perms&0o002 != 0 {
		notify(fmt.Errorf("cachingdb: dir %q is world-writable (mode %o)", dir, perms))
	} else if perms&0o020 != 0 {
		notify(fmt.Errorf("cachingdb: dir %q is group-writable (mode %o)", dir, perms))
	}
}

func memtableCapacity(flushThreshold int64) int {
	if flushThreshold <= 0 {
		return 0
	}
	capBytes := flushThreshold + flushThreshold/4 // +25% to cover skiplist overhead.
	if capBytes < minMemtablePrealloc {
		capBytes = minMemtablePrealloc
	}
	if capBytes > maxMemtablePrealloc {
		capBytes = maxMemtablePrealloc
	}
	maxInt := int64(int(^uint(0) >> 1))
	if capBytes > maxInt {
		capBytes = maxInt
	}
	return int(capBytes)
}

func normalizeShardCount(n int) int {
	if n < 1 {
		return 1
	}
	// Round down to a power of two.
	v := 1
	for v<<1 <= n {
		v <<= 1
	}
	return v
}

func defaultMemtableShards() int {
	n := runtime.GOMAXPROCS(0)
	if n < 1 {
		n = 1
	}
	n *= 2
	if n > 16 {
		n = 16
	}
	return normalizeShardCount(n)
}

func shardCapacity(totalCap, shards int) int {
	if shards <= 1 {
		return totalCap
	}
	if totalCap <= 0 {
		return 1
	}
	cap := totalCap / shards
	if cap <= 0 {
		cap = 1
	}
	return cap
}

func (db *DB) valueLogEnabled() bool {
	return true
}

func (db *DB) splitValueLogEnabled() bool {
	return true
}

// ReserveValueLogRIDs reserves a contiguous RID range from the cached-mode
// shared allocator and returns the starting RID.
func (db *DB) ReserveValueLogRIDs(count int) (uint64, error) {
	if db == nil {
		return 0, fmt.Errorf("value-log rid allocator unavailable")
	}
	if count <= 0 {
		return 0, fmt.Errorf("value-log rid allocator requires positive count: count=%d", count)
	}
	need := uint64(count)
	for {
		cur := db.nextRID.Load()
		if need > (^uint64(0) - cur) {
			return 0, fmt.Errorf("value-log rid space exhausted")
		}
		next := cur + need
		if next == 0 || next < cur {
			return 0, fmt.Errorf("value-log rid space exhausted")
		}
		if db.nextRID.CompareAndSwap(cur, next) {
			return cur + 1, nil
		}
	}
}

func (db *DB) valueLogThresholdForKey(key []byte) int {
	if db == nil {
		return page.DefaultInlineThreshold
	}
	return backenddb.ResolveInlineThresholdForKey(db.valueLogThreshold, key, db.valueLogDomainThresholds)
}

func (db *DB) shouldWriteViaValueLogForKeyValue(key, value []byte) bool {
	if db == nil {
		return false
	}
	return db.forceValueLogPointers || len(value) > db.valueLogThresholdForKey(key)
}

// CommandWALPayloadShouldBypassForValue reports whether the public command-WAL
// wrapper should let cached write preflight promote this value to a value-log
// pointer before command-frame encoding.
func (db *DB) CommandWALPayloadShouldBypassForValue(key, value []byte) bool {
	if db == nil || len(value) == 0 || !db.valueLogEnabled() || !db.allowValueLogPointers() {
		return false
	}
	if db.disableJournal && !db.memtableValueLogPointers {
		return false
	}
	return db.shouldWriteViaValueLogForKeyValue(key, value)
}

type outerLeafRecordGroup struct {
	start int
	end   int
}

// buildOuterLeafValueRecords encodes key/value pairs into value-log records.
// The returned groups map each encoded record back to a contiguous source range
// [start,end).
func (db *DB) buildOuterLeafValueRecords(keys [][]byte, values [][]byte) ([]valuelog.Record, []outerLeafRecordGroup, []byte, error) {
	if len(keys) != len(values) {
		return nil, nil, nil, fmt.Errorf("cachingdb: outer-leaf key/value length mismatch %d/%d", len(keys), len(values))
	}
	if len(keys) == 0 {
		return nil, nil, nil, nil
	}

	records := getValueLogRecordsCap(len(keys))
	groups := make([]outerLeafRecordGroup, 0, len(keys))
	for i := range keys {
		records = append(records, valuelog.Record{Value: values[i]})
		groups = append(groups, outerLeafRecordGroup{start: i, end: i + 1})
	}
	return records, groups, nil, nil
}

type valueLogDictClassRange struct {
	start int
	end   int
	class vlogDictClass
}

func (db *DB) valueLogDictClassRangesForRecords(records []valuelog.Record) []valueLogDictClassRange {
	if len(records) == 0 {
		return nil
	}
	if db == nil || db.dictClassMode() != vlogDictClassModeSplitOuterLeaf {
		return []valueLogDictClassRange{{
			start: 0,
			end:   len(records),
			class: vlogDictClassSingleValue,
		}}
	}
	ranges := make([]valueLogDictClassRange, 0, 4)
	start := 0
	class := db.valueLogDictClassForValue(records[0].Value)
	for i := 1; i < len(records); i++ {
		nextClass := db.valueLogDictClassForValue(records[i].Value)
		if nextClass == class {
			continue
		}
		ranges = append(ranges, valueLogDictClassRange{
			start: start,
			end:   i,
			class: class,
		})
		start = i
		class = nextClass
	}
	ranges = append(ranges, valueLogDictClassRange{
		start: start,
		end:   len(records),
		class: class,
	})
	return ranges
}

func (db *DB) appendValueLogForRecords(l *lane, records []valuelog.Record, durability journalDurability) ([]page.ValuePtr, error) {
	if len(records) == 0 {
		return nil, nil
	}
	if db != nil && db.dictStore == nil {
		return db.appendValueLog(l, 0, nil, records, durability)
	}
	ranges := db.valueLogDictClassRangesForRecords(records)
	if len(ranges) == 0 {
		return nil, nil
	}
	resolveDictID := func(class vlogDictClass, cache *[vlogDictClassCount]uint64, cached *[vlogDictClassCount]bool) (uint64, error) {
		if db == nil || db.dictStore == nil {
			return 0, nil
		}
		classIdx := int(class)
		if classIdx < 0 || classIdx >= vlogDictClassCount {
			classIdx = int(vlogDictClassSingleValue)
			class = vlogDictClassSingleValue
		}
		if cached[classIdx] {
			return cache[classIdx], nil
		}
		id, err := db.currentDictIDForClass(context.Background(), class)
		if err != nil {
			return 0, err
		}
		cache[classIdx] = id
		cached[classIdx] = true
		return id, nil
	}

	var (
		dictIDCache  [vlogDictClassCount]uint64
		dictIDCached [vlogDictClassCount]bool
	)
	if len(ranges) == 1 {
		dictID, err := resolveDictID(ranges[0].class, &dictIDCache, &dictIDCached)
		if err != nil {
			return nil, err
		}
		return db.appendValueLog(l, dictID, nil, records, durability)
	}
	// Highly alternating class layouts can explode contiguous ranges and
	// degrade batching. Re-pack by class to bound append calls.
	if len(ranges) > 8 {
		var (
			classRecords [vlogDictClassCount][]valuelog.Record
			classIndexes [vlogDictClassCount][]int
		)
		for i := range ranges {
			r := ranges[i]
			classIdx := int(r.class)
			if classIdx < 0 || classIdx >= vlogDictClassCount {
				classIdx = int(vlogDictClassSingleValue)
			}
			classRecords[classIdx] = append(classRecords[classIdx], records[r.start:r.end]...)
			idxs := classIndexes[classIdx]
			for j := r.start; j < r.end; j++ {
				idxs = append(idxs, j)
			}
			classIndexes[classIdx] = idxs
		}
		ptrs := getValueLogPtrsCap(len(records))
		ptrs = ptrs[:len(records)]
		for classIdx := 0; classIdx < vlogDictClassCount; classIdx++ {
			recs := classRecords[classIdx]
			if len(recs) == 0 {
				continue
			}
			dictID, err := resolveDictID(vlogDictClass(classIdx), &dictIDCache, &dictIDCached)
			if err != nil {
				putValueLogPtrs(ptrs)
				return nil, err
			}
			segPtrs, err := db.appendValueLog(l, dictID, nil, recs, durability)
			if err != nil {
				putValueLogPtrs(ptrs)
				return nil, err
			}
			if len(segPtrs) != len(recs) {
				putValueLogPtrs(segPtrs)
				putValueLogPtrs(ptrs)
				return nil, fmt.Errorf("cachingdb: value-log segment returned %d ptrs for %d records", len(segPtrs), len(recs))
			}
			idxs := classIndexes[classIdx]
			for j := 0; j < len(segPtrs); j++ {
				ptrs[idxs[j]] = segPtrs[j]
			}
			putValueLogPtrs(segPtrs)
		}
		return ptrs, nil
	}

	ptrs := getValueLogPtrsCap(len(records))
	ptrs = ptrs[:len(records)]
	for i := range ranges {
		r := ranges[i]
		dictID, err := resolveDictID(r.class, &dictIDCache, &dictIDCached)
		if err != nil {
			putValueLogPtrs(ptrs)
			return nil, err
		}
		segPtrs, err := db.appendValueLog(l, dictID, nil, records[r.start:r.end], durability)
		if err != nil {
			putValueLogPtrs(ptrs)
			return nil, err
		}
		if len(segPtrs) != r.end-r.start {
			putValueLogPtrs(segPtrs)
			putValueLogPtrs(ptrs)
			return nil, fmt.Errorf("cachingdb: value-log segment returned %d ptrs for %d records", len(segPtrs), r.end-r.start)
		}
		copy(ptrs[r.start:r.end], segPtrs)
		putValueLogPtrs(segPtrs)
	}
	return ptrs, nil
}

func fallbackAutoVlogWriteMode(mode vlogCompressionMode, writeMode vlogCompressionWriteMode, allowDictFallback bool) vlogCompressionWriteMode {
	if writeMode != vlogWriteDict {
		return writeMode
	}
	if mode == vlogCompressionAuto {
		return vlogWriteBlock
	}
	if mode == vlogCompressionDict && allowDictFallback {
		return vlogWriteBlock
	}
	return writeMode
}

func lookupVlogDictBytes(dictID uint64, singleDictID uint64, singleDict []byte, dictByID map[uint64][]byte) []byte {
	if dictID == 0 {
		return nil
	}
	if dictByID == nil {
		if dictID == singleDictID {
			return singleDict
		}
		return nil
	}
	return dictByID[dictID]
}

func (db *DB) deferredValueLogEnabled() bool {
	if db == nil {
		return false
	}
	return false
}

// sumKeyValueBytes returns the total bytes across paired key/value entries.
// If keys and values differ in length, only the shared prefix is counted.
func sumKeyValueBytes(keys, values [][]byte) uint64 {
	if len(keys) == 0 || len(values) == 0 {
		return 0
	}
	if len(keys) > len(values) {
		keys = keys[:len(values)]
	} else if len(values) > len(keys) {
		values = values[:len(keys)]
	}
	var total uint64
	for i := 0; i < len(keys); i++ {
		total += uint64(len(keys[i]) + len(values[i]))
	}
	return total
}

func (db *DB) shouldFlushDeferredValueLog(writeMode vlogCompressionWriteMode, records []valuelog.Record) bool {
	return db != nil && db.deferredValueLogEnabled()
}

func (db *DB) shouldFlushDeferredValueLogValue(writeMode vlogCompressionWriteMode, value []byte) bool {
	return db != nil && db.deferredValueLogEnabled()
}

func (db *DB) walUsesValueLog() bool {
	return false
}

func (db *DB) needsVlogAutotuneTiming() bool {
	if db == nil {
		return false
	}
	if db.valueLogAutotuneOptions.Mode != valuelog.AutotuneOff {
		return true
	}
	return vlogAutotuneMetricsEnabled.Load()
}

func (db *DB) pickLane(sync bool, preferred int) (*lane, error) {
	if db == nil || len(db.lanes) == 0 {
		return nil, errWALUnavailable
	}
	if !sync && preferred >= 0 && preferred < len(db.lanes) {
		l := &db.lanes[preferred]
		if !l.syncing.Load() {
			return l, nil
		}
	}

	db.laneMu.Lock()
	defer db.laneMu.Unlock()
	for {
		select {
		case <-db.closeCh:
			return nil, errWALClosed
		default:
		}

		if preferred >= 0 && preferred < len(db.lanes) {
			l := &db.lanes[preferred]
			if !l.syncing.Load() {
				if sync {
					l.syncing.Store(true)
				}
				return l, nil
			}
			// If preferred lane is busy, we could wait or fallback.
			// To maintain strict lane-affinity, we wait.
			db.laneCond.Wait()
			continue
		}

		start := db.nextLane
		for i := 0; i < len(db.lanes); i++ {
			idx := (start + i) % len(db.lanes)
			l := &db.lanes[idx]
			if l.syncing.Load() {
				continue
			}
			db.nextLane = (idx + 1) % len(db.lanes)
			if sync {
				l.syncing.Store(true)
			}
			return l, nil
		}
		db.laneCond.Wait()
	}
}

func (db *DB) releaseLaneSync(l *lane) {
	if l == nil {
		return
	}
	if !l.syncing.CompareAndSwap(true, false) {
		return
	}
	db.laneMu.Lock()
	db.laneCond.Broadcast()
	db.laneMu.Unlock()
}

func (db *DB) valueLogDirForLane(l *lane) string {
	if db == nil {
		return ""
	}
	if db.isLeafLogAppendLane(l) && db.leafLogDir != "" {
		return db.leafLogDir
	}
	return db.valueLogDir
}

func (db *DB) valueLogLaneByID(laneID int) *lane {
	if db == nil || laneID < 0 {
		return nil
	}
	if laneID < len(db.lanes) {
		return &db.lanes[laneID]
	}
	if laneID == leafLogLaneID && db.indexOuterLeavesInValueLog {
		return &db.leafLog
	}
	return nil
}

func (db *DB) valueLogLaneForFileID(fileID uint32) *lane {
	if db == nil || fileID == 0 {
		return nil
	}
	laneID, seq := valuelog.DecodeFileID(fileID)
	if laneID != leafLogLaneID || !db.indexOuterLeavesInValueLog {
		return db.valueLogLaneByID(int(laneID))
	}
	if view := db.leafLogAppendLanesView.Load(); view != nil {
		for _, l := range *view {
			if db.leafLogAppendLaneMatchesSeq(l, seq) {
				return l
			}
		}
		return nil
	}
	for idx := 0; ; idx++ {
		l, ok := db.leafLogAppendLaneAtIndex(idx)
		if !ok {
			return nil
		}
		if db.leafLogAppendLaneMatchesSeq(l, seq) {
			return l
		}
	}
}

func (db *DB) leafLogAppendLaneMatchesSeq(l *lane, seq uint32) bool {
	if l == nil {
		return false
	}
	l.vlogMu.Lock()
	matches := l.vlogSeq == int(seq) && (l.vlogPath != "" || l.vlog != nil)
	l.vlogMu.Unlock()
	return matches
}

func (db *DB) leafLogAppendLaneAtIndex(idx int) (*lane, bool) {
	if db == nil || !db.indexOuterLeavesInValueLog || idx < 0 {
		return nil, false
	}
	db.leafLogAppendMu.RLock()
	defer db.leafLogAppendMu.RUnlock()
	if len(db.leafLogAppendLanes) == 0 {
		if idx == 0 {
			return &db.leafLog, true
		}
		return nil, false
	}
	if idx >= len(db.leafLogAppendLanes) {
		return nil, false
	}
	return db.leafLogAppendLanes[idx], true
}

func (db *DB) isLeafLogAppendLane(l *lane) bool {
	if db == nil || !db.indexOuterLeavesInValueLog || l == nil || l.id != leafLogLaneID {
		return false
	}
	if l == &db.leafLog {
		return true
	}
	db.leafLogAppendMu.RLock()
	defer db.leafLogAppendMu.RUnlock()
	for _, lane := range db.leafLogAppendLanes {
		if lane == l {
			return true
		}
	}
	return false
}

func (db *DB) leafLogAppendCompressionSelector() *vlogCompressionSelector {
	if db == nil || !db.indexOuterLeavesInValueLog {
		return nil
	}
	seedCodec := db.valueLogBlockCodec
	if normalizeVlogCompressionMode(db.valueLogCompressionMode) == vlogCompressionAuto && normalizeVlogAutoPolicy(db.valueLogAutoPolicy) != vlogAutoThroughput {
		seedCodec = valuelog.BlockCodecLZ4
	}
	return newVlogCompressionSelectorWithSeed(
		normalizeVlogAutoPolicy(db.valueLogAutoPolicy),
		uint64(db.valueLogIncompressibleHold),
		uint64(db.valueLogIncompressibleProbe),
		seedCodec,
	)
}

func (db *DB) initLeafLogAppendState(maxLeafVlogSeq int) {
	if db == nil || !db.indexOuterLeavesInValueLog {
		return
	}
	db.leafLogAppendMu.Lock()
	defer db.leafLogAppendMu.Unlock()
	db.leafLogAppendSeq.Store(uint32(maxLeafVlogSeq))
	db.leafLogAppendLanes = []*lane{&db.leafLog}
	db.publishLeafLogAppendLanesLocked()
}

func (db *DB) publishLeafLogAppendLanesLocked() {
	if db == nil || !db.indexOuterLeavesInValueLog || len(db.leafLogAppendLanes) == 0 {
		return
	}
	view := append([]*lane(nil), db.leafLogAppendLanes...)
	db.leafLogAppendLanesView.Store(&view)
}

func (db *DB) leafLogAppendLanesSnapshot() []*lane {
	if db == nil || !db.indexOuterLeavesInValueLog {
		return nil
	}
	db.leafLogAppendMu.RLock()
	defer db.leafLogAppendMu.RUnlock()
	if len(db.leafLogAppendLanes) == 0 {
		return []*lane{&db.leafLog}
	}
	return append([]*lane(nil), db.leafLogAppendLanes...)
}

func (db *DB) leafLogAppendLaneForWorkerIndex(workerIndex int) *lane {
	if db == nil || !db.indexOuterLeavesInValueLog {
		return nil
	}
	if workerIndex <= 0 {
		return &db.leafLog
	}
	db.leafLogAppendMu.Lock()
	if len(db.leafLogAppendLanes) == 0 {
		db.leafLogAppendLanes = []*lane{&db.leafLog}
	}
	for len(db.leafLogAppendLanes) <= workerIndex {
		db.leafLogAppendLanes = append(db.leafLogAppendLanes, nil)
	}
	l := db.leafLogAppendLanes[workerIndex]
	if l == nil {
		l = &lane{
			id:                      leafLogLaneID,
			vlogGenerationClass:     db.leafLog.vlogGenerationClass,
			vlogCompressionSelector: db.leafLogAppendCompressionSelector(),
			vlogSeq:                 int(db.leafLogAppendSeq.Load()),
		}
		db.startVlogWriter(l)
		db.leafLogAppendLanes[workerIndex] = l
		db.publishLeafLogAppendLanesLocked()
	}
	db.leafLogAppendMu.Unlock()
	return l
}

func (db *DB) advanceLeafLogAppendSeqAtLeast(seq int) {
	if db == nil || !db.indexOuterLeavesInValueLog || seq <= 0 {
		return
	}
	need := uint32(seq)
	for {
		cur := db.leafLogAppendSeq.Load()
		if cur >= need {
			return
		}
		if db.leafLogAppendSeq.CompareAndSwap(cur, need) {
			return
		}
	}
}

func (db *DB) advanceCompactStorageLeafPageLogSeqAtLeast(seq uint32) error {
	if db == nil || !db.indexOuterLeavesInValueLog || seq == 0 {
		return nil
	}
	observedMaxSeq := int(seq)
	db.advanceLeafLogAppendSeqAtLeast(observedMaxSeq)
	for _, l := range db.leafLogAppendLanesSnapshot() {
		if err := db.advanceLeafLogAppendWriterPastObservedSeq(l, observedMaxSeq); err != nil {
			return err
		}
	}
	return nil
}

func (db *DB) nextLeafLogAppendSeq() (int, error) {
	if db == nil || !db.indexOuterLeavesInValueLog {
		return 0, errWALUnavailable
	}
	for {
		cur := db.leafLogAppendSeq.Load()
		next := cur + 1
		if next <= cur {
			return 0, fmt.Errorf("cachingdb: leaf log sequence space exhausted")
		}
		if _, err := valuelog.EncodeFileID(uint32(leafLogLaneID), next); err != nil {
			if errors.Is(err, valuelog.ErrSegmentIDRange) {
				return 0, fmt.Errorf("cachingdb: leaf log sequence space exhausted")
			}
			return 0, err
		}
		if db.leafLogAppendSeq.CompareAndSwap(cur, next) {
			return int(next), nil
		}
	}
}

func (db *DB) closeLeafValueLogLane(l *lane) error {
	if db == nil || l == nil {
		return nil
	}
	l.vlogMu.Lock()
	defer l.vlogMu.Unlock()
	if l.vlog != nil {
		if err := l.vlog.Close(); err != nil {
			return err
		}
		l.vlog = nil
	}
	l.vlogCaps = vlogWriterCaps{}
	l.vlogLiveBytes.Store(0)
	l.vlogModeSet = false
	l.vlogModeWriter = nil
	return nil
}

func (db *DB) currentValueLogPath(l *lane) string {
	if l == nil {
		return ""
	}
	if db.splitValueLogEnabled() {
		l.vlogMu.Lock()
		path := l.vlogPath
		l.vlogMu.Unlock()
		return path
	}
	l.walMu.Lock()
	path := l.walPath
	l.walMu.Unlock()
	return path
}

func (db *DB) currentValueLogSeq(l *lane) int {
	if l == nil {
		return 0
	}
	if db.splitValueLogEnabled() {
		l.vlogMu.Lock()
		seq := l.vlogSeq
		l.vlogMu.Unlock()
		return seq
	}
	l.walMu.Lock()
	seq := l.walSeq
	l.walMu.Unlock()
	return seq
}

func (db *DB) currentWALPaths() []string {
	if db == nil || db.disableJournal {
		return nil
	}
	paths := make([]string, 0, len(db.lanes))
	for i := range db.lanes {
		l := &db.lanes[i]
		l.walMu.Lock()
		if l.walPath != "" {
			paths = append(paths, l.walPath)
		}
		l.walMu.Unlock()
	}
	return paths
}

func (db *DB) currentValueLogPaths() []string {
	if db == nil || !db.valueLogEnabled() {
		return nil
	}
	paths := make([]string, 0, len(db.lanes)+1)
	for i := range db.lanes {
		l := &db.lanes[i]
		if db.splitValueLogEnabled() {
			l.vlogMu.Lock()
			if l.vlogPath != "" {
				paths = append(paths, l.vlogPath)
			}
			l.vlogMu.Unlock()
			continue
		}
		l.walMu.Lock()
		if l.walPath != "" {
			paths = append(paths, l.walPath)
		}
		l.walMu.Unlock()
	}
	if db.indexOuterLeavesInValueLog && db.splitValueLogEnabled() {
		for _, l := range db.leafLogAppendLanesSnapshot() {
			if l == nil {
				continue
			}
			l.vlogMu.Lock()
			if l.vlogPath != "" {
				paths = append(paths, l.vlogPath)
			}
			l.vlogMu.Unlock()
		}
	}
	return paths
}

func (db *DB) deferValueLogOps(ops []batch.Entry, sync bool) ([]batch.Entry, error) {
	if db == nil || len(ops) == 0 || !db.deferredValueLogEnabled() {
		return ops, nil
	}
	durability := journalDurabilityNone
	if sync {
		if db.relaxedSync {
			durability = journalDurabilityFlush
		} else {
			durability = journalDurabilitySync
		}
	}
	return db.rewriteValueLogOpsForBackend(ops, durability)
}

func (db *DB) prepareBypassValueLogOps(ops []batch.Entry, sync bool) ([]batch.Entry, error) {
	if db == nil || len(ops) == 0 || !db.allowValueLogPointers() {
		return ops, nil
	}
	durability := journalDurabilityFlush
	if sync && !db.relaxedSync {
		durability = journalDurabilitySync
	}
	return db.rewriteValueLogOpsForBackend(ops, durability)
}

func (db *DB) rewriteValueLogOpsForBackend(ops []batch.Entry, durability journalDurability) ([]batch.Entry, error) {
	if db == nil || len(ops) == 0 {
		return ops, nil
	}
	if !db.allowValueLogPointers() {
		return ops, nil
	}

	eligible := getValueLogEligible(len(ops))
	defer putValueLogEligible(eligible)
	for i := range ops {
		op := &ops[i]
		if op.Type != batch.OpPut || op.IsPtr {
			continue
		}
		if !db.shouldWriteViaValueLogForKeyValue(op.Key, op.Value) {
			continue
		}
		eligible = append(eligible, i)
	}
	if len(eligible) == 0 {
		return ops, nil
	}

	lane, err := db.pickLane(false, -1)
	if err != nil {
		return nil, err
	}

	keys := getValueLogKeys(len(eligible))
	defer putValueLogKeys(keys)
	values := getValueLogKeys(len(eligible))
	defer putValueLogKeys(values)
	for _, idx := range eligible {
		op := &ops[idx]
		keys = append(keys, op.Key)
		values = append(values, op.Value)
	}
	records, groups, outerArena, err := db.buildOuterLeafValueRecords(keys, values)
	if err != nil {
		return nil, err
	}
	if len(records) == 0 {
		return ops, nil
	}
	startRID := db.nextRID.Add(uint64(len(records))) - uint64(len(records)) + 1
	for i := range records {
		records[i].RID = startRID + uint64(i)
	}
	ptrs, err := db.appendValueLogForRecords(lane, records, durability)
	if err != nil {
		putValueLogRecordsNoClear(records)
		putOuterLeafArena(outerArena)
		return nil, err
	}
	if len(ptrs) != len(records) {
		putValueLogPtrs(ptrs)
		putValueLogRecordsNoClear(records)
		putOuterLeafArena(outerArena)
		return nil, fmt.Errorf("cachingdb: deferred value-log returned %d ptrs for %d records", len(ptrs), len(records))
	}
	defer func() {
		putValueLogPtrs(ptrs)
		putValueLogRecordsNoClear(records)
		putOuterLeafArena(outerArena)
	}()

	for i := range groups {
		ptr := ptrs[i]
		group := groups[i]
		if group.start < 0 || group.end < group.start || group.end > len(eligible) {
			return nil, errors.New("cachingdb: deferred value-log group out of range")
		}
		for srcPos := group.start; srcPos < group.end; srcPos++ {
			idx := eligible[srcPos]
			op := &ops[idx]
			op.ValuePtr = ptr
			op.IsPtr = true
			op.Value = nil
		}
	}
	retainPath := db.currentValueLogPath(lane)
	if retainPath != "" {
		db.markValueLogRetain(retainPath)
	}
	if durability == journalDurabilityNone {
		db.backendReadVlogDirtySeq.Add(1)
	}
	return ops, nil
}

type backendBatchReserveHint interface {
	Reserve(int)
}

type physicalBackendBatchSizer interface {
	NewPhysicalBatchWithSize(size int) batch.Interface
}

type physicalBackendBatcher interface {
	NewPhysicalBatch() batch.Interface
}

type backendBatchSetViewer interface {
	SetView(key, value []byte) error
}

type backendBatchDeleteViewer interface {
	DeleteView(key []byte) error
}

type backendBatchPointerSetter interface {
	SetPointer(key []byte, ptr page.ValuePtr) error
}

type backendBatchPointerSetterView interface {
	SetPointerView(key []byte, ptr page.ValuePtr) error
}

type backendBatchSetRevision interface {
	SetWithRevision(key, value []byte, revision page.EntryRevision) error
}

type backendBatchSetViewRevision interface {
	SetViewWithRevision(key, value []byte, revision page.EntryRevision) error
}

type backendBatchDeleteRevision interface {
	DeleteWithRevision(key []byte, revision page.EntryRevision) error
}

type backendBatchDeleteViewRevision interface {
	DeleteViewWithRevision(key []byte, revision page.EntryRevision) error
}

type backendBatchPointerSetterRevision interface {
	SetPointerWithRevision(key []byte, ptr page.ValuePtr, revision page.EntryRevision) error
}

type backendBatchPointerSetterViewRevision interface {
	SetPointerViewWithRevision(key []byte, ptr page.ValuePtr, revision page.EntryRevision) error
}

type backendBatchRevisionOps struct {
	set     backendBatchSetRevision
	setView backendBatchSetViewRevision
	del     backendBatchDeleteRevision
	delView backendBatchDeleteViewRevision
	ptr     backendBatchPointerSetterRevision
	ptrView backendBatchPointerSetterViewRevision
}

func resolveBackendBatchRevisionOps(backendBatch batch.Interface) backendBatchRevisionOps {
	ops := backendBatchRevisionOps{}
	ops.set, _ = backendBatch.(backendBatchSetRevision)
	ops.setView, _ = backendBatch.(backendBatchSetViewRevision)
	ops.del, _ = backendBatch.(backendBatchDeleteRevision)
	ops.delView, _ = backendBatch.(backendBatchDeleteViewRevision)
	ops.ptr, _ = backendBatch.(backendBatchPointerSetterRevision)
	ops.ptrView, _ = backendBatch.(backendBatchPointerSetterViewRevision)
	return ops
}

type backendBatchCommandWALPublisher interface {
	SetCommandWALPublish(appliedLSN uint64, covered []backenddb.CommandWALLSNRange) error
}

func appendBackendBatchPointOp(
	backendBatch batch.Interface,
	op batch.Entry,
	stableView bool,
	sv backendBatchSetViewer,
	dv backendBatchDeleteViewer,
	psv backendBatchPointerSetterView,
	ps backendBatchPointerSetter,
	revOps backendBatchRevisionOps,
) error {
	if backendBatch == nil {
		return errors.New("cachingdb: missing backend batch")
	}
	if op.Revision != page.LegacyEntryRevision {
		switch {
		case op.Type == batch.OpDelete:
			if stableView && revOps.delView != nil {
				return revOps.delView.DeleteViewWithRevision(op.Key, op.Revision)
			}
			if revOps.del != nil {
				return revOps.del.DeleteWithRevision(op.Key, op.Revision)
			}
		case op.IsPtr:
			if stableView && revOps.ptrView != nil {
				return revOps.ptrView.SetPointerViewWithRevision(op.Key, op.ValuePtr, op.Revision)
			}
			if revOps.ptr != nil {
				return revOps.ptr.SetPointerWithRevision(op.Key, op.ValuePtr, op.Revision)
			}
		default:
			if stableView && revOps.setView != nil {
				return revOps.setView.SetViewWithRevision(op.Key, op.Value, op.Revision)
			}
			if revOps.set != nil {
				return revOps.set.SetWithRevision(op.Key, op.Value, op.Revision)
			}
		}
		if !stableView {
			op.Key = append([]byte(nil), op.Key...)
			if op.Type == batch.OpPut && !op.IsPtr && op.Value != nil {
				op.Value = append([]byte(nil), op.Value...)
			}
		}
		var single [1]batch.Entry
		single[0] = op
		return backendBatch.SetOps(single[:])
	}
	switch {
	case op.Type == batch.OpDelete:
		if stableView && dv != nil {
			return dv.DeleteView(op.Key)
		}
		return backendBatch.Delete(op.Key)
	case op.IsPtr:
		if stableView && psv != nil {
			return psv.SetPointerView(op.Key, op.ValuePtr)
		}
		if ps != nil {
			return ps.SetPointer(op.Key, op.ValuePtr)
		}
		if !stableView {
			op.Key = append([]byte(nil), op.Key...)
		}
		var single [1]batch.Entry
		single[0] = op
		return backendBatch.SetOps(single[:])
	default:
		if stableView && sv != nil {
			return sv.SetView(op.Key, op.Value)
		}
		return backendBatch.Set(op.Key, op.Value)
	}
}

type checkpointCommandWALPublish struct {
	appliedLSN uint64
	ranges     []backenddb.CommandWALLSNRange
	consumed   bool
}

func (p *checkpointCommandWALPublish) attach(backendBatch batch.Interface) (bool, error) {
	if p == nil || p.consumed || p.appliedLSN == 0 {
		return false, nil
	}
	publisher, ok := backendBatch.(backendBatchCommandWALPublisher)
	if !ok {
		return false, errors.New("cachingdb: backend batch cannot publish command wal applied lsn")
	}
	if err := publisher.SetCommandWALPublish(p.appliedLSN, p.ranges); err != nil {
		return false, err
	}
	return true, nil
}

func reserveBackendBatchOps(backendBatch batch.Interface, n int) {
	if backendBatch == nil || n <= 0 {
		return
	}
	if r, ok := backendBatch.(backendBatchReserveHint); ok {
		r.Reserve(n)
	}
}

func (db *DB) flushDeferredValueLogMemtable(
	iter iterator.UnsafeIterator,
	backendBatch batch.Interface,
	memLen int,
	sync bool,
	laneID int,
	stableUnsafe bool,
) (int, error) {
	if db == nil {
		return 0, nil
	}
	if iter == nil {
		return 0, nil
	}
	if backendBatch == nil {
		return 0, errors.New("cachingdb: missing backend batch")
	}

	allowPointers := db.allowValueLogPointers()

	sv, _ := backendBatch.(backendBatchSetViewer)
	dv, _ := backendBatch.(backendBatchDeleteViewer)
	psv, _ := backendBatch.(backendBatchPointerSetterView)
	ps, _ := backendBatch.(backendBatchPointerSetter)
	revOps := resolveBackendBatchRevisionOps(backendBatch)
	reserveHint := memLen
	if db.flushBackendMaxEntries > 0 && reserveHint > db.flushBackendMaxEntries {
		reserveHint = db.flushBackendMaxEntries
	}
	reserveBackendBatchOps(backendBatch, reserveHint)

	var ptrKeys [][]byte
	var ptrVals [][]byte
	var ptrRevisions []page.EntryRevision
	defer func() {
		putValueLogKeys(ptrKeys)
		putValueLogKeys(ptrVals)
	}()

	emittedOps := 0
	durability := journalDurabilityNone
	if sync {
		durability = journalDurabilitySync
	}

	vlogLane := (*lane)(nil)
	ensureVlogLane := func() error {
		if vlogLane != nil {
			return nil
		}
		l, err := db.pickLane(false, laneID)
		if err != nil {
			return err
		}
		vlogLane = l
		return nil
	}

	for iter.Valid() {
		key := iter.UnsafeKey()
		val, ptr, flags, revision := iterator.UnsafeEntryWithRevision(iter)
		if flags&node.FlagTombstone != 0 {
			op := batch.Entry{Type: batch.OpDelete, Key: key, Revision: revision}
			if err := appendBackendBatchPointOp(backendBatch, op, stableUnsafe, sv, dv, psv, ps, revOps); err != nil {
				return 0, err
			}
			emittedOps++
			iter.Next()
			continue
		}

		if flags&node.FlagPointer != 0 {
			op := batch.Entry{Type: batch.OpPut, Key: key, ValuePtr: ptr, IsPtr: true, Revision: revision}
			if err := appendBackendBatchPointOp(backendBatch, op, stableUnsafe, sv, dv, psv, ps, revOps); err != nil {
				return 0, err
			}
			emittedOps++
			iter.Next()
			continue
		}

		if val == nil && db.memtableValueLogPointers {
			return 0, errors.New("cachingdb: flush missing value-log ptr for key")
		}

		if allowPointers && db.shouldWriteViaValueLogForKeyValue(key, val) {
			if ptrKeys == nil {
				hint := memLen
				if hint <= 0 {
					hint = 16
				}
				if hint > db.flushBackendInitEntries {
					hint = db.flushBackendInitEntries
				}
				ptrKeys = getValueLogKeys(hint)
				ptrVals = getValueLogKeys(hint)
			}
			keyCopy := append([]byte(nil), key...)
			valCopy := append([]byte(nil), val...)
			ptrKeys = append(ptrKeys, keyCopy)
			ptrVals = append(ptrVals, valCopy)
			if revision != page.LegacyEntryRevision || ptrRevisions != nil {
				if ptrRevisions == nil {
					ptrRevisions = make([]page.EntryRevision, len(ptrKeys)-1, cap(ptrKeys))
				}
				ptrRevisions = append(ptrRevisions, revision)
			}
			iter.Next()
			continue
		}

		op := batch.Entry{Type: batch.OpPut, Key: key, Value: val, Revision: revision}
		if err := appendBackendBatchPointOp(backendBatch, op, stableUnsafe, sv, dv, psv, ps, revOps); err != nil {
			return 0, err
		}
		emittedOps++
		iter.Next()
	}

	if len(ptrKeys) == 0 {
		return emittedOps, nil
	}
	if !allowPointers {
		return emittedOps, nil
	}
	if len(ptrKeys) != len(ptrVals) {
		return 0, errors.New("cachingdb: internal deferred value-log mismatch")
	}
	if ptrRevisions != nil && len(ptrRevisions) != len(ptrKeys) {
		return 0, errors.New("cachingdb: internal deferred value-log revision mismatch")
	}
	if err := ensureVlogLane(); err != nil {
		return 0, err
	}

	records, groups, outerArena, err := db.buildOuterLeafValueRecords(ptrKeys, ptrVals)
	if err != nil {
		return 0, err
	}
	if len(records) == 0 {
		putValueLogRecordsNoClear(records)
		putOuterLeafArena(outerArena)
		return emittedOps, nil
	}
	defer putValueLogRecordsNoClear(records)
	defer putOuterLeafArena(outerArena)

	startRID := db.nextRID.Add(uint64(len(records))) - uint64(len(records)) + 1
	for i := range records {
		records[i].RID = startRID + uint64(i)
	}

	ptrs, err := db.appendValueLogForRecords(vlogLane, records, durability)
	if err != nil {
		return 0, err
	}
	if len(ptrs) != len(records) {
		putValueLogPtrs(ptrs)
		return 0, fmt.Errorf("cachingdb: deferred value-log returned %d ptrs for %d records", len(ptrs), len(records))
	}
	defer putValueLogPtrs(ptrs)

	if len(ptrs) != len(groups) {
		return 0, errors.New("cachingdb: deferred value-log group/pointer count mismatch")
	}
	for i := range groups {
		ptr := ptrs[i]
		group := groups[i]
		if group.start < 0 || group.end < group.start || group.end > len(ptrKeys) {
			return 0, errors.New("cachingdb: deferred value-log group out of range")
		}
		for srcPos := group.start; srcPos < group.end; srcPos++ {
			key := ptrKeys[srcPos]
			revision := page.LegacyEntryRevision
			if ptrRevisions != nil {
				revision = ptrRevisions[srcPos]
			}
			op := batch.Entry{Type: batch.OpPut, Key: key, ValuePtr: ptr, IsPtr: true, Revision: revision}
			if err := appendBackendBatchPointOp(backendBatch, op, true, sv, dv, psv, ps, revOps); err != nil {
				return 0, err
			}
			emittedOps++
		}
	}

	retainPath := db.currentValueLogPath(vlogLane)
	if retainPath != "" {
		db.markValueLogRetain(retainPath)
	}
	if durability == journalDurabilityNone {
		db.backendReadVlogDirtySeq.Add(1)
	}
	return emittedOps, nil
}

func (db *DB) flushDeferredValueLogUnits(units []flushUnit, backendBatch batch.Interface, sync bool, laneID int) (int, error) {
	if db == nil || len(units) == 0 {
		return 0, nil
	}
	if backendBatch == nil {
		return 0, errors.New("cachingdb: missing backend batch")
	}

	sv, _ := backendBatch.(backendBatchSetViewer)
	dv, _ := backendBatch.(backendBatchDeleteViewer)
	psv, _ := backendBatch.(backendBatchPointerSetterView)
	ps, _ := backendBatch.(backendBatchPointerSetter)
	revOps := resolveBackendBatchRevisionOps(backendBatch)

	chunkCap := db.flushBuildChunkCap
	if chunkCap <= 0 {
		chunkCap = 8192
	}
	const maxDeferredInlineGroupKeys = 32768

	unitRuns := getUnitRuns(len(units))
	defer func() {
		for i := range unitRuns {
			for _, run := range unitRuns[i] {
				putEntrySlice(run)
			}
			putEntryRuns(unitRuns[i])
		}
		putUnitRuns(unitRuns)
	}()
	for i := range units {
		runs, _, err := buildOpRuns(units[i].mem, chunkCap)
		if err != nil {
			return 0, err
		}
		unitRuns[i] = runs
	}

	heap := getOpMergeHeap(len(unitRuns))
	defer func() { putOpMergeHeap(heap) }()
	for i := range unitRuns {
		if len(unitRuns[i]) == 0 {
			continue
		}
		it := newOpRunIter(unitRuns[i])
		if !it.Valid() {
			continue
		}
		priority := len(unitRuns) - 1 - i
		heap = append(heap, opMergeItem{iter: it, priority: priority, key: it.Key()})
	}
	for i := len(heap)/2 - 1; i >= 0; i-- {
		(&heap).down(i, len(heap))
	}

	allowPointers := db.allowValueLogPointers()
	durability := journalDurabilityNone
	if sync {
		durability = journalDurabilitySync
	}

	ptrCap := estimateUnitRunEntries(unitRuns, chunkCap)
	reserveHint := ptrCap
	if db.flushBackendMaxEntries > 0 && reserveHint > db.flushBackendMaxEntries {
		reserveHint = db.flushBackendMaxEntries
	}
	reserveBackendBatchOps(backendBatch, reserveHint)
	if ptrCap > maxDeferredInlineGroupKeys {
		ptrCap = maxDeferredInlineGroupKeys
	}
	ptrKeys := getValueLogKeys(ptrCap)
	ptrVals := getValueLogKeys(ptrCap)
	var ptrRevisions []page.EntryRevision
	defer func() {
		putValueLogKeys(ptrKeys)
		putValueLogKeys(ptrVals)
	}()

	backendPendingOps := 0
	vlogLane := (*lane)(nil)
	ensureVlogLane := func() error {
		if vlogLane != nil {
			return nil
		}
		l, err := db.pickLane(false, laneID)
		if err != nil {
			return err
		}
		vlogLane = l
		return nil
	}

	emitPointer := func(key []byte, ptr page.ValuePtr, revision page.EntryRevision) error {
		op := batch.Entry{Type: batch.OpPut, Key: key, ValuePtr: ptr, IsPtr: true, Revision: revision}
		if err := appendBackendBatchPointOp(backendBatch, op, true, sv, dv, psv, ps, revOps); err != nil {
			return err
		}
		backendPendingOps++
		return nil
	}

	flushInlinePointerGroup := func() error {
		if len(ptrKeys) == 0 {
			return nil
		}
		if !allowPointers {
			ptrKeys = ptrKeys[:0]
			ptrVals = ptrVals[:0]
			if ptrRevisions != nil {
				ptrRevisions = ptrRevisions[:0]
			}
			return nil
		}
		if len(ptrKeys) != len(ptrVals) {
			return errors.New("cachingdb: deferred inline pointer grouping mismatch")
		}
		if ptrRevisions != nil && len(ptrRevisions) != len(ptrKeys) {
			return errors.New("cachingdb: deferred inline pointer revision mismatch")
		}
		if err := ensureVlogLane(); err != nil {
			return err
		}
		totalKeys := len(ptrKeys)
		for chunkStart := 0; chunkStart < totalKeys; chunkStart += maxDeferredInlineGroupKeys {
			chunkEnd := chunkStart + maxDeferredInlineGroupKeys
			if chunkEnd > totalKeys {
				chunkEnd = totalKeys
			}
			chunkKeys := ptrKeys[chunkStart:chunkEnd]
			chunkVals := ptrVals[chunkStart:chunkEnd]
			var chunkRevisions []page.EntryRevision
			if ptrRevisions != nil {
				chunkRevisions = ptrRevisions[chunkStart:chunkEnd]
			}

			records, groups, outerArena, err := db.buildOuterLeafValueRecords(chunkKeys, chunkVals)
			if err != nil {
				return err
			}
			if len(records) == 0 {
				putValueLogRecordsNoClear(records)
				putOuterLeafArena(outerArena)
				continue
			}

			startRID := db.nextRID.Add(uint64(len(records))) - uint64(len(records)) + 1
			for i := range records {
				records[i].RID = startRID + uint64(i)
			}

			ptrs, err := db.appendValueLogForRecords(vlogLane, records, durability)
			putValueLogRecordsNoClear(records)
			putOuterLeafArena(outerArena)
			if err != nil {
				return err
			}
			if len(ptrs) != len(records) {
				putValueLogPtrs(ptrs)
				return fmt.Errorf("cachingdb: deferred value-log returned %d ptrs for %d records", len(ptrs), len(records))
			}
			if len(ptrs) != len(groups) {
				putValueLogPtrs(ptrs)
				return errors.New("cachingdb: deferred inline pointer group/pointer count mismatch")
			}
			for i := range groups {
				ptr := ptrs[i]
				group := groups[i]
				if group.start < 0 || group.end < group.start || group.end > len(chunkKeys) {
					putValueLogPtrs(ptrs)
					return errors.New("cachingdb: deferred inline pointer source group out of range")
				}
				for srcPos := group.start; srcPos < group.end; srcPos++ {
					revision := page.LegacyEntryRevision
					if chunkRevisions != nil {
						revision = chunkRevisions[srcPos]
					}
					if err := emitPointer(chunkKeys[srcPos], ptr, revision); err != nil {
						putValueLogPtrs(ptrs)
						return err
					}
				}
			}
			putValueLogPtrs(ptrs)
			if durability == journalDurabilityNone {
				db.backendReadVlogDirtySeq.Add(1)
			}
		}

		ptrKeys = ptrKeys[:0]
		ptrVals = ptrVals[:0]
		if ptrRevisions != nil {
			ptrRevisions = ptrRevisions[:0]
		}
		return nil
	}

	shadowedOps := 0
	appliedOps := 0
	for len(heap) > 0 {
		top := heap.pop()
		currentKey := top.key

		for len(heap) > 0 {
			next := heap.peek()
			if next != nil && bytes.Equal(next.key, currentKey) {
				shadowed := heap.pop()
				shadowedOps++
				shadowed.iter.Next()
				if shadowed.iter.Valid() {
					shadowed.key = shadowed.iter.Key()
					heap.push(shadowed)
				}
				continue
			}
			break
		}

		entry := top.iter.Entry()
		switch {
		case entry.Type == batch.OpDelete:
			if err := flushInlinePointerGroup(); err != nil {
				return 0, err
			}
			if err := appendBackendBatchPointOp(backendBatch, entry, true, sv, dv, psv, ps, revOps); err != nil {
				return 0, err
			}
			backendPendingOps++
			appliedOps++
		case entry.IsPtr:
			if err := flushInlinePointerGroup(); err != nil {
				return 0, err
			}
			if err := emitPointer(entry.Key, entry.ValuePtr, entry.Revision); err != nil {
				return 0, err
			}
		default:
			if allowPointers && db.shouldWriteViaValueLogForKeyValue(entry.Key, entry.Value) {
				if len(ptrKeys) >= maxDeferredInlineGroupKeys {
					if err := flushInlinePointerGroup(); err != nil {
						return 0, err
					}
				}
				keyCopy := append([]byte(nil), entry.Key...)
				valCopy := append([]byte(nil), entry.Value...)
				ptrKeys = append(ptrKeys, keyCopy)
				ptrVals = append(ptrVals, valCopy)
				if entry.Revision != page.LegacyEntryRevision || ptrRevisions != nil {
					if ptrRevisions == nil {
						ptrRevisions = make([]page.EntryRevision, len(ptrKeys)-1, cap(ptrKeys))
					}
					ptrRevisions = append(ptrRevisions, entry.Revision)
				}
			} else {
				if err := flushInlinePointerGroup(); err != nil {
					return 0, err
				}
				if err := appendBackendBatchPointOp(backendBatch, entry, true, sv, dv, psv, ps, revOps); err != nil {
					return 0, err
				}
				backendPendingOps++
				appliedOps++
			}
		}

		top.iter.Next()
		if top.iter.Valid() {
			top.key = top.iter.Key()
			heap.push(top)
		}
	}

	if err := flushInlinePointerGroup(); err != nil {
		return 0, err
	}
	if vlogLane != nil {
		// Do not flush/sync the value-log lane here. flushLaneOnce performs one
		// flush boundary after value-log appends so we avoid redundant syscalls.
		retainPath := db.currentValueLogPath(vlogLane)
		if retainPath != "" {
			db.markValueLogRetain(retainPath)
		}
	}
	if shadowedOps > 0 {
		flushMergeShadowedOpsTotal.Add(uint64(shadowedOps))
		flushMergeDeferredShadowedOpsTotal.Add(uint64(shadowedOps))
		db.observeFlushSpanRunShadowedOps(shadowedOps)
	}
	if appliedOps > 0 {
		flushMergeAppliedOpsTotal.Add(uint64(appliedOps))
		flushMergeDeferredAppliedOpsTotal.Add(uint64(appliedOps))
	}
	return backendPendingOps, nil
}

// SetDictStore installs the dictionary store for current-ID freezing.
func (db *DB) SetDictStore(store DictStore) {
	if db == nil {
		return
	}
	db.dictStore = store
	if setter, ok := db.backend.(interface {
		SetStableDictionaryResourceProvider(backenddb.StableDictionaryResourceProvider)
	}); ok {
		provider, _ := store.(backenddb.StableDictionaryResourceProvider)
		setter.SetStableDictionaryResourceProvider(provider)
	}
	db.dictCurrentCached.Store(0)
	db.dictCurrentOps.Store(0)
	for class := 0; class < vlogDictClassCount; class++ {
		db.dictCurrentCachedByClass[class].Store(0)
		db.dictCurrentOpsByClass[class].Store(0)
	}
	if store != nil {
		globalCurrent := uint64(0)
		if dictID, err := store.GetCurrent(context.Background()); err == nil {
			db.dictCurrentCached.Store(dictID)
			db.dictCurrentCachedByClass[vlogDictClassSingleValue].Store(dictID)
			globalCurrent = dictID
		}
		if db.dictClassMode() == vlogDictClassModeSplitOuterLeaf {
			byClass, hasClassReader := store.(dictStoreCurrentByClass)
			_, hasClassWriter := store.(dictStoreWriterByClass)
			if hasClassReader && hasClassWriter {
				for class := 0; class < vlogDictClassCount; class++ {
					clampedClass := vlogDictClass(class)
					dictID, err := byClass.GetCurrentForClass(context.Background(), vlogDictClassSuffix(clampedClass))
					if err != nil {
						continue
					}
					if dictID == 0 {
						dictID = globalCurrent
					}
					if dictID == 0 {
						continue
					}
					db.dictCurrentCachedByClass[class].Store(dictID)
					if clampedClass == vlogDictClassSingleValue {
						db.dictCurrentCached.Store(dictID)
						globalCurrent = dictID
					}
				}
			}
		}
	}
	db.valueLogDictBytesMu.Lock()
	db.valueLogDictBytesID = 0
	db.valueLogDictBytes = nil
	db.valueLogDictBytesMu.Unlock()
	for i := range db.lanes {
		l := &db.lanes[i]
		l.vlogDictBytesMu.Lock()
		l.vlogDictBytes = nil
		l.vlogDictBytesMu.Unlock()
	}
	if db.valueLogReader != nil && store != nil {
		db.valueLogReader.SetDictLookup(func(dictID uint64) ([]byte, error) {
			return store.GetDictBytes(context.Background(), dictID)
		})
	}
	db.ensureValueLogDictTrainer()
}

// SetCommandWALCheckpointPublishHook installs an optional hook that lets a
// caller publish already-covered command-WAL LSNs in the same backend commit
// that Checkpoint uses for its root/sync boundary. Checkpoint may call the hook
// more than once when a piggyback attempt is prepared but not consumed; hook
// implementations must therefore be idempotent and safe to reinvoke within one
// checkpoint.
func (db *DB) SetCommandWALCheckpointPublishHook(h func(sync bool) (uint64, []backenddb.CommandWALLSNRange, error)) {
	if db == nil {
		return
	}
	if h == nil {
		db.commandWALCheckpointPublish.Store(nil)
		return
	}
	db.commandWALCheckpointPublish.Store(&commandWALCheckpointPublishHookBox{fn: h})
}

// SetCommandWALCheckpointCutoverHook installs an optional hook called while
// Checkpoint still holds the write cutover lock. Command-WAL publishers use it
// to cap AppliedCommandLSN publication to writes included in this checkpoint.
func (db *DB) SetCommandWALCheckpointCutoverHook(h func()) {
	if db == nil {
		return
	}
	if h == nil {
		db.commandWALCheckpointCutover.Store(nil)
		return
	}
	db.commandWALCheckpointCutover.Store(&commandWALCheckpointCutoverHookBox{fn: h})
}

// SetCommandWALCheckpointCleanupHook installs an optional hook called after a
// cached checkpoint has published command-WAL coverage.
func (db *DB) SetCommandWALCheckpointCleanupHook(h func(sync bool) error) {
	if db == nil {
		return
	}
	if h == nil {
		db.commandWALCheckpointCleanup.Store(nil)
		return
	}
	db.commandWALCheckpointCleanup.Store(&commandWALCheckpointCleanupHookBox{fn: h})
}

// SetStatsHook installs an optional stats decorator for outer wrappers that own
// counters not stored on the cached layer itself. The hook must not call
// DB.Stats.
func (db *DB) SetStatsHook(h func(map[string]string)) {
	if db == nil {
		return
	}
	if h == nil {
		db.statsHook.Store(nil)
		return
	}
	db.statsHook.Store(&statsHookBox{fn: h})
}

// SetTemplateStore installs the template store used for template compression.
func (db *DB) SetTemplateStore(store template.Store) {
	if db == nil {
		return
	}
	db.templateStore = store
	if db.valueLogReader != nil && store != nil {
		db.valueLogReader.SetTemplateLookup(func(templateID uint64) ([]byte, error) {
			return db.templateLookup(context.Background(), templateID)
		}, db.valueLogTemplateDecodeOpts)
	}
}

func (db *DB) templateLookup(ctx context.Context, templateID uint64) ([]byte, error) {
	if templateID == 0 {
		return nil, valuelog.ErrMissingTemplate
	}
	if db == nil || db.templateStore == nil {
		return nil, valuelog.ErrMissingTemplate
	}
	defBytes, err := db.templateStore.GetTemplateDef(ctx, templateID)
	if err != nil {
		return nil, err
	}
	return defBytes, nil
}

func (db *DB) currentDictID(ctx context.Context) (uint64, error) {
	return db.currentDictIDForClass(ctx, vlogDictClassSingleValue)
}

func (db *DB) currentDictIDForClass(ctx context.Context, class vlogDictClass) (uint64, error) {
	if db == nil || db.dictStore == nil {
		return 0, nil
	}
	const refreshEvery = uint64(1 << 16)
	clampedClass := class
	classIdx := int(clampedClass)
	if classIdx < 0 || classIdx >= vlogDictClassCount {
		clampedClass = vlogDictClassSingleValue
		classIdx = int(clampedClass)
	}
	if db.dictClassMode() == vlogDictClassModeSplitOuterLeaf {
		byClass, hasClassReader := db.dictStore.(dictStoreCurrentByClass)
		_, hasClassWriter := db.dictStore.(dictStoreWriterByClass)
		if hasClassReader && hasClassWriter {
			seq := db.dictCurrentOpsByClass[classIdx].Add(1)
			if seq&(refreshEvery-1) != 0 {
				return db.dictCurrentCachedByClass[classIdx].Load(), nil
			}
			dictID, err := byClass.GetCurrentForClass(ctx, vlogDictClassSuffix(clampedClass))
			if err != nil {
				// Fall back to cached value on transient errors (best-effort).
				return db.dictCurrentCachedByClass[classIdx].Load(), nil
			}
			if dictID == 0 {
				// Class marker can legitimately be unset; refresh legacy global current.
				globalDictID, globalErr := db.dictStore.GetCurrent(ctx)
				if globalErr != nil {
					dictID = db.dictCurrentCached.Load()
				} else {
					dictID = globalDictID
					db.dictCurrentCached.Store(globalDictID)
					db.dictCurrentCachedByClass[vlogDictClassSingleValue].Store(globalDictID)
				}
			}
			db.dictCurrentCachedByClass[classIdx].Store(dictID)
			if clampedClass == vlogDictClassSingleValue {
				db.dictCurrentCached.Store(dictID)
			}
			return dictID, nil
		}
	}
	// Avoid per-write dictdb reads on the hot path; refresh every N uses.
	seq := db.dictCurrentOps.Add(1)
	if seq&(refreshEvery-1) != 0 {
		return db.dictCurrentCached.Load(), nil
	}
	dictID, err := db.dictStore.GetCurrent(ctx)
	if err != nil {
		// Fall back to cached value on transient errors (best-effort).
		return db.dictCurrentCached.Load(), nil
	}
	db.dictCurrentCached.Store(dictID)
	db.dictCurrentCachedByClass[classIdx].Store(dictID)
	db.dictCurrentCachedByClass[vlogDictClassSingleValue].Store(dictID)
	return dictID, nil
}

func (db *DB) dictBytes(ctx context.Context, dictID uint64) ([]byte, error) {
	if dictID == 0 {
		return nil, nil
	}
	if db == nil || db.dictStore == nil {
		return nil, valuelog.ErrMissingDict
	}
	db.valueLogDictBytesMu.Lock()
	if db.valueLogDictBytesID == dictID && len(db.valueLogDictBytes) > 0 {
		out := db.valueLogDictBytes
		db.valueLogDictBytesMu.Unlock()
		return out, nil
	}
	db.valueLogDictBytesMu.Unlock()

	out, err := db.dictStore.GetDictBytes(ctx, dictID)
	if err != nil {
		return nil, err
	}
	db.valueLogDictBytesMu.Lock()
	db.valueLogDictBytesID = dictID
	db.valueLogDictBytes = out
	db.valueLogDictBytesMu.Unlock()
	return out, nil
}

func (db *DB) dictBytesForLane(ctx context.Context, l *lane, dictID uint64) ([]byte, error) {
	if dictID == 0 {
		return nil, nil
	}
	if l == nil {
		return db.dictBytes(ctx, dictID)
	}
	l.vlogDictBytesMu.RLock()
	if l.vlogDictBytes != nil {
		if b, ok := l.vlogDictBytes[dictID]; ok && len(b) > 0 {
			l.vlogDictBytesMu.RUnlock()
			return b, nil
		}
	}
	l.vlogDictBytesMu.RUnlock()

	out, err := db.dictBytes(ctx, dictID)
	if err != nil {
		return nil, err
	}
	if len(out) == 0 {
		return out, nil
	}
	l.vlogDictBytesMu.Lock()
	if l.vlogDictBytes == nil {
		l.vlogDictBytes = make(map[uint64][]byte)
	}
	if len(l.vlogDictBytes) >= 32 {
		clear(l.vlogDictBytes)
	}
	l.vlogDictBytes[dictID] = out
	l.vlogDictBytesMu.Unlock()
	return out, nil
}

func (db *DB) templateCompressionEnabled() bool {
	return db != nil && db.valueLogTemplateEnabled && db.valueLogTemplateEngine != nil && db.templateStore != nil
}

func (db *DB) valueLogTemplateEncodeRecords(records []valuelog.Record) ([]valuelog.Record, bool) {
	if !db.templateCompressionEnabled() || len(records) == 0 {
		return records, false
	}
	engine := db.valueLogTemplateEngine
	store := db.templateStore
	encoded := records
	used := false
	for i := range records {
		payload, ok := engine.Encode(nil, records[i].Value, store)
		if ok {
			if !used {
				encoded = make([]valuelog.Record, len(records))
				copy(encoded, records)
				used = true
			}
			encoded[i].Value = payload
		}
	}
	return encoded, used
}

func (db *DB) readValueLog(key []byte, ptr page.ValuePtr) ([]byte, error) {
	if db.valueLogReader == nil {
		return nil, errors.New("cachingdb: value-log reader unavailable")
	}
	if !page.IsValueLogFileID(ptr.FileID) {
		return nil, fmt.Errorf("cachingdb: non value-log pointer %#x", ptr.FileID)
	}
	if db.valueLogEnabled() {
		if err := db.flushValueLogForPtr(ptr); err != nil {
			return nil, err
		}
	}
	return db.valueLogReader.Read(ptr)
}

func (db *DB) readValueLogUnsafe(key []byte, ptr page.ValuePtr) ([]byte, error) {
	if db.valueLogReader == nil {
		return nil, errors.New("cachingdb: value-log reader unavailable")
	}
	if !page.IsValueLogFileID(ptr.FileID) {
		return nil, fmt.Errorf("cachingdb: non value-log pointer %#x", ptr.FileID)
	}
	if db.valueLogEnabled() {
		if err := db.flushValueLogForPtr(ptr); err != nil {
			return nil, err
		}
	}
	return db.valueLogReader.ReadUnsafe(ptr)
}

func (db *DB) readValueLogAppend(key []byte, ptr page.ValuePtr, dst []byte) ([]byte, error) {
	if db.valueLogReader == nil {
		return nil, errors.New("cachingdb: value-log reader unavailable")
	}
	if !page.IsValueLogFileID(ptr.FileID) {
		return nil, fmt.Errorf("cachingdb: non value-log pointer %#x", ptr.FileID)
	}
	if db.valueLogEnabled() {
		if err := db.flushValueLogForPtr(ptr); err != nil {
			return nil, err
		}
	}
	return db.valueLogReader.ReadAppend(ptr, dst)
}

func (db *DB) flushValueLogForPtr(ptr page.ValuePtr) error {
	_, err := db.flushValueLogForFileIDWithSize(ptr.FileID)
	return err
}

func (db *DB) flushValueLogForFileIDWithSize(fileID uint32) (int64, error) {
	if !db.valueLogEnabled() {
		return -1, nil
	}
	_, seq := valuelog.DecodeFileID(fileID)
	l := db.valueLogLaneForFileID(fileID)
	if l == nil {
		return -1, nil
	}
	currentSeq := db.currentValueLogSeq(l)
	if currentSeq == int(seq) {
		return db.flushValueLogLaneWithSize(l)
	}
	return -1, nil
}

func (db *DB) flushValueLog(laneIDs ...int) error {
	if !db.valueLogEnabled() {
		return nil
	}
	if len(laneIDs) == 0 {
		for i := range db.lanes {
			if err := db.flushValueLogLane(&db.lanes[i]); err != nil {
				return err
			}
		}
		return nil
	}

	seen := make(map[int]struct{}, len(laneIDs))
	for _, id := range laneIDs {
		if id < 0 || id >= len(db.lanes) {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		if err := db.flushValueLogLane(&db.lanes[id]); err != nil {
			return err
		}
	}
	return nil
}

// flushValueLogForBackendRead makes value-log bytes visible to backend reads
// once pointer-bearing backend keys may already reference them. This matters
// even when deferred value-log mode is disabled: durability-none grouped
// appends can leave the current segment tail buffered in-process while backend
// keys already point at those records.
func (db *DB) flushValueLogForBackendRead() error {
	if db == nil || !db.valueLogEnabled() {
		return nil
	}
	dirtySeq := db.backendReadVlogDirtySeq.Load()
	if dirtySeq == 0 || dirtySeq == db.backendReadVlogFlushedSeq.Load() {
		return nil
	}
	if err := db.flushValueLog(); err != nil {
		return err
	}
	db.backendReadVlogFlushedSeq.Store(dirtySeq)
	return nil
}

type valueLogReadBarrierSetter interface {
	SetCurrentValueLogReadBarrier(func(fileID uint32) error)
}

type valueLogReadBarrierWithSizeSetter interface {
	SetCurrentValueLogReadBarrierWithSize(func(fileID uint32) (int64, error))
}

func backendValueLogReadBarrierKey(backend any) uintptr {
	if backend == nil {
		return 0
	}
	v := reflect.ValueOf(backend)
	if !v.IsValid() {
		return 0
	}
	switch v.Kind() {
	case reflect.Pointer, reflect.UnsafePointer:
		return v.Pointer()
	default:
		return 0
	}
}

func registerBackendValueLogReadBarrierDB(key uintptr, db *DB) {
	if key == 0 || db == nil {
		return
	}
	backendValueLogReadBarrierRegistryMu.Lock()
	owners := backendValueLogReadBarrierRegistry[key]
	if owners == nil {
		owners = &backendValueLogReadBarrierOwners{
			set: make(map[*DB]struct{}),
		}
		backendValueLogReadBarrierRegistry[key] = owners
	}
	if _, exists := owners.set[db]; !exists {
		owners.set[db] = struct{}{}
		rebuildBackendValueLogReadBarrierSnapshot(owners)
	}
	backendValueLogReadBarrierRegistryMu.Unlock()
}

func unregisterBackendValueLogReadBarrierDB(key uintptr, db *DB) int {
	if key == 0 || db == nil {
		return 0
	}
	backendValueLogReadBarrierRegistryMu.Lock()
	defer backendValueLogReadBarrierRegistryMu.Unlock()
	owners := backendValueLogReadBarrierRegistry[key]
	if owners == nil {
		return 0
	}
	delete(owners.set, db)
	if len(owners.set) == 0 {
		delete(backendValueLogReadBarrierRegistry, key)
		return 0
	}
	rebuildBackendValueLogReadBarrierSnapshot(owners)
	return len(owners.snapshot)
}

func rebuildBackendValueLogReadBarrierSnapshot(owners *backendValueLogReadBarrierOwners) {
	if owners == nil {
		return
	}
	if len(owners.set) == 0 {
		owners.snapshot = nil
		return
	}
	snapshot := make([]*DB, 0, len(owners.set))
	for db := range owners.set {
		snapshot = append(snapshot, db)
	}
	owners.snapshot = snapshot
}

func snapshotBackendValueLogReadBarrierDBs(key uintptr) []*DB {
	if key == 0 {
		return nil
	}
	backendValueLogReadBarrierRegistryMu.Lock()
	owners := backendValueLogReadBarrierRegistry[key]
	var dbs []*DB
	if owners != nil && len(owners.snapshot) > 0 {
		dbs = owners.snapshot
	}
	backendValueLogReadBarrierRegistryMu.Unlock()
	return dbs
}

func dispatchBackendValueLogReadBarrierWithSize(key uintptr, fileID uint32) (int64, error) {
	dbs := snapshotBackendValueLogReadBarrierDBs(key)
	if len(dbs) == 0 {
		return -1, nil
	}
	_, seq := valuelog.DecodeFileID(fileID)
	var firstErr error
	flushedAny := false
	size := int64(-1)
	sizeSafe := len(dbs) == 1
	for _, db := range dbs {
		if db == nil || db.closing.Load() {
			continue
		}
		l := db.valueLogLaneForFileID(fileID)
		if l == nil {
			continue
		}
		// Reads against sealed segments do not need a lane flush barrier.
		if db.currentValueLogSeq(l) != int(seq) {
			continue
		}
		if l.backendReadDirtySeq.Load() == l.backendReadFlushedSeq.Load() {
			continue
		}
		flushedSize, err := db.flushValueLogLaneWithSize(l)
		if err != nil {
			if errors.Is(err, errWALUnavailable) {
				continue
			}
			if firstErr == nil {
				firstErr = err
			}
			continue
		}
		if sizeSafe {
			size = flushedSize
		}
		flushedAny = true
	}
	if flushedAny {
		return size, nil
	}
	return -1, firstErr
}

func dispatchBackendValueLogReadBarrier(key uintptr, fileID uint32) error {
	_, err := dispatchBackendValueLogReadBarrierWithSize(key, fileID)
	return err
}

func (db *DB) installBackendValueLogReadBarrier() {
	if db == nil {
		return
	}
	if barrierSetter, ok := db.backend.(valueLogReadBarrierWithSizeSetter); ok {
		key := backendValueLogReadBarrierKey(db.backend)
		if key == 0 {
			barrierSetter.SetCurrentValueLogReadBarrierWithSize(func(fileID uint32) (int64, error) {
				return db.flushValueLogForFileIDWithSize(fileID)
			})
			return
		}
		registerBackendValueLogReadBarrierDB(key, db)
		barrierSetter.SetCurrentValueLogReadBarrierWithSize(func(fileID uint32) (int64, error) {
			return dispatchBackendValueLogReadBarrierWithSize(key, fileID)
		})
		return
	}
	barrierSetter, ok := db.backend.(valueLogReadBarrierSetter)
	if !ok {
		return
	}
	key := backendValueLogReadBarrierKey(db.backend)
	if key == 0 {
		barrierSetter.SetCurrentValueLogReadBarrier(func(fileID uint32) error {
			_, err := db.flushValueLogForFileIDWithSize(fileID)
			return err
		})
		return
	}
	registerBackendValueLogReadBarrierDB(key, db)
	barrierSetter.SetCurrentValueLogReadBarrier(func(fileID uint32) error {
		return dispatchBackendValueLogReadBarrier(key, fileID)
	})
}

func (db *DB) clearBackendValueLogReadBarrier() {
	if db == nil {
		return
	}
	if barrierSetter, ok := db.backend.(valueLogReadBarrierWithSizeSetter); ok {
		key := backendValueLogReadBarrierKey(db.backend)
		if key == 0 {
			barrierSetter.SetCurrentValueLogReadBarrierWithSize(nil)
			return
		}
		if remaining := unregisterBackendValueLogReadBarrierDB(key, db); remaining == 0 {
			barrierSetter.SetCurrentValueLogReadBarrierWithSize(nil)
		}
		return
	}
	barrierSetter, ok := db.backend.(valueLogReadBarrierSetter)
	if !ok {
		return
	}
	key := backendValueLogReadBarrierKey(db.backend)
	if key == 0 {
		barrierSetter.SetCurrentValueLogReadBarrier(nil)
		return
	}
	if remaining := unregisterBackendValueLogReadBarrierDB(key, db); remaining == 0 {
		barrierSetter.SetCurrentValueLogReadBarrier(nil)
	}
}

func (db *DB) syncValueLog(laneIDs ...int) error {
	if !db.valueLogEnabled() {
		return nil
	}
	if len(laneIDs) == 0 {
		for i := range db.lanes {
			if err := db.syncValueLogLane(&db.lanes[i]); err != nil {
				return err
			}
		}
		return nil
	}

	seen := make(map[int]struct{}, len(laneIDs))
	for _, id := range laneIDs {
		if id < 0 || id >= len(db.lanes) {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		if err := db.syncValueLogLane(&db.lanes[id]); err != nil {
			return err
		}
	}
	return nil
}

func (db *DB) flushValueLogLane(l *lane) error {
	_, err := db.flushValueLogLaneWithSize(l)
	return err
}

func (db *DB) flushValueLogLaneWithSize(l *lane) (int64, error) {
	if l == nil {
		return -1, errWALUnavailable
	}
	if db.splitValueLogEnabled() {
		waitStart := time.Now()
		l.vlogMu.Lock()
		waited := time.Since(waitStart)
		w := l.vlog
		if w == nil {
			l.vlogMu.Unlock()
			return -1, nil
		}
		// Always take vlogMu first so flush acts as a write barrier for in-flight appends.
		if !l.vlogDirty.Load() {
			if pending, ok := w.(interface{ PendingBytes() int }); !ok || pending.PendingBytes() == 0 {
				size := w.Size()
				l.vlogMu.Unlock()
				return size, nil
			}
		}
		start := time.Now()
		err := w.Flush()
		if db.testOnVlogFlush != nil {
			db.testOnVlogFlush(int(l.id))
		}
		db.debugVlogTiming("vlog_flush", int(l.id), "vlogMu", waited, time.Since(start))
		if err == nil {
			l.vlogDirty.Store(false)
			if db.relaxedSync {
				l.vlogSyncPending.Store(false)
			}
			l.backendReadFlushedSeq.Store(l.backendReadDirtySeq.Load())
		}
		size := int64(-1)
		if err == nil {
			size = w.Size()
		}
		l.vlogMu.Unlock()
		return size, err
	}
	waitStart := time.Now()
	l.walMu.Lock()
	waited := time.Since(waitStart)
	w := l.wal
	if w == nil {
		l.walMu.Unlock()
		return -1, errWALUnavailable
	}
	start := time.Now()
	err := w.Flush()
	if db.testOnVlogFlush != nil {
		db.testOnVlogFlush(int(l.id))
	}
	db.debugVlogTiming("wal_flush", int(l.id), "walMu", waited, time.Since(start))
	if err == nil {
		l.backendReadFlushedSeq.Store(l.backendReadDirtySeq.Load())
	}
	size := int64(-1)
	if err == nil {
		size = w.Size()
	}
	l.walMu.Unlock()
	return size, err
}

func (db *DB) syncValueLogLane(l *lane) error {
	if l == nil {
		return errWALUnavailable
	}
	if db.splitValueLogEnabled() {
		waitStart := time.Now()
		l.vlogMu.Lock()
		waited := time.Since(waitStart)
		w := l.vlog
		if w == nil {
			l.vlogMu.Unlock()
			return nil
		}
		start := time.Now()
		err := w.Sync()
		elapsed := time.Since(start)
		db.observeValueLogSync(valueLogSyncPathExternalRef, waited, elapsed, err)
		if db.testOnVlogSync != nil {
			db.testOnVlogSync(int(l.id))
		}
		db.debugVlogTiming("vlog_sync", int(l.id), "vlogMu", waited, elapsed)
		if err == nil {
			l.vlogDirty.Store(false)
			l.vlogSyncPending.Store(false)
			l.backendReadFlushedSeq.Store(l.backendReadDirtySeq.Load())
		}
		l.vlogMu.Unlock()
		return err
	}
	waitStart := time.Now()
	l.walMu.Lock()
	waited := time.Since(waitStart)
	w := l.wal
	if w == nil {
		l.walMu.Unlock()
		return errWALUnavailable
	}
	start := time.Now()
	err := w.Sync()
	if db.testOnVlogSync != nil {
		db.testOnVlogSync(int(l.id))
	}
	db.debugVlogTiming("wal_sync", int(l.id), "walMu", waited, time.Since(start))
	if err == nil {
		l.backendReadFlushedSeq.Store(l.backendReadDirtySeq.Load())
	}
	l.walMu.Unlock()
	return err
}

func (db *DB) logSegmentPrefix(laneID int) string {
	return fmt.Sprintf("commit-l%d-", laneID)
}

func (db *DB) markValueLogRetain(path string) {
	if path == "" {
		return
	}
	db.valueLogMu.Lock()
	if db.valueLogRetain == nil {
		db.valueLogRetain = make(map[string]struct{})
	}
	db.valueLogRetain[path] = struct{}{}
	db.valueLogMu.Unlock()
}

func (db *DB) forgetValueLogRetain(path string) {
	if path == "" {
		return
	}
	db.valueLogMu.Lock()
	if db.valueLogRetain != nil {
		delete(db.valueLogRetain, path)
	}
	db.valueLogMu.Unlock()
}

func (db *DB) cleanupMissingRetainedValueLog(path string) bool {
	if path == "" {
		return false
	}
	if _, err := os.Stat(path); err == nil || !os.IsNotExist(err) {
		return false
	}
	db.dropValueLogSegment(path)
	db.mu.Lock()
	db.untrackValueLogSegmentLocked(path)
	db.mu.Unlock()
	db.forgetValueLogRetain(path)
	return true
}

func (db *DB) cleanupOrphanedRetainedValueLog(path string) bool {
	return db.cleanupOrphanedRetainedValueLogExpected(path, rootpublication.StableIdentity{})
}

func (db *DB) cleanupOrphanedRetainedValueLogExpected(path string, expected rootpublication.StableIdentity) bool {
	if path == "" || db.valueLogReader == nil {
		return false
	}
	laneID, seq, valueLog, ok := parseLogSeq(filepath.Base(path))
	if !ok || !valueLog || laneID < 0 {
		return false
	}
	id, err := valuelog.EncodeFileID(uint32(laneID), uint32(seq))
	if err != nil {
		return false
	}
	if err := db.valueLogReader.RegisterSegment(path, id); err != nil {
		if os.IsNotExist(err) {
			return db.cleanupMissingRetainedValueLog(path)
		}
		return false
	}
	var removeErr error
	if expected != (rootpublication.StableIdentity{}) {
		removeErr = db.valueLogReader.RemoveSegmentExpectedIdentity(id, expected)
	} else {
		removeErr = db.valueLogReader.RemoveSegment(id)
	}
	if removeErr != nil {
		return false
	}
	if _, err := os.Stat(path); err == nil || !os.IsNotExist(err) {
		return false
	}
	db.mu.Lock()
	db.untrackValueLogSegmentLocked(path)
	db.mu.Unlock()
	db.forgetValueLogRetain(path)
	db.syncDirBestEffort(filepath.Dir(path), persistentLogResourceForPath(path))
	return true
}

func (db *DB) dropValueLogSegment(path string) {
	if db.valueLogReader == nil || path == "" {
		return
	}
	laneID, seq, valueLog, ok := parseLogSeq(filepath.Base(path))
	if !ok || !valueLog {
		return
	}
	if laneID < 0 {
		return
	}
	id, err := valuelog.EncodeFileID(uint32(laneID), uint32(seq))
	if err != nil {
		return
	}
	_ = db.valueLogReader.RemoveSegment(id)
}

func (db *DB) valueLogRetained(path string) bool {
	if path == "" {
		return false
	}
	db.valueLogMu.Lock()
	defer db.valueLogMu.Unlock()
	_, retained := db.valueLogRetain[path]
	return retained
}

func (db *DB) valueLogRetainedStats() (segments int, bytes int64) {
	stats := db.valueLogRetainedStatsDetailed()
	return stats.SegmentsTotal, stats.BytesTotal
}

type valueLogRetainedGenerationStats struct {
	SegmentsTotal int
	SegmentsHot   int
	SegmentsWarm  int
	SegmentsCold  int
	BytesTotal    int64
	BytesHot      int64
	BytesWarm     int64
	BytesCold     int64
}

func (db *DB) valueLogRetainedStatsDetailed() valueLogRetainedGenerationStats {
	var out valueLogRetainedGenerationStats
	db.valueLogMu.Lock()
	if len(db.valueLogRetain) == 0 {
		db.valueLogMu.Unlock()
		return out
	}
	paths := make([]string, 0, len(db.valueLogRetain))
	for path := range db.valueLogRetain {
		paths = append(paths, path)
	}
	db.valueLogMu.Unlock()

	pathSizes := make(map[string]int64)
	currentSizes := make(map[string]int64)
	pathClasses := make(map[string]uint8)
	if db.splitValueLogEnabled() {
		for i := range db.lanes {
			l := &db.lanes[i]
			l.vlogMu.Lock()
			for path, size := range l.vlogClosedSizes {
				pathSizes[path] = size
				pathClasses[path] = l.vlogGenerationClass
			}
			if l.vlogPath != "" {
				currentSizes[l.vlogPath] = l.vlogLiveBytes.Load()
				pathClasses[l.vlogPath] = l.vlogGenerationClass
			}
			l.vlogMu.Unlock()
		}
		if db.indexOuterLeavesInValueLog {
			for _, l := range db.leafLogAppendLanesSnapshot() {
				if l == nil {
					continue
				}
				l.vlogMu.Lock()
				for path, size := range l.vlogClosedSizes {
					pathSizes[path] = size
					pathClasses[path] = l.vlogGenerationClass
				}
				if l.vlogPath != "" {
					currentSizes[l.vlogPath] = l.vlogLiveBytes.Load()
					pathClasses[l.vlogPath] = l.vlogGenerationClass
				}
				l.vlogMu.Unlock()
			}
		}
	} else {
		for i := range db.lanes {
			l := &db.lanes[i]
			l.walMu.Lock()
			for path, size := range l.walClosedSizes {
				pathSizes[path] = size
			}
			if l.walPath != "" {
				currentSizes[l.walPath] = l.walLiveBytes.Load()
			}
			l.walMu.Unlock()
		}
	}

	for _, path := range paths {
		out.SegmentsTotal++
		class := pathClasses[path]
		switch class {
		case vlogGenerationClassWarm:
			out.SegmentsWarm++
		case vlogGenerationClassCold:
			out.SegmentsCold++
		default:
			out.SegmentsHot++
		}
		size := int64(0)
		if v, ok := currentSizes[path]; ok {
			size = v
		} else if v, ok := pathSizes[path]; ok {
			size = v
		}
		out.BytesTotal += size
		switch class {
		case vlogGenerationClassWarm:
			out.BytesWarm += size
		case vlogGenerationClassCold:
			out.BytesCold += size
		default:
			out.BytesHot += size
		}
	}
	return out
}

func (db *DB) valueLogRetainedPaths() []string {
	db.valueLogMu.Lock()
	if len(db.valueLogRetain) == 0 {
		db.valueLogMu.Unlock()
		return nil
	}
	paths := make([]string, 0, len(db.valueLogRetain))
	for path := range db.valueLogRetain {
		paths = append(paths, path)
	}
	db.valueLogMu.Unlock()
	return paths
}

// ValueLogRetainedPaths returns a best-effort snapshot of retained value-log
// segment paths currently pinned by cached-mode pointer lifecycle tracking.
func (db *DB) ValueLogRetainedPaths() []string {
	return db.valueLogRetainedPaths()
}

// PruneRetainedValueLogsForMaintenance runs a synchronous retained value-log
// prune before full backend maintenance computes reclaim candidates.
func (db *DB) PruneRetainedValueLogsForMaintenance() {
	if db == nil || !db.valueLogEnabled() {
		return
	}
	for {
		db.waitForRetainedValueLogPrune()
		if _, ran := db.runRetainedValueLogPruneInline(true, nil); ran {
			return
		}
		db.retainedPruneMu.Lock()
		done := db.retainedPruneDone
		closing := db.closing.Load()
		db.retainedPruneMu.Unlock()
		if closing || done == nil {
			return
		}
		<-done
	}
}

func mergeUniqueNonEmptyStrings(pathSets ...[]string) []string {
	seen := make(map[string]struct{})
	var out []string
	for _, paths := range pathSets {
		for _, path := range paths {
			if path == "" {
				continue
			}
			if _, ok := seen[path]; ok {
				continue
			}
			seen[path] = struct{}{}
			out = append(out, path)
		}
	}
	return out
}

func (db *DB) isLeafValueLogPath(path string) bool {
	if db == nil || !db.indexOuterLeavesInValueLog || db.leafLogDir == "" || path == "" {
		return false
	}
	return filepath.Clean(filepath.Dir(path)) == filepath.Clean(db.leafLogDir)
}

func (db *DB) valueOnlyLogPaths(paths []string) []string {
	if len(paths) == 0 {
		return nil
	}
	if db == nil || !db.indexOuterLeavesInValueLog {
		return append([]string(nil), paths...)
	}
	out := make([]string, 0, len(paths))
	for _, path := range paths {
		if path == "" || db.isLeafValueLogPath(path) {
			continue
		}
		out = append(out, path)
	}
	return out
}

func (db *DB) valueLogGCProtectedPathSets() (retained []string, inUse []string, merged []string) {
	retained = db.valueOnlyLogPaths(db.valueLogRetainedPaths())
	inUse = db.valueOnlyLogPaths(db.valueLogInUsePaths())
	merged = mergeUniqueNonEmptyStrings(retained, inUse)
	return retained, inUse, merged
}

func (db *DB) valueLogProtectedPaths() []string {
	_, _, merged := db.valueLogGCProtectedPathSets()
	return merged
}

// ValueLogProtectedPaths returns value-log segment paths that online backend
// maintenance must protect while this cached DB is live. The set includes
// retained pointer-lifecycle paths plus current/queued in-use writer paths.
func (db *DB) ValueLogProtectedPaths() []string {
	return db.valueLogProtectedPaths()
}

// ValueLogInUsePaths returns value-log segment paths currently backing cached
// mutable/queued writer state. It excludes retained lifecycle paths so callers
// that already hold a writer fence can still reclaim independently proven
// unreachable retained sources.
func (db *DB) ValueLogInUsePaths() []string {
	return db.valueOnlyLogPaths(db.valueLogInUsePaths())
}

// ReclaimObservedValueLogSources rotates cached writers past rewrite-selected
// source segments and reclaims storage classes that backend rewrite already
// proved obsolete.
func (db *DB) ReclaimObservedValueLogSources(ctx context.Context, ids []uint32) (backenddb.ValueLogGCStats, error) {
	var stats backenddb.ValueLogGCStats
	if db == nil || len(ids) == 0 {
		return stats, nil
	}
	gcer, hasValueLogGC := db.backend.(backendValueLogGCer)
	leafGcer, hasLeafGenerationGC := db.backend.(backendLeafGenerationGCRunner)
	if !hasValueLogGC && !hasLeafGenerationGC {
		return stats, nil
	}
	seen := make(map[uint32]struct{}, len(ids))
	observed := make([]uint32, 0, len(ids))
	for _, id := range ids {
		if id == 0 {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		observed = append(observed, id)
	}
	if len(observed) == 0 {
		return stats, nil
	}

	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return stats, err
	}
	// Rotate cached writers off any observed source before the final checkpoint.
	// The checkpoint can then publish late cached writes, and the revalidation
	// below prevents active reclaim if those writes re-reference a source.
	finishRotateFence, err := db.BeginValueLogMaintenanceFence(ctx)
	if err != nil {
		return stats, err
	}
	finishRotateFence()
	if err := db.Checkpoint(); err != nil {
		return stats, err
	}
	finishFence, err := db.BeginValueLogMaintenanceFence(ctx)
	if err != nil {
		return stats, err
	}
	defer finishFence()
	if refresher, ok := db.backend.(valueLogSetRefresher); ok {
		if err := refresher.RefreshValueLogSet(); err != nil {
			return stats, err
		}
	}
	reclaimIDs, err := db.revalidateUnreferencedObservedValueLogSources(ctx, gcer, observed)
	if err != nil {
		return stats, err
	}
	reclaimSeen := make(map[uint32]struct{}, len(reclaimIDs))
	for _, id := range reclaimIDs {
		reclaimSeen[id] = struct{}{}
	}
	pruneStats, _ := db.runRetainedValueLogPruneInline(true, reclaimSeen)
	pruneReclaimedSegments := pruneStats.ObservedSourceRemovedSegments + pruneStats.ObservedSourceZombieMarkedSegments
	pruneReclaimedBytes := pruneStats.ObservedSourceRemovedBytes + pruneStats.ObservedSourceZombieMarkedBytes
	if pruneReclaimedSegments > 0 {
		stats.SegmentsDeleted += pruneReclaimedSegments
		stats.ObservedSourceSegmentsDeleted += pruneReclaimedSegments
	}
	if pruneReclaimedBytes > 0 {
		stats.BytesDeleted += pruneReclaimedBytes
		stats.ObservedSourceBytesDeleted += pruneReclaimedBytes
	}

	if hasValueLogGC && len(reclaimIDs) > 0 {
		opts := db.valueLogGCOptionsForObservedSources(false, reclaimSeen)
		opts.ObservedSourceFileIDs = reclaimIDs
		opts.ObservedSourceAssumeUnreferenced = true
		opts.ObservedSourceReclaimActive = true
		gcStats, err := gcer.ValueLogGC(ctx, opts)
		if err != nil {
			return stats, err
		}
		gcStats.SegmentsDeleted += stats.SegmentsDeleted
		gcStats.BytesDeleted += stats.BytesDeleted
		gcStats.ObservedSourceSegmentsDeleted += stats.ObservedSourceSegmentsDeleted
		gcStats.ObservedSourceBytesDeleted += stats.ObservedSourceBytesDeleted
		stats = gcStats
	}
	if stats.ObservedSourceSegmentsDeleted > 0 {
		db.cleanupMissingObservedValueLogRetains(seen)
	}
	if hasLeafGenerationGC {
		if _, err := leafGcer.LeafGenerationGC(ctx, db.leafGenerationGCOptions()); err != nil {
			return stats, err
		}
	}
	return stats, nil
}

func (db *DB) revalidateUnreferencedObservedValueLogSources(ctx context.Context, gcer backendValueLogGCer, observed []uint32) ([]uint32, error) {
	if db == nil || gcer == nil || len(observed) == 0 {
		return nil, nil
	}
	opts := db.valueLogGCOptions(false)
	opts.DryRun = true
	opts.ObservedSourceFileIDs = observed
	audit, err := gcer.ValueLogGC(ctx, opts)
	if err != nil {
		return nil, err
	}
	if audit.ObservedSourceSegmentsReferenced == 0 {
		return observed, nil
	}
	out := make([]uint32, 0, len(observed))
	for _, id := range observed {
		opts := db.valueLogGCOptions(false)
		opts.DryRun = true
		opts.ObservedSourceFileIDs = []uint32{id}
		audit, err := gcer.ValueLogGC(ctx, opts)
		if err != nil {
			return nil, err
		}
		if audit.ObservedSourceSegments > 0 && audit.ObservedSourceSegmentsReferenced == 0 {
			out = append(out, id)
		}
	}
	return out, nil
}

func (db *DB) cleanupMissingObservedValueLogRetains(observed map[uint32]struct{}) {
	if db == nil || len(observed) == 0 {
		return
	}
	for _, path := range db.valueOnlyLogPaths(db.valueLogRetainedPaths()) {
		if id, ok := valueLogFileIDForPath(path); ok {
			if _, keep := observed[id]; keep {
				db.cleanupMissingRetainedValueLog(path)
			}
		}
	}
}

// BeginValueLogMaintenanceFence blocks cached writers and rotates current
// value-log writers so backend maintenance can reclaim formerly active
// unreachable segments without racing mutable cached state.
func (db *DB) BeginValueLogMaintenanceFence(ctx context.Context) (func(), error) {
	if db == nil {
		return func() {}, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	db.writeMu.Lock()
	unlock := func() {
		db.writeMu.Unlock()
	}
	if !db.splitValueLogEnabled() {
		return unlock, nil
	}
	for i := range db.lanes {
		if err := ctx.Err(); err != nil {
			unlock()
			return nil, err
		}
		l := &db.lanes[i]
		l.vlogMu.Lock()
		if l.vlogPath != "" {
			db.markValueLogRetain(l.vlogPath)
			err := db.rotateValueLogMuHeld(l)
			l.vlogMu.Unlock()
			if err != nil {
				unlock()
				return nil, err
			}
			continue
		}
		l.vlogMu.Unlock()
	}
	if db.indexOuterLeavesInValueLog {
		for _, l := range db.leafLogAppendLanesSnapshot() {
			if l == nil {
				continue
			}
			l.vlogMu.Lock()
			if l.vlogPath != "" {
				db.markValueLogRetain(l.vlogPath)
				err := db.rotateValueLogMuHeld(l)
				l.vlogMu.Unlock()
				if err != nil {
					unlock()
					return nil, err
				}
				continue
			}
			l.vlogMu.Unlock()
		}
	}
	return unlock, nil
}

func (db *DB) rotateObservedValueLogSources(ctx context.Context, ids map[uint32]struct{}) error {
	if db == nil || len(ids) == 0 || !db.splitValueLogEnabled() {
		return nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	db.writeMu.Lock()
	defer db.writeMu.Unlock()
	for i := range db.lanes {
		if err := ctx.Err(); err != nil {
			return err
		}
		l := &db.lanes[i]
		l.vlogMu.Lock()
		if l.vlogPath == "" || l.vlogSeq <= 0 {
			l.vlogMu.Unlock()
			continue
		}
		fileID, err := valuelog.EncodeFileID(uint32(l.id), uint32(l.vlogSeq))
		if err == nil {
			if _, ok := ids[fileID]; ok {
				err = db.rotateValueLogMuHeld(l)
			}
		}
		l.vlogMu.Unlock()
		if err != nil {
			return err
		}
	}
	return nil
}

func (db *DB) valueLogGCOptions(dryRun bool) backenddb.ValueLogGCOptions {
	retained, inUse, merged := db.valueLogGCProtectedPathSets()
	return backenddb.ValueLogGCOptions{
		DryRun:                 dryRun,
		ProtectedPaths:         merged,
		ProtectedInUsePaths:    inUse,
		ProtectedRetainedPaths: retained,
	}
}

func (db *DB) valueLogGCOptionsForObservedSources(dryRun bool, observed map[uint32]struct{}) backenddb.ValueLogGCOptions {
	retained, inUse, _ := db.valueLogGCProtectedPathSets()
	if len(observed) > 0 {
		retained = filterObservedValueLogPaths(retained, observed)
		inUse = filterObservedValueLogPaths(inUse, observed)
	}
	merged := mergeUniqueNonEmptyStrings(retained, inUse)
	return backenddb.ValueLogGCOptions{
		DryRun:                 dryRun,
		ProtectedPaths:         merged,
		ProtectedInUsePaths:    inUse,
		ProtectedRetainedPaths: retained,
	}
}

func filterObservedValueLogPaths(paths []string, observed map[uint32]struct{}) []string {
	if len(paths) == 0 || len(observed) == 0 {
		return paths
	}
	out := make([]string, 0, len(paths))
	for _, path := range paths {
		if id, ok := valueLogFileIDForPath(path); ok {
			if _, drop := observed[id]; drop {
				continue
			}
		}
		out = append(out, path)
	}
	return out
}

func valueLogFileIDForPath(path string) (uint32, bool) {
	laneID, seq, valueLog, ok := parseLogSeq(filepath.Base(path))
	if !ok || !valueLog || laneID < 0 || seq < 0 {
		return 0, false
	}
	id, err := valuelog.EncodeFileID(uint32(laneID), uint32(seq))
	if err != nil {
		return 0, false
	}
	return id, true
}

func (db *DB) leafGenerationGCOptions() backenddb.LeafGenerationGCOptions {
	protectedRootIDs, protectedSystemRootIDs := db.publishedLeafGenerationProtectionIDs()
	return backenddb.LeafGenerationGCOptions{
		ProtectedRootIDs:       protectedRootIDs,
		ProtectedSystemRootIDs: protectedSystemRootIDs,
	}
}

func (db *DB) ProtectedLeafGenerationRootIDs() []uint64 {
	protectedRootIDs, _ := db.publishedLeafGenerationProtectionIDs()
	return protectedRootIDs
}

func (db *DB) ProtectedLeafGenerationSystemRootIDs() []uint64 {
	_, protectedSystemRootIDs := db.publishedLeafGenerationProtectionIDs()
	return protectedSystemRootIDs
}

func (db *DB) ProtectedLeafGenerationRootIDPair() ([]uint64, []uint64) {
	return db.publishedLeafGenerationProtectionIDs()
}

func (db *DB) publishedLeafGenerationProtectionIDs() ([]uint64, []uint64) {
	rootIDs, systemRootIDs, _ := db.publishedLeafGenerationProtectionSnapshot()
	return rootIDs, systemRootIDs
}

func (db *DB) publishedLeafGenerationProtectionSnapshot() ([]uint64, []uint64, uint64) {
	if db == nil {
		return nil, nil, 0
	}
	db.mu.RLock()
	published := clonePublishedRootSet(db.rootPublishedSet)
	version := db.rootDomainVersion.Load()
	db.mu.RUnlock()
	return publishedRootSetRootIDs(published), publishedRootSetSystemRootIDs(published), version
}

func publishedRootSetRootIDs(set *publishedRootSet) []uint64 {
	if set == nil {
		return nil
	}
	roots := make([]uint64, 0, len(set.pointShards)+2)
	var seen map[uint64]struct{}
	add := func(rootID uint64) {
		if rootID == 0 {
			return
		}
		if seen == nil {
			seen = make(map[uint64]struct{}, len(set.pointShards)+2)
		}
		if _, ok := seen[rootID]; ok {
			return
		}
		seen[rootID] = struct{}{}
		roots = append(roots, rootID)
	}
	for i := range set.pointShards {
		add(set.pointShards[i].rootID)
	}
	add(set.system.rootID)
	add(set.iterator.rootID)
	return roots
}

func publishedRootSetSystemRootIDs(set *publishedRootSet) []uint64 {
	if set == nil || set.system.rootID == 0 {
		return nil
	}
	return []uint64{set.system.rootID}
}

// valueLogInUsePaths returns a best-effort snapshot of value-log segment paths
// that may be referenced by in-memory state (mutable + queued memtables).
//
// This is intentionally narrower than valueLogRetainedPaths: retained paths can
// include segments that are still referenced in the backend index (and thus
// candidates for rewrite), while in-use paths are only about protecting against
// concurrent writers while online maintenance is running.
func (db *DB) valueLogInUsePaths() []string {
	if db == nil || !db.valueLogEnabled() {
		return nil
	}
	inUse := make(map[string]struct{})
	if db.splitValueLogEnabled() {
		for _, path := range db.currentValueLogPaths() {
			if path == "" {
				continue
			}
			inUse[path] = struct{}{}
		}
		db.mu.RLock()
		for _, paths := range db.queueValueLogPaths {
			for _, path := range paths {
				if path == "" {
					continue
				}
				inUse[path] = struct{}{}
			}
		}
		db.mu.RUnlock()
	} else {
		for _, path := range db.currentWALPaths() {
			if path == "" {
				continue
			}
			inUse[path] = struct{}{}
		}
		db.mu.RLock()
		for _, paths := range db.queueWALPaths {
			for _, path := range paths {
				if path == "" {
					continue
				}
				inUse[path] = struct{}{}
			}
		}
		db.mu.RUnlock()
	}
	if len(inUse) == 0 {
		return nil
	}
	out := make([]string, 0, len(inUse))
	for path := range inUse {
		out = append(out, path)
	}
	sort.Strings(out)
	return out
}

// ReadValueLogRecord reads a raw value-log record for diagnostics and tooling.
func (db *DB) ReadValueLogRecord(ptr page.ValuePtr) ([]byte, error) {
	if db == nil || db.valueLogReader == nil {
		return nil, fmt.Errorf("cachingdb: value-log reader unavailable")
	}
	return db.valueLogReader.Read(ptr)
}

type backendPointerProjectionIterator interface {
	IteratorWithOptions(start, end []byte, opts tree.IteratorOptions) (iterator.UnsafeIterator, error)
}

var (
	errForegroundWritesResumed         = errors.New("cachingdb: foreground writes resumed")
	errRetainedPruneCloseCanceled      = errors.New("cachingdb: retained prune canceled by close")
	errRetainedPruneScanBudgetExceeded = errors.New("cachingdb: retained prune live-ID scan budget exceeded")
)

func retainedPruneContextErr(ctx context.Context) error {
	if ctx == nil {
		return nil
	}
	if err := ctx.Err(); err != nil {
		if cause := context.Cause(ctx); cause != nil && cause != err {
			return cause
		}
		return err
	}
	return nil
}

func retainedPruneContextCause(ctx context.Context, err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		if cause := retainedPruneContextErr(ctx); cause != nil {
			return cause
		}
	}
	return err
}

func (db *DB) retainedPruneLiveIDScanContext(parent context.Context, lastWrite int64, timeout time.Duration) (context.Context, context.CancelFunc) {
	if parent == nil {
		parent = context.Background()
	}
	ctx, cancelCause := context.WithCancelCause(parent)
	var timeoutTimer *time.Timer
	if timeout > 0 {
		timeoutTimer = time.AfterFunc(timeout, func() {
			cancelCause(errRetainedPruneScanBudgetExceeded)
		})
	}
	cancel := func() {
		if timeoutTimer != nil {
			timeoutTimer.Stop()
		}
		cancelCause(context.Canceled)
	}
	if db == nil {
		return ctx, cancel
	}
	if db.closing.Load() {
		cancelCause(errRetainedPruneCloseCanceled)
		return ctx, cancel
	}
	closeCh := db.closeCh
	if closeCh == nil && lastWrite <= 0 {
		return ctx, cancel
	}
	var tick <-chan time.Time
	var ticker *time.Ticker
	if lastWrite > 0 {
		ticker = time.NewTicker(foregroundMaintenancePollInterval())
		tick = ticker.C
	}
	go func(lastWrite int64, closeCh <-chan struct{}) {
		if ticker != nil {
			defer ticker.Stop()
		}
		for {
			select {
			case <-ctx.Done():
				return
			case <-closeCh:
				cancelCause(errRetainedPruneCloseCanceled)
				return
			case <-tick:
				if db.foregroundWritesResumedSince(lastWrite) {
					cancelCause(errForegroundWritesResumed)
					return
				}
			}
		}
	}(lastWrite, closeCh)
	return ctx, cancel
}

func (db *DB) retainedPruneCloseCanceled(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, errRetainedPruneCloseCanceled) {
		return true
	}
	return db != nil && db.closing.Load() && errors.Is(err, context.Canceled)
}

func (db *DB) observeRetainedPruneAbortError(out *retainedValueLogPruneStats, err error) bool {
	if out == nil || err == nil {
		return false
	}
	if db.retainedPruneCloseCanceled(err) {
		out.AbortedClose = true
		return true
	}
	if errors.Is(err, errForegroundWritesResumed) {
		out.AbortedForegroundWrites = true
		return true
	}
	if errors.Is(err, errRetainedPruneScanBudgetExceeded) {
		out.AbortedScanBudget = true
		return true
	}
	return false
}

func (db *DB) retainedPruneScanHook(ctx context.Context, phase string) error {
	if err := retainedPruneContextErr(ctx); err != nil {
		return err
	}
	if db == nil || db.testRetainedPruneScanHook == nil {
		return nil
	}
	if err := db.testRetainedPruneScanHook(ctx, phase); err != nil {
		return err
	}
	return retainedPruneContextErr(ctx)
}

func (db *DB) foregroundWritesResumedSince(lastWrite int64) bool {
	if db == nil {
		return false
	}
	current := db.lastForegroundWriteUnixNano.Load()
	if lastWrite <= 0 {
		return false
	}
	return current > lastWrite
}

type retainedPruneStatus uint32

const (
	retainedPruneStatusNone retainedPruneStatus = iota
	retainedPruneStatusRunning
	retainedPruneStatusCompleted
	retainedPruneStatusNoCandidates
	retainedPruneStatusForegroundAbort
	retainedPruneStatusCloseAbort
	retainedPruneStatusError
	retainedPruneStatusBudgetAbort
)

func retainedPruneStatusString(status uint32) string {
	switch retainedPruneStatus(status) {
	case retainedPruneStatusRunning:
		return "running"
	case retainedPruneStatusCompleted:
		return "completed"
	case retainedPruneStatusNoCandidates:
		return "no_candidates"
	case retainedPruneStatusForegroundAbort:
		return "foreground_abort"
	case retainedPruneStatusCloseAbort:
		return "close_abort"
	case retainedPruneStatusBudgetAbort:
		return "budget_abort"
	case retainedPruneStatusError:
		return "error"
	default:
		return "none"
	}
}

type retainedPruneMode uint32

const (
	retainedPruneModeNone retainedPruneMode = iota
	retainedPruneModeNoCandidates
	retainedPruneModeObservedSourceFastPath
	retainedPruneModeFullLiveIDScan
)

func retainedPruneModeString(mode uint32) string {
	switch retainedPruneMode(mode) {
	case retainedPruneModeNoCandidates:
		return "no_candidates"
	case retainedPruneModeObservedSourceFastPath:
		return "observed_source_fast_path"
	case retainedPruneModeFullLiveIDScan:
		return "full_live_id_scan"
	default:
		return "none"
	}
}

type valueLogLiveIDScanStats struct {
	Records             int64
	ValuePointerRecords int64
	OuterLeafRecords    int64
	OuterLeafBytes      int64
	NestedValuePointers int64
}

func (db *DB) collectValueLogLiveIDs() (map[uint32]struct{}, error) {
	return db.collectValueLogLiveIDsUntil(0)
}

func (db *DB) collectValueLogLiveIDsUntil(lastWrite int64) (map[uint32]struct{}, error) {
	return db.collectValueLogLiveIDsUntilWithStats(lastWrite, nil)
}

func (db *DB) collectValueLogLiveIDsUntilWithStats(lastWrite int64, scanStats *valueLogLiveIDScanStats) (map[uint32]struct{}, error) {
	return db.collectValueLogLiveIDsUntilWithContext(context.Background(), lastWrite, scanStats)
}

func (db *DB) collectValueLogLiveIDsUntilWithContext(ctx context.Context, lastWrite int64, scanStats *valueLogLiveIDScanStats) (map[uint32]struct{}, error) {
	return db.collectValueLogLiveIDsUntilWithContextAndTimeout(ctx, lastWrite, scanStats, 0)
}

func (db *DB) collectValueLogLiveIDsUntilWithContextAndTimeout(ctx context.Context, lastWrite int64, scanStats *valueLogLiveIDScanStats, timeout time.Duration) (map[uint32]struct{}, error) {
	if db == nil || !db.valueLogEnabled() {
		return make(map[uint32]struct{}), nil
	}
	if err := retainedPruneContextErr(ctx); err != nil {
		return nil, err
	}
	if refresher, ok := db.backend.(valueLogSetRefresher); ok {
		if err := refresher.RefreshValueLogSet(); err != nil {
			return nil, err
		}
	}
	ctx, cancel := db.retainedPruneLiveIDScanContext(ctx, lastWrite, timeout)
	defer cancel()
	live := make(map[uint32]struct{})
	if snapper, ok := db.backend.(interface{ AcquireSnapshot() *backenddb.Snapshot }); ok {
		snap := snapper.AcquireSnapshot()
		if snap != nil {
			state := snap.State()
			p := snap.Pager()
			if state != nil && p != nil {
				db.mu.RLock()
				publishedRoots := clonePublishedRootSet(db.rootPublishedSet)
				db.mu.RUnlock()
				reader := newCachedLiveScanReader(valueReaderForBackendState(state), db.valueLogReader)
				maintenanceRootIDs, err := backenddb.CollectMaintenanceRootIDsWithContext(ctx, p, reader, state)
				if err != nil {
					_ = snap.Close()
					return nil, retainedPruneContextCause(ctx, err)
				}
				if state.RootPageID != 0 {
					if err := db.collectIteratorValueLogLiveIDsUntilWithContext(ctx, tree.New(p, reader, state.RootPageID).IteratorWithOptions(nil, nil, tree.IteratorOptions{Mode: tree.IteratorModePointerProjection}), live, lastWrite, scanStats); err != nil {
						_ = snap.Close()
						return nil, err
					}
				}
				if state.SystemRootPageID != 0 {
					if err := db.collectIteratorValueLogLiveIDsUntilWithContext(ctx, tree.New(p, reader, state.SystemRootPageID).IteratorWithOptions(nil, nil, tree.IteratorOptions{Mode: tree.IteratorModePointerProjection}), live, lastWrite, scanStats); err != nil {
						_ = snap.Close()
						return nil, err
					}
				}
				if err := retainedPruneContextErr(ctx); err != nil {
					_ = snap.Close()
					return nil, err
				}
				if db.foregroundWritesResumedSince(lastWrite) {
					_ = snap.Close()
					return nil, errForegroundWritesResumed
				}
				if err := collectLeafRefNestedValueLogLiveIDs(ctx, p, state.RootPageID, reader, live); err != nil {
					_ = snap.Close()
					return nil, retainedPruneContextCause(ctx, err)
				}
				if err := retainedPruneContextErr(ctx); err != nil {
					_ = snap.Close()
					return nil, err
				}
				if db.foregroundWritesResumedSince(lastWrite) {
					_ = snap.Close()
					return nil, errForegroundWritesResumed
				}
				if err := collectLeafRefNestedValueLogLiveIDs(ctx, p, state.SystemRootPageID, reader, live); err != nil {
					_ = snap.Close()
					return nil, retainedPruneContextCause(ctx, err)
				}
				if err := db.collectPublishedRootValueLogLiveIDsUntil(ctx, p, reader, publishedRoots, state.RootPageID, state.SystemRootPageID, maintenanceRootIDs, live, lastWrite, scanStats); err != nil {
					_ = snap.Close()
					return nil, retainedPruneContextCause(ctx, err)
				}
			}
			if err := snap.Close(); err != nil {
				return nil, err
			}
			return live, nil
		}
	}

	var (
		it  iterator.UnsafeIterator
		err error
	)
	if proj, ok := db.backend.(backendPointerProjectionIterator); ok {
		it, err = proj.IteratorWithOptions(nil, nil, tree.IteratorOptions{Mode: tree.IteratorModePointerProjection})
	} else {
		it, err = db.backend.Iterator(nil, nil)
	}
	if err != nil {
		return nil, err
	}
	if err := db.collectIteratorValueLogLiveIDsUntilWithContext(ctx, it, live, lastWrite, scanStats); err != nil {
		return nil, err
	}

	return live, nil
}

func (db *DB) collectPublishedRootValueLogLiveIDsUntil(ctx context.Context, p *pager.Pager, reader tree.SlabReader, published *publishedRootSet, userRootID, systemRootID uint64, maintenanceRootIDs []uint64, live map[uint32]struct{}, lastWrite int64, scanStats *valueLogLiveIDScanStats) error {
	if db == nil || p == nil || reader == nil || live == nil {
		return nil
	}
	seenCap := len(maintenanceRootIDs) + 2
	if published != nil {
		seenCap += len(published.pointShards)
	}
	seenRoots := make(map[uint64]struct{}, seenCap)
	scanRoot := func(rootID uint64) error {
		if err := retainedPruneContextErr(ctx); err != nil {
			return err
		}
		if rootID == 0 || rootID == userRootID || rootID == systemRootID {
			return nil
		}
		if _, ok := seenRoots[rootID]; ok {
			return nil
		}
		seenRoots[rootID] = struct{}{}
		if err := db.collectIteratorValueLogLiveIDsUntilWithContext(ctx, tree.New(p, reader, rootID).IteratorWithOptions(nil, nil, tree.IteratorOptions{Mode: tree.IteratorModePointerProjection}), live, lastWrite, scanStats); err != nil {
			return err
		}
		if err := retainedPruneContextErr(ctx); err != nil {
			return err
		}
		if db.foregroundWritesResumedSince(lastWrite) {
			return errForegroundWritesResumed
		}
		return collectLeafRefValueLogLiveIDs(ctx, p, rootID, reader, live)
	}
	for _, rootID := range maintenanceRootIDs {
		if err := scanRoot(rootID); err != nil {
			return err
		}
	}
	if published != nil {
		for i := range published.pointShards {
			if err := scanRoot(published.pointShards[i].rootID); err != nil {
				return err
			}
		}
		if err := scanRoot(published.system.rootID); err != nil {
			return err
		}
		if published.system.rootID != 0 && published.system.rootID != systemRootID {
			systemRootIDs, err := backenddb.CollectMaintenanceRootIDsForSystemRootWithContext(ctx, p, reader, published.system.rootID)
			if err != nil {
				return err
			}
			for _, rootID := range systemRootIDs {
				if err := scanRoot(rootID); err != nil {
					return err
				}
			}
		}
		if err := scanRoot(published.iterator.rootID); err != nil {
			return err
		}
	}
	return nil
}

func (db *DB) collectIteratorValueLogLiveIDs(it iterator.UnsafeIterator, live map[uint32]struct{}) error {
	return db.collectIteratorValueLogLiveIDsUntil(it, live, 0)
}

func (db *DB) collectIteratorValueLogLiveIDsUntil(it iterator.UnsafeIterator, live map[uint32]struct{}, lastWrite int64) error {
	return db.collectIteratorValueLogLiveIDsUntilWithStats(it, live, lastWrite, nil)
}

func (db *DB) collectIteratorValueLogLiveIDsUntilWithStats(it iterator.UnsafeIterator, live map[uint32]struct{}, lastWrite int64, scanStats *valueLogLiveIDScanStats) error {
	return db.collectIteratorValueLogLiveIDsUntilWithContext(context.Background(), it, live, lastWrite, scanStats)
}

func (db *DB) collectIteratorValueLogLiveIDsUntilWithContext(ctx context.Context, it iterator.UnsafeIterator, live map[uint32]struct{}, lastWrite int64, scanStats *valueLogLiveIDScanStats) error {
	if it == nil {
		return nil
	}
	defer it.Close()
	seen := 0
	var outerLeafReadScratch []byte
	for it.Valid() {
		if seen == 0 || seen&foregroundWriteResumeCheckMask == 0 {
			if err := retainedPruneContextErr(ctx); err != nil {
				return err
			}
			if seen > 0 && db.foregroundWritesResumedSince(lastWrite) {
				return errForegroundWritesResumed
			}
		}
		if err := db.retainedPruneScanHook(ctx, "iterator_record"); err != nil {
			return err
		}
		if scanStats != nil {
			scanStats.Records++
		}
		_, ptr, flags := it.UnsafeEntry()
		if flags&node.FlagPointer != 0 && page.IsValueLogFileID(ptr.FileID) {
			live[ptr.FileID] = struct{}{}
			if scanStats != nil {
				scanStats.ValuePointerRecords++
			}
			if err := db.collectNestedValueLogLiveIDsFromOuterLeafWithContext(ctx, ptr, live, &outerLeafReadScratch, scanStats); err != nil {
				return err
			}
		}
		it.Next()
		seen++
	}
	if err := it.Error(); err != nil {
		return err
	}
	if err := retainedPruneContextErr(ctx); err != nil {
		return err
	}
	if db.foregroundWritesResumedSince(lastWrite) {
		return errForegroundWritesResumed
	}
	return nil
}

const nestedOuterLeafReadScratchDefaultCap = 64 << 10

func (db *DB) collectNestedValueLogLiveIDsFromOuterLeaf(ptr page.ValuePtr, live map[uint32]struct{}, readScratch *[]byte) error {
	return db.collectNestedValueLogLiveIDsFromOuterLeafWithStats(ptr, live, readScratch, nil)
}

func (db *DB) collectNestedValueLogLiveIDsFromOuterLeafWithStats(ptr page.ValuePtr, live map[uint32]struct{}, readScratch *[]byte, scanStats *valueLogLiveIDScanStats) error {
	return db.collectNestedValueLogLiveIDsFromOuterLeafWithContext(context.Background(), ptr, live, readScratch, scanStats)
}

func (db *DB) collectNestedValueLogLiveIDsFromOuterLeafWithContext(ctx context.Context, ptr page.ValuePtr, live map[uint32]struct{}, readScratch *[]byte, scanStats *valueLogLiveIDScanStats) error {
	if db == nil || len(live) == 0 || db.valueLogReader == nil {
		return nil
	}
	if err := db.retainedPruneScanHook(ctx, "nested_outer_leaf_before_read"); err != nil {
		return err
	}
	var (
		raw []byte
		err error
	)
	if readScratch != nil {
		dst := *readScratch
		if dst == nil {
			dst = make([]byte, 0, nestedOuterLeafReadScratchDefaultCap)
		} else {
			dst = dst[:0]
		}
		var usedDst bool
		raw, usedDst, err = db.valueLogReader.ReadUnsafeTo(ptr, dst)
		if err != nil {
			return err
		}
		if usedDst {
			*readScratch = raw[:0]
		}
	} else {
		raw, err = db.valueLogReader.Read(ptr)
		if err != nil {
			return err
		}
	}
	if err := retainedPruneContextErr(ctx); err != nil {
		return err
	}
	if !outerleaf.HasMagic(raw) {
		return nil
	}
	if scanStats != nil {
		scanStats.OuterLeafRecords++
		scanStats.OuterLeafBytes += int64(len(raw))
	}
	block, err := outerleaf.DecodeBlockLeaseWithVerify(raw, false)
	if err != nil {
		if ctxErr := retainedPruneContextErr(ctx); ctxErr != nil {
			return ctxErr
		}
		return nil
	}
	defer block.Release()
	if err := retainedPruneContextErr(ctx); err != nil {
		return err
	}

	typed, err := block.TypedEntries(nil)
	if err != nil {
		if ctxErr := retainedPruneContextErr(ctx); ctxErr != nil {
			return ctxErr
		}
		return nil
	}
	for i := range typed {
		if i > 0 && i&foregroundWriteResumeCheckMask == 0 {
			if err := retainedPruneContextErr(ctx); err != nil {
				return err
			}
		}
		if typed[i].Kind != outerleaf.EntryKindBlobRef {
			continue
		}
		if typed[i].BlobPtr.FileID == 0 {
			continue
		}
		if !page.IsValueLogFileID(typed[i].BlobPtr.FileID) {
			return fmt.Errorf("cachingdb: invalid nested blob pointer file %d", typed[i].BlobPtr.FileID)
		}
		live[typed[i].BlobPtr.FileID] = struct{}{}
		if scanStats != nil {
			scanStats.NestedValuePointers++
		}
	}
	return retainedPruneContextErr(ctx)
}

func (db *DB) checkValueLogRetention() {
	limit := db.maxValueLogRetainedBytes
	if limit <= 0 || !db.valueLogEnabled() {
		return
	}
	_, bytes := db.valueLogRetainedStats()
	if bytes <= limit {
		db.valueLogWarned.Store(false)
		return
	}
	if db.valueLogWarned.CompareAndSwap(false, true) {
		db.reportError(fmt.Errorf("cachingdb: retained value-log bytes %d exceed limit %d", bytes, limit))
	}
}

func (db *DB) allowValueLogPointers() bool {
	if !db.valueLogEnabled() {
		return false
	}
	limit := db.maxValueLogRetainedBytesHard
	if limit <= 0 {
		return true
	}
	bytes := db.valueLogRetainedClosedBytes.Load()
	if db.splitValueLogEnabled() {
		for i := range db.lanes {
			l := &db.lanes[i]
			if l.vlogPath != "" && l.vlogPath == l.vlogRetainedPath {
				bytes += l.vlogLiveBytes.Load()
			}
		}
		if db.indexOuterLeavesInValueLog {
			for _, l := range db.leafLogAppendLanesSnapshot() {
				if l != nil && l.vlogPath != "" && l.vlogPath == l.vlogRetainedPath {
					bytes += l.vlogLiveBytes.Load()
				}
			}
		}
	}
	if bytes >= limit {
		if db.valueLogHardCapWarned.CompareAndSwap(false, true) {
			db.reportError(fmt.Errorf("cachingdb: retained value-log bytes %d exceed hard cap %d; disabling new value-log pointers", bytes, limit))
			// Hard-cap entry means retained bytes are now constraining placement.
			// Request an eager retained prune so lifecycle pins can drain promptly.
			db.scheduleRetainedValueLogPruneForce()
		}
		return false
	}
	db.valueLogHardCapWarned.Store(false)
	return true
}

type valueLogZombieMarker interface {
	MarkValueLogZombie(id uint32) error
}

type valueLogSetRefresher interface {
	RefreshValueLogSet() error
}

type retainedValueLogPruneStats struct {
	RemovedSegments                    int
	RemovedBytes                       int64
	InUseSkippedSegments               int
	InUseSkippedBytes                  int64
	CandidateSegments                  int
	CandidateBytes                     int64
	LiveSkippedSegments                int
	LiveSkippedBytes                   int64
	ParseSkippedSegments               int
	ParseSkippedBytes                  int64
	ZombieMarkedSegments               int
	ZombieMarkedBytes                  int64
	ObservedSourceSegments             int
	ObservedSourceBytes                int64
	ObservedSourceCandidateSegments    int
	ObservedSourceCandidateBytes       int64
	ObservedSourceRemovedSegments      int
	ObservedSourceRemovedBytes         int64
	ObservedSourceInUseSkippedSegments int
	ObservedSourceInUseSkippedBytes    int64
	ObservedSourceLiveSkippedSegments  int
	ObservedSourceLiveSkippedBytes     int64
	ObservedSourceParseSkippedSegments int
	ObservedSourceParseSkippedBytes    int64
	ObservedSourceZombieMarkedSegments int
	ObservedSourceZombieMarkedBytes    int64
	Mode                               retainedPruneMode
	ScanStats                          valueLogLiveIDScanStats
	ElapsedNanos                       int64
	AbortedClose                       bool
	AbortedForegroundWrites            bool
	AbortedScanBudget                  bool
	ScanError                          bool
	RetriedWithoutWriteGate            bool
	RetrySucceeded                     bool
}

type retainedValueLogPruneRunOptions struct {
	fullLiveIDScanBudget time.Duration
}

func retainedPruneStatusForStats(pruneStats retainedValueLogPruneStats) retainedPruneStatus {
	if pruneStats.AbortedClose {
		return retainedPruneStatusCloseAbort
	}
	if pruneStats.AbortedForegroundWrites {
		return retainedPruneStatusForegroundAbort
	}
	if pruneStats.AbortedScanBudget {
		return retainedPruneStatusBudgetAbort
	}
	if pruneStats.ScanError {
		return retainedPruneStatusError
	}
	if pruneStats.Mode == retainedPruneModeNoCandidates {
		return retainedPruneStatusNoCandidates
	}
	return retainedPruneStatusCompleted
}

func (db *DB) observeRetainedValueLogPruneStart(force bool, observedSourceIDs int, inline bool, start time.Time) {
	if db == nil {
		return
	}
	db.retainedValueLogPruneLastStatus.Store(uint32(retainedPruneStatusRunning))
	db.retainedValueLogPruneLastMode.Store(uint32(retainedPruneModeNone))
	db.retainedValueLogPruneLastForce.Store(force)
	db.retainedValueLogPruneLastStartUnixNano.Store(start.UnixNano())
	db.retainedValueLogPruneLastElapsedNanos.Store(0)
	db.retainedValueLogPruneLastScanRecords.Store(0)
	db.retainedValueLogPruneLastScanValuePointerRecords.Store(0)
	db.retainedValueLogPruneLastScanOuterLeafRecords.Store(0)
	db.retainedValueLogPruneLastScanOuterLeafBytes.Store(0)
	db.retainedValueLogPruneLastScanNestedValuePointers.Store(0)
	db.debugVlogMaintf(
		"retained_prune_start force=%t inline=%t observed_source_ids=%d closed_bytes=%d pressure_bytes=%d",
		force,
		inline,
		observedSourceIDs,
		db.valueLogRetainedClosedBytes.Load(),
		db.retainedPrunePressureBytes(),
	)
}

func (db *DB) observeRetainedValueLogPruneCloseAbort(force bool, inline bool, elapsed time.Duration) {
	if db == nil {
		return
	}
	db.retainedValueLogPruneLastStatus.Store(uint32(retainedPruneStatusCloseAbort))
	db.retainedValueLogPruneLastMode.Store(uint32(retainedPruneModeNone))
	db.retainedValueLogPruneLastForce.Store(force)
	db.retainedValueLogPruneLastElapsedNanos.Store(int64(elapsed))
	db.retainedValueLogPruneCloseAbortRuns.Add(1)
	if elapsed > 0 {
		observeDurationNanos(&db.retainedValueLogPruneTotalNanos, &db.retainedValueLogPruneMaxNanos, elapsed)
	}
	db.debugVlogMaintf("retained_prune_abort reason=close force=%t inline=%t elapsed_ms=%.3f", force, inline, float64(elapsed)/float64(time.Millisecond))
}

func (db *DB) observeRetainedValueLogPruneStats(pruneStats retainedValueLogPruneStats) {
	if db == nil {
		return
	}
	status := retainedPruneStatusForStats(pruneStats)
	db.retainedValueLogPruneLastStatus.Store(uint32(status))
	db.retainedValueLogPruneLastMode.Store(uint32(pruneStats.Mode))
	if pruneStats.ElapsedNanos > 0 {
		db.retainedValueLogPruneLastElapsedNanos.Store(pruneStats.ElapsedNanos)
		observeDurationNanos(&db.retainedValueLogPruneTotalNanos, &db.retainedValueLogPruneMaxNanos, time.Duration(pruneStats.ElapsedNanos))
	} else {
		db.retainedValueLogPruneLastElapsedNanos.Store(0)
	}
	db.retainedValueLogPruneLastScanRecords.Store(pruneStats.ScanStats.Records)
	db.retainedValueLogPruneLastScanValuePointerRecords.Store(pruneStats.ScanStats.ValuePointerRecords)
	db.retainedValueLogPruneLastScanOuterLeafRecords.Store(pruneStats.ScanStats.OuterLeafRecords)
	db.retainedValueLogPruneLastScanOuterLeafBytes.Store(pruneStats.ScanStats.OuterLeafBytes)
	db.retainedValueLogPruneLastScanNestedValuePointers.Store(pruneStats.ScanStats.NestedValuePointers)
	if status != retainedPruneStatusForegroundAbort &&
		status != retainedPruneStatusCloseAbort &&
		status != retainedPruneStatusBudgetAbort &&
		status != retainedPruneStatusError {
		db.retainedValueLogPruneCompletedRuns.Add(1)
	}
	if status == retainedPruneStatusError {
		db.retainedValueLogPruneErrorRuns.Add(1)
	}
	if status == retainedPruneStatusCloseAbort {
		db.retainedValueLogPruneCloseAbortRuns.Add(1)
	}
	if status == retainedPruneStatusBudgetAbort {
		db.retainedValueLogPruneBudgetAbortRuns.Add(1)
	}
	if pruneStats.Mode == retainedPruneModeNoCandidates {
		db.retainedValueLogPruneNoCandidateRuns.Add(1)
	}
	if pruneStats.Mode == retainedPruneModeObservedSourceFastPath {
		db.retainedValueLogPruneObservedSourceFastPathRuns.Add(1)
	}
	if pruneStats.Mode == retainedPruneModeFullLiveIDScan {
		db.retainedValueLogPruneFullLiveIDScanRuns.Add(1)
	}
	if pruneStats.ScanStats.Records > 0 {
		db.retainedValueLogPruneScanRecordsTotal.Add(uint64(pruneStats.ScanStats.Records))
	}
	if pruneStats.ScanStats.ValuePointerRecords > 0 {
		db.retainedValueLogPruneScanValuePointerRecordsTotal.Add(uint64(pruneStats.ScanStats.ValuePointerRecords))
	}
	if pruneStats.ScanStats.OuterLeafRecords > 0 {
		db.retainedValueLogPruneScanOuterLeafRecordsTotal.Add(uint64(pruneStats.ScanStats.OuterLeafRecords))
	}
	if pruneStats.ScanStats.OuterLeafBytes > 0 {
		db.retainedValueLogPruneScanOuterLeafBytesTotal.Add(uint64(pruneStats.ScanStats.OuterLeafBytes))
	}
	if pruneStats.ScanStats.NestedValuePointers > 0 {
		db.retainedValueLogPruneScanNestedValuePointersTotal.Add(uint64(pruneStats.ScanStats.NestedValuePointers))
	}
	debugEvent := "end"
	debugReason := "none"
	switch status {
	case retainedPruneStatusForegroundAbort:
		debugEvent = "abort"
		debugReason = retainedPruneStatusString(uint32(status))
	case retainedPruneStatusCloseAbort:
		debugEvent = "abort"
		debugReason = "close"
	case retainedPruneStatusBudgetAbort:
		debugEvent = "abort"
		debugReason = retainedPruneStatusString(uint32(status))
	case retainedPruneStatusError:
		debugEvent = "abort"
		debugReason = retainedPruneStatusString(uint32(status))
	}
	db.debugVlogMaintf(
		"retained_prune_%s reason=%s status=%s mode=%s force=%t elapsed_ms=%.3f candidates=%d candidate_bytes=%d removed_segments=%d removed_bytes=%d zombie_marked_segments=%d zombie_marked_bytes=%d live_skipped_segments=%d live_skipped_bytes=%d in_use_skipped_segments=%d parse_skipped_segments=%d observed_source_segments=%d observed_source_candidate_segments=%d observed_source_removed_segments=%d observed_source_zombie_marked_segments=%d scan_records=%d scan_value_pointer_records=%d scan_outer_leaf_records=%d scan_outer_leaf_bytes=%d scan_nested_value_pointers=%d",
		debugEvent,
		debugReason,
		retainedPruneStatusString(uint32(status)),
		retainedPruneModeString(uint32(pruneStats.Mode)),
		db.retainedValueLogPruneLastForce.Load(),
		float64(pruneStats.ElapsedNanos)/float64(time.Millisecond),
		pruneStats.CandidateSegments,
		pruneStats.CandidateBytes,
		pruneStats.RemovedSegments,
		pruneStats.RemovedBytes,
		pruneStats.ZombieMarkedSegments,
		pruneStats.ZombieMarkedBytes,
		pruneStats.LiveSkippedSegments,
		pruneStats.LiveSkippedBytes,
		pruneStats.InUseSkippedSegments,
		pruneStats.ParseSkippedSegments,
		pruneStats.ObservedSourceSegments,
		pruneStats.ObservedSourceCandidateSegments,
		pruneStats.ObservedSourceRemovedSegments,
		pruneStats.ObservedSourceZombieMarkedSegments,
		pruneStats.ScanStats.Records,
		pruneStats.ScanStats.ValuePointerRecords,
		pruneStats.ScanStats.OuterLeafRecords,
		pruneStats.ScanStats.OuterLeafBytes,
		pruneStats.ScanStats.NestedValuePointers,
	)
	db.retainedValueLogPruneLastObservedSourceSegments.Store(int64(pruneStats.ObservedSourceSegments))
	db.retainedValueLogPruneLastObservedSourceBytes.Store(pruneStats.ObservedSourceBytes)
	db.retainedValueLogPruneLastObservedSourceCandidateSegments.Store(int64(pruneStats.ObservedSourceCandidateSegments))
	db.retainedValueLogPruneLastObservedSourceCandidateBytes.Store(pruneStats.ObservedSourceCandidateBytes)
	db.retainedValueLogPruneLastObservedSourceRemovedSegments.Store(int64(pruneStats.ObservedSourceRemovedSegments))
	db.retainedValueLogPruneLastObservedSourceRemovedBytes.Store(pruneStats.ObservedSourceRemovedBytes)
	db.retainedValueLogPruneLastObservedSourceInUseSkippedSegments.Store(int64(pruneStats.ObservedSourceInUseSkippedSegments))
	db.retainedValueLogPruneLastObservedSourceInUseSkippedBytes.Store(pruneStats.ObservedSourceInUseSkippedBytes)
	db.retainedValueLogPruneLastObservedSourceLiveSkippedSegments.Store(int64(pruneStats.ObservedSourceLiveSkippedSegments))
	db.retainedValueLogPruneLastObservedSourceLiveSkippedBytes.Store(pruneStats.ObservedSourceLiveSkippedBytes)
	db.retainedValueLogPruneLastObservedSourceParseSkippedSegments.Store(int64(pruneStats.ObservedSourceParseSkippedSegments))
	db.retainedValueLogPruneLastObservedSourceParseSkippedBytes.Store(pruneStats.ObservedSourceParseSkippedBytes)
	db.retainedValueLogPruneLastObservedSourceZombieMarkedSegments.Store(int64(pruneStats.ObservedSourceZombieMarkedSegments))
	db.retainedValueLogPruneLastObservedSourceZombieMarkedBytes.Store(pruneStats.ObservedSourceZombieMarkedBytes)
	if pruneStats.ObservedSourceSegments > 0 {
		db.retainedValueLogPruneObservedSourceSegmentsTotal.Add(uint64(pruneStats.ObservedSourceSegments))
	}
	if pruneStats.ObservedSourceBytes > 0 {
		db.retainedValueLogPruneObservedSourceBytesTotal.Add(pruneStats.ObservedSourceBytes)
	}
	if pruneStats.ObservedSourceCandidateSegments > 0 {
		db.retainedValueLogPruneObservedSourceCandidateSegmentsTotal.Add(uint64(pruneStats.ObservedSourceCandidateSegments))
	}
	if pruneStats.ObservedSourceCandidateBytes > 0 {
		db.retainedValueLogPruneObservedSourceCandidateBytesTotal.Add(pruneStats.ObservedSourceCandidateBytes)
	}
	if pruneStats.ObservedSourceRemovedSegments > 0 {
		db.retainedValueLogPruneObservedSourceRemovedSegmentsTotal.Add(uint64(pruneStats.ObservedSourceRemovedSegments))
	}
	if pruneStats.ObservedSourceRemovedBytes > 0 {
		db.retainedValueLogPruneObservedSourceRemovedBytesTotal.Add(pruneStats.ObservedSourceRemovedBytes)
	}
	if pruneStats.ObservedSourceInUseSkippedSegments > 0 {
		db.retainedValueLogPruneObservedSourceInUseSkippedSegmentsTotal.Add(uint64(pruneStats.ObservedSourceInUseSkippedSegments))
	}
	if pruneStats.ObservedSourceInUseSkippedBytes > 0 {
		db.retainedValueLogPruneObservedSourceInUseSkippedBytesTotal.Add(pruneStats.ObservedSourceInUseSkippedBytes)
	}
	if pruneStats.ObservedSourceLiveSkippedSegments > 0 {
		db.retainedValueLogPruneObservedSourceLiveSkippedSegmentsTotal.Add(uint64(pruneStats.ObservedSourceLiveSkippedSegments))
	}
	if pruneStats.ObservedSourceLiveSkippedBytes > 0 {
		db.retainedValueLogPruneObservedSourceLiveSkippedBytesTotal.Add(pruneStats.ObservedSourceLiveSkippedBytes)
	}
	if pruneStats.ObservedSourceParseSkippedSegments > 0 {
		db.retainedValueLogPruneObservedSourceParseSkippedSegmentsTotal.Add(uint64(pruneStats.ObservedSourceParseSkippedSegments))
	}
	if pruneStats.ObservedSourceParseSkippedBytes > 0 {
		db.retainedValueLogPruneObservedSourceParseSkippedBytesTotal.Add(pruneStats.ObservedSourceParseSkippedBytes)
	}
	if pruneStats.ObservedSourceZombieMarkedSegments > 0 {
		db.retainedValueLogPruneObservedSourceZombieMarkedSegmentsTotal.Add(uint64(pruneStats.ObservedSourceZombieMarkedSegments))
	}
	if pruneStats.ObservedSourceZombieMarkedBytes > 0 {
		db.retainedValueLogPruneObservedSourceZombieMarkedBytesTotal.Add(pruneStats.ObservedSourceZombieMarkedBytes)
	}
	if pruneStats.RetriedWithoutWriteGate {
		db.retainedValueLogPruneWriteGateRetries.Add(1)
		if pruneStats.RetrySucceeded {
			db.retainedValueLogPruneWriteGateRetrySuccesses.Add(1)
		}
	}
	if pruneStats.AbortedForegroundWrites {
		db.retainedValueLogPruneForegroundAbortRuns.Add(1)
	}
	if pruneStats.RemovedSegments > 0 {
		db.retainedValueLogPruneRemovedSegments.Add(uint64(pruneStats.RemovedSegments))
	}
	if pruneStats.RemovedBytes > 0 {
		db.retainedValueLogPruneRemovedBytes.Add(uint64(pruneStats.RemovedBytes))
	}
	if pruneStats.InUseSkippedSegments > 0 {
		db.retainedValueLogPruneInUseSkippedSegments.Add(uint64(pruneStats.InUseSkippedSegments))
	}
	if pruneStats.InUseSkippedBytes > 0 {
		db.retainedValueLogPruneInUseSkippedBytes.Add(uint64(pruneStats.InUseSkippedBytes))
	}
	if pruneStats.CandidateSegments > 0 {
		db.retainedValueLogPruneCandidateSegments.Add(uint64(pruneStats.CandidateSegments))
	}
	if pruneStats.CandidateBytes > 0 {
		db.retainedValueLogPruneCandidateBytes.Add(uint64(pruneStats.CandidateBytes))
	}
	if pruneStats.LiveSkippedSegments > 0 {
		db.retainedValueLogPruneLiveSkippedSegments.Add(uint64(pruneStats.LiveSkippedSegments))
	}
	if pruneStats.LiveSkippedBytes > 0 {
		db.retainedValueLogPruneLiveSkippedBytes.Add(uint64(pruneStats.LiveSkippedBytes))
	}
	if pruneStats.ParseSkippedSegments > 0 {
		db.retainedValueLogPruneParseSkippedSegments.Add(uint64(pruneStats.ParseSkippedSegments))
	}
	if pruneStats.ParseSkippedBytes > 0 {
		db.retainedValueLogPruneParseSkippedBytes.Add(uint64(pruneStats.ParseSkippedBytes))
	}
	if pruneStats.ZombieMarkedSegments > 0 {
		db.retainedValueLogPruneZombieMarkedSegments.Add(uint64(pruneStats.ZombieMarkedSegments))
	}
	if pruneStats.ZombieMarkedBytes > 0 {
		db.retainedValueLogPruneZombieMarkedBytes.Add(uint64(pruneStats.ZombieMarkedBytes))
	}
}

func (db *DB) valueLogClosedSegmentSize(path string) int64 {
	if db == nil || path == "" {
		return 0
	}
	laneID, _, _, ok := parseLogSeq(filepath.Base(path))
	if !ok {
		return 0
	}
	l := db.valueLogLaneByID(laneID)
	if l == nil {
		return 0
	}
	l.vlogMu.Lock()
	defer l.vlogMu.Unlock()
	if l.vlogClosedSizes == nil {
		return 0
	}
	return l.vlogClosedSizes[path]
}

func (db *DB) pruneRetainedValueLogs(force bool) retainedValueLogPruneStats {
	return db.pruneRetainedValueLogsWithObserved(force, nil)
}

func (db *DB) pruneRetainedValueLogsWithObserved(force bool, observedSourceIDs map[uint32]struct{}) retainedValueLogPruneStats {
	return db.pruneRetainedValueLogsWithObservedContext(context.Background(), force, observedSourceIDs)
}

func (db *DB) pruneRetainedValueLogsWithObservedContext(ctx context.Context, force bool, observedSourceIDs map[uint32]struct{}) retainedValueLogPruneStats {
	return db.pruneRetainedValueLogsWithObservedContextOptions(ctx, force, observedSourceIDs, retainedValueLogPruneRunOptions{})
}

func (db *DB) pruneRetainedValueLogsWithObservedContextOptions(ctx context.Context, force bool, observedSourceIDs map[uint32]struct{}, runOpts retainedValueLogPruneRunOptions) retainedValueLogPruneStats {
	var out retainedValueLogPruneStats
	if ctx == nil {
		ctx = context.Background()
	}
	if !db.valueLogEnabled() {
		return out
	}
	if err := retainedPruneContextErr(ctx); err != nil {
		if !db.observeRetainedPruneAbortError(&out, err) {
			out.ScanError = true
			db.reportError(fmt.Errorf("cachingdb: retained value-log prune canceled: %w", err))
		}
		return out
	}
	paths := db.valueOnlyLogPaths(db.valueLogRetainedPaths())
	if len(paths) == 0 {
		out.Mode = retainedPruneModeNoCandidates
		return out
	}

	inUse := make(map[string]struct{})
	for _, path := range db.valueOnlyLogPaths(db.valueLogInUsePaths()) {
		inUse[path] = struct{}{}
	}

	type pruneCandidate struct {
		path     string
		size     int64
		id       uint32
		hasID    bool
		observed bool
	}
	candidatePaths := make([]pruneCandidate, 0, len(paths))
	for i, path := range paths {
		if i == 0 || i&foregroundWriteResumeCheckMask == 0 {
			if err := retainedPruneContextErr(ctx); err != nil {
				if !db.observeRetainedPruneAbortError(&out, err) {
					out.ScanError = true
					db.reportError(fmt.Errorf("cachingdb: retained value-log prune canceled while collecting candidates: %w", err))
				}
				return out
			}
		}
		size := db.valueLogClosedSegmentSize(path)
		candidate := pruneCandidate{path: path, size: size}
		if laneID, seq, valueLog, ok := parseLogSeq(filepath.Base(path)); ok && valueLog && laneID >= 0 {
			if id, err := valuelog.EncodeFileID(uint32(laneID), uint32(seq)); err == nil {
				candidate.id = id
				candidate.hasID = true
				if _, ok := observedSourceIDs[id]; ok {
					candidate.observed = true
					out.ObservedSourceSegments++
					if size > 0 {
						out.ObservedSourceBytes += size
					}
				}
			}
		}
		if _, ok := inUse[path]; ok {
			out.InUseSkippedSegments++
			if size > 0 {
				out.InUseSkippedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceInUseSkippedSegments++
				if size > 0 {
					out.ObservedSourceInUseSkippedBytes += size
				}
			}
			continue
		}
		if db.cleanupMissingRetainedValueLog(path) {
			out.RemovedSegments++
			if size > 0 {
				out.RemovedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceRemovedSegments++
				if size > 0 {
					out.ObservedSourceRemovedBytes += size
				}
			}
			continue
		}
		out.CandidateSegments++
		if size > 0 {
			out.CandidateBytes += size
		}
		if candidate.observed {
			out.ObservedSourceCandidateSegments++
			if size > 0 {
				out.ObservedSourceCandidateBytes += size
			}
		}
		candidatePaths = append(candidatePaths, candidate)
	}
	if len(candidatePaths) == 0 {
		out.Mode = retainedPruneModeNoCandidates
		return out
	}

	// When a queued rewrite explicitly observed source segment IDs that are
	// currently pinned by retention, we already know those segments are
	// unreachable in the backend index (otherwise rewrite+GC would not have
	// classified them as retained-protected blockers). In that case, prune only
	// the observed IDs and avoid an expensive full pointer scan.
	if force && len(observedSourceIDs) > 0 {
		out.Mode = retainedPruneModeObservedSourceFastPath
		removed := false
		marked := false
		for i, candidate := range candidatePaths {
			if i == 0 || i&foregroundWriteResumeCheckMask == 0 {
				if err := retainedPruneContextErr(ctx); err != nil {
					if !db.observeRetainedPruneAbortError(&out, err) {
						out.ScanError = true
						db.reportError(fmt.Errorf("cachingdb: retained value-log observed-source prune canceled: %w", err))
					}
					return out
				}
			}
			if !candidate.observed {
				continue
			}
			path := candidate.path
			size := candidate.size
			id := candidate.id
			if !candidate.hasID {
				out.ParseSkippedSegments++
				if size > 0 {
					out.ParseSkippedBytes += size
				}
				out.ObservedSourceParseSkippedSegments++
				if size > 0 {
					out.ObservedSourceParseSkippedBytes += size
				}
				continue
			}

			if marker, ok := db.backend.(valueLogZombieMarker); ok {
				var expectedIdentity rootpublication.StableIdentity
				if db.valueLogReader != nil {
					expectedIdentity, _ = db.valueLogReader.StableSegmentIdentity(id)
					_ = db.valueLogReader.EvictSegment(id)
				}
				if err := marker.MarkValueLogZombie(id); err != nil {
					if errors.Is(err, backenddb.ErrValueLogZombieDeferred) {
						continue
					}
					if errors.Is(err, valuelog.ErrFileNotFound) && db.cleanupOrphanedRetainedValueLogExpected(path, expectedIdentity) {
						removed = true
						out.RemovedSegments++
						if size > 0 {
							out.RemovedBytes += size
						}
						out.ObservedSourceRemovedSegments++
						if size > 0 {
							out.ObservedSourceRemovedBytes += size
						}
						continue
					}
					if db.cleanupMissingRetainedValueLog(path) {
						out.RemovedSegments++
						if size > 0 {
							out.RemovedBytes += size
						}
						out.ObservedSourceRemovedSegments++
						if size > 0 {
							out.ObservedSourceRemovedBytes += size
						}
						continue
					}
					db.reportError(fmt.Errorf("cachingdb: failed to mark value-log %d zombie: %w", id, err))
					continue
				}
				out.ZombieMarkedSegments++
				if size > 0 {
					out.ZombieMarkedBytes += size
				}
				out.ObservedSourceZombieMarkedSegments++
				if size > 0 {
					out.ObservedSourceZombieMarkedBytes += size
				}
				marked = true
			} else if db.cleanupOrphanedRetainedValueLog(path) {
				db.mu.Lock()
				db.untrackValueLogSegmentLocked(path)
				db.mu.Unlock()
				removed = true
				out.RemovedSegments++
				if size > 0 {
					out.RemovedBytes += size
				}
				out.ObservedSourceRemovedSegments++
				if size > 0 {
					out.ObservedSourceRemovedBytes += size
				}
			} else {
				continue
			}
			db.forgetValueLogRetain(path)
		}

		if marked {
			if refresher, ok := db.backend.(valueLogSetRefresher); ok {
				if err := refresher.RefreshValueLogSet(); err != nil {
					db.reportError(fmt.Errorf("cachingdb: failed to refresh value-log set: %w", err))
				}
			}
		}
		if removed {
			db.syncDirBestEffort(db.valueLogDir, durabilitycut.ResourceValueLog)
			if db.leafLogDir != "" {
				db.syncDirBestEffort(db.leafLogDir, durabilitycut.ResourceOuterLeaf)
			}
		}
		return out
	}

	out.Mode = retainedPruneModeFullLiveIDScan
	lastWrite := db.lastForegroundWriteUnixNano.Load()
	liveIDs, err := db.collectValueLogLiveIDsUntilWithContextAndTimeout(
		ctx,
		lastWrite,
		&out.ScanStats,
		runOpts.fullLiveIDScanBudget,
	)
	if err != nil {
		if db.observeRetainedPruneAbortError(&out, err) {
			return out
		}
		out.ScanError = true
		db.reportError(fmt.Errorf("cachingdb: failed to scan value-log pointers: %w", err))
		return out
	}
	if err := retainedPruneContextErr(ctx); err != nil {
		if !db.observeRetainedPruneAbortError(&out, err) {
			out.ScanError = true
			db.reportError(fmt.Errorf("cachingdb: retained value-log prune canceled after live-ID scan: %w", err))
		}
		return out
	}

	removed := false
	marked := false
	for i, candidate := range candidatePaths {
		if i == 0 || i&foregroundWriteResumeCheckMask == 0 {
			if err := retainedPruneContextErr(ctx); err != nil {
				if !db.observeRetainedPruneAbortError(&out, err) {
					out.ScanError = true
					db.reportError(fmt.Errorf("cachingdb: retained value-log prune canceled before reclaim: %w", err))
				}
				return out
			}
		}
		path := candidate.path
		size := candidate.size
		id := candidate.id
		if !candidate.hasID {
			out.ParseSkippedSegments++
			if size > 0 {
				out.ParseSkippedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceParseSkippedSegments++
				if size > 0 {
					out.ObservedSourceParseSkippedBytes += size
				}
			}
			continue
		}
		if _, ok := liveIDs[id]; ok {
			out.LiveSkippedSegments++
			if size > 0 {
				out.LiveSkippedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceLiveSkippedSegments++
				if size > 0 {
					out.ObservedSourceLiveSkippedBytes += size
				}
			}
			continue
		}

		if marker, ok := db.backend.(valueLogZombieMarker); ok {
			var expectedIdentity rootpublication.StableIdentity
			if db.valueLogReader != nil {
				expectedIdentity, _ = db.valueLogReader.StableSegmentIdentity(id)
				_ = db.valueLogReader.EvictSegment(id)
			}
			if err := marker.MarkValueLogZombie(id); err != nil {
				if errors.Is(err, backenddb.ErrValueLogZombieDeferred) {
					continue
				}
				if errors.Is(err, valuelog.ErrFileNotFound) && db.cleanupOrphanedRetainedValueLogExpected(path, expectedIdentity) {
					removed = true
					out.RemovedSegments++
					if size > 0 {
						out.RemovedBytes += size
					}
					if candidate.observed {
						out.ObservedSourceRemovedSegments++
						if size > 0 {
							out.ObservedSourceRemovedBytes += size
						}
					}
					continue
				}
				if db.cleanupMissingRetainedValueLog(path) {
					out.RemovedSegments++
					if size > 0 {
						out.RemovedBytes += size
					}
					if candidate.observed {
						out.ObservedSourceRemovedSegments++
						if size > 0 {
							out.ObservedSourceRemovedBytes += size
						}
					}
					continue
				}
				db.reportError(fmt.Errorf("cachingdb: failed to mark value-log %d zombie: %w", id, err))
				continue
			}
			out.ZombieMarkedSegments++
			if size > 0 {
				out.ZombieMarkedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceZombieMarkedSegments++
				if size > 0 {
					out.ObservedSourceZombieMarkedBytes += size
				}
			}
			marked = true
		} else if db.cleanupOrphanedRetainedValueLog(path) {
			db.mu.Lock()
			db.untrackValueLogSegmentLocked(path)
			db.mu.Unlock()
			removed = true
			out.RemovedSegments++
			if size > 0 {
				out.RemovedBytes += size
			}
			if candidate.observed {
				out.ObservedSourceRemovedSegments++
				if size > 0 {
					out.ObservedSourceRemovedBytes += size
				}
			}
		} else {
			continue
		}
		db.forgetValueLogRetain(path)
	}

	if marked {
		if refresher, ok := db.backend.(valueLogSetRefresher); ok {
			if err := refresher.RefreshValueLogSet(); err != nil {
				db.reportError(fmt.Errorf("cachingdb: failed to refresh value-log set: %w", err))
			}
		}
	}
	if removed {
		db.syncDirBestEffort(db.valueLogDir, durabilitycut.ResourceValueLog)
		if db.leafLogDir != "" {
			db.syncDirBestEffort(db.leafLogDir, durabilitycut.ResourceOuterLeaf)
		}
	}
	return out
}

func (db *DB) retainedPrunePressureBytes() int64 {
	if db == nil || !db.valueLogEnabled() {
		return 0
	}
	if limit := db.maxValueLogRetainedBytes; limit > 0 {
		return limit
	}
	if limit := db.maxValueLogRetainedBytesHard; limit > 0 {
		if limit <= 1 {
			return 1
		}
		return limit / 2
	}
	const (
		retainedPruneSegmentPressureMultiplier = 4
		// Keep retained-prune pressure comfortably above tiny test/default
		// segment sizes so prune cadence stays tied to substantial backlog.
		retainedPrunePressureFloorBytes = 1 << 30
	)
	pressure := db.valueLogMaxSegmentBytes * retainedPruneSegmentPressureMultiplier
	if pressure <= 0 {
		pressure = retainedPrunePressureFloorBytes
	}
	if db.flushThreshold > 0 {
		ft := db.flushThreshold
		if ft > math.MaxInt64/8 {
			ft = math.MaxInt64
		} else {
			ft *= 8
		}
		if ft > pressure {
			pressure = ft
		}
	}
	if pressure < retainedPrunePressureFloorBytes {
		pressure = retainedPrunePressureFloorBytes
	}
	return pressure
}

func (db *DB) retainedPruneBackgroundFullLiveIDScanBudget() time.Duration {
	if db == nil {
		return 0
	}
	budget := db.retainedPruneFullLiveIDScanBudget
	if budget < 0 {
		return 0
	}
	if budget == 0 {
		return retainedPruneDefaultFullLiveIDScanBudget
	}
	return budget
}

func (db *DB) shouldScheduleRetainedValueLogPrune() bool {
	return db.shouldScheduleRetainedValueLogPruneWithForce(false)
}

func (db *DB) shouldScheduleRetainedValueLogPruneWithForce(force bool) bool {
	if db == nil || !db.valueLogEnabled() {
		return false
	}
	closed := db.valueLogRetainedClosedBytes.Load()
	if closed <= 0 {
		return false
	}
	if force {
		return true
	}
	return closed >= db.retainedPrunePressureBytes()
}

type retainedPruneQuietWaitResult uint8

const (
	retainedPruneQuietWaitAdmitted retainedPruneQuietWaitResult = iota
	retainedPruneQuietWaitForced
	retainedPruneQuietWaitBelowPressure
	retainedPruneQuietWaitStopped
)

func (db *DB) waitForRetainedValueLogPruneQuietOrForce(quietWindow time.Duration) retainedPruneQuietWaitResult {
	if db == nil {
		return retainedPruneQuietWaitStopped
	}
	if quietWindow <= 0 {
		if db.retainedPruneForceRequested.Swap(false) {
			return retainedPruneQuietWaitForced
		}
		return retainedPruneQuietWaitAdmitted
	}
	ticker := time.NewTicker(foregroundMaintenancePollInterval())
	defer ticker.Stop()
	for {
		if db.closing.Load() {
			if db.retainedPruneForceRequested.Swap(false) {
				return retainedPruneQuietWaitForced
			}
			return retainedPruneQuietWaitStopped
		}
		if db.retainedPruneForceRequested.Swap(false) {
			return retainedPruneQuietWaitForced
		}
		if !db.shouldScheduleRetainedValueLogPruneWithForce(false) {
			return retainedPruneQuietWaitBelowPressure
		}
		if db.foregroundVlogMaintenanceQuietFor(time.Now(), quietWindow) {
			// Re-check immediately before returning so force requests racing with
			// the quiet-window transition are not dropped.
			if db.retainedPruneForceRequested.Swap(false) {
				return retainedPruneQuietWaitForced
			}
			return retainedPruneQuietWaitAdmitted
		}
		select {
		case <-db.closeCh:
			if db.retainedPruneForceRequested.Swap(false) {
				return retainedPruneQuietWaitForced
			}
			return retainedPruneQuietWaitStopped
		case <-ticker.C:
		}
	}
}

func (db *DB) queueRetainedPruneObservedSourceIDs(ids []uint32) {
	if db == nil || len(ids) == 0 {
		return
	}
	db.retainedPruneObservedMu.Lock()
	if db.retainedPruneObservedSourceIDs == nil {
		db.retainedPruneObservedSourceIDs = make(map[uint32]struct{}, len(ids))
	}
	for _, id := range ids {
		if id == 0 {
			continue
		}
		db.retainedPruneObservedSourceIDs[id] = struct{}{}
	}
	db.retainedPruneObservedMu.Unlock()
}

func (db *DB) takeRetainedPruneObservedSourceIDs() map[uint32]struct{} {
	if db == nil {
		return nil
	}
	db.retainedPruneObservedMu.Lock()
	if len(db.retainedPruneObservedSourceIDs) == 0 {
		db.retainedPruneObservedMu.Unlock()
		return nil
	}
	out := db.retainedPruneObservedSourceIDs
	db.retainedPruneObservedSourceIDs = nil
	db.retainedPruneObservedMu.Unlock()
	return out
}

func (db *DB) retainedPruneObservedSourcePending() bool {
	if db == nil {
		return false
	}
	db.retainedPruneObservedMu.Lock()
	pending := len(db.retainedPruneObservedSourceIDs) > 0
	db.retainedPruneObservedMu.Unlock()
	return pending
}

func (db *DB) queueVlogGenerationObservedSourceGCList(ids []uint32) {
	if db == nil || len(ids) == 0 {
		return
	}
	nowUnixNano := time.Now().UnixNano()
	db.vlogGenerationObservedGCMu.Lock()
	if db.vlogGenerationObservedGCSourceIDs == nil {
		db.vlogGenerationObservedGCSourceIDs = make(map[uint32]struct{}, len(ids))
	}
	if db.vlogGenerationObservedGCFirstQueuedUnixNano == nil {
		db.vlogGenerationObservedGCFirstQueuedUnixNano = make(map[uint32]int64, len(ids))
	}
	added := 0
	for _, id := range ids {
		if id == 0 {
			continue
		}
		if _, exists := db.vlogGenerationObservedGCSourceIDs[id]; exists {
			continue
		}
		db.vlogGenerationObservedGCSourceIDs[id] = struct{}{}
		if _, exists := db.vlogGenerationObservedGCFirstQueuedUnixNano[id]; !exists {
			db.vlogGenerationObservedGCFirstQueuedUnixNano[id] = nowUnixNano
		}
		added++
	}
	db.vlogGenerationObservedGCMu.Unlock()
	if added > 0 {
		db.vlogGenerationObservedGCQueuedBatches.Add(1)
		db.vlogGenerationObservedGCQueuedIDs.Add(uint64(added))
	}
}

func (db *DB) queueVlogGenerationObservedSourceGCIDs(ids map[uint32]struct{}) {
	if db == nil || len(ids) == 0 {
		return
	}
	nowUnixNano := time.Now().UnixNano()
	db.vlogGenerationObservedGCMu.Lock()
	if db.vlogGenerationObservedGCSourceIDs == nil {
		db.vlogGenerationObservedGCSourceIDs = make(map[uint32]struct{}, len(ids))
	}
	if db.vlogGenerationObservedGCFirstQueuedUnixNano == nil {
		db.vlogGenerationObservedGCFirstQueuedUnixNano = make(map[uint32]int64, len(ids))
	}
	added := 0
	for id := range ids {
		if id == 0 {
			continue
		}
		if _, exists := db.vlogGenerationObservedGCSourceIDs[id]; exists {
			continue
		}
		db.vlogGenerationObservedGCSourceIDs[id] = struct{}{}
		if _, exists := db.vlogGenerationObservedGCFirstQueuedUnixNano[id]; !exists {
			db.vlogGenerationObservedGCFirstQueuedUnixNano[id] = nowUnixNano
		}
		added++
	}
	db.vlogGenerationObservedGCMu.Unlock()
	if added > 0 {
		db.vlogGenerationObservedGCQueuedBatches.Add(1)
		db.vlogGenerationObservedGCQueuedIDs.Add(uint64(added))
	}
}

func (db *DB) takeVlogGenerationObservedSourceGCListBefore(cutoffUnixNano int64) []uint32 {
	if db == nil {
		return nil
	}
	db.vlogGenerationObservedGCMu.Lock()
	if len(db.vlogGenerationObservedGCSourceIDs) == 0 {
		db.vlogGenerationObservedGCMu.Unlock()
		return nil
	}
	remaining := make(map[uint32]struct{}, len(db.vlogGenerationObservedGCSourceIDs))
	out := make([]uint32, 0, len(db.vlogGenerationObservedGCSourceIDs))
	for id := range db.vlogGenerationObservedGCSourceIDs {
		if id == 0 {
			continue
		}
		firstQueued := int64(0)
		if db.vlogGenerationObservedGCFirstQueuedUnixNano != nil {
			firstQueued = db.vlogGenerationObservedGCFirstQueuedUnixNano[id]
		}
		if cutoffUnixNano > 0 && firstQueued > cutoffUnixNano {
			remaining[id] = struct{}{}
			continue
		}
		out = append(out, id)
	}
	if len(remaining) == 0 {
		db.vlogGenerationObservedGCSourceIDs = nil
	} else {
		db.vlogGenerationObservedGCSourceIDs = remaining
	}
	db.vlogGenerationObservedGCMu.Unlock()
	if len(out) > 0 {
		db.vlogGenerationObservedGCTakenBatches.Add(1)
		db.vlogGenerationObservedGCTakenIDs.Add(uint64(len(out)))
	}
	return out
}

func (db *DB) takeVlogGenerationObservedSourceGCList() []uint32 {
	return db.takeVlogGenerationObservedSourceGCListBefore(0)
}

func (db *DB) finalizeVlogGenerationObservedSourceGCIDs(ids []uint32, dropped bool) {
	if db == nil || len(ids) == 0 {
		return
	}
	nowUnixNano := time.Now().UnixNano()
	totalLatencyMS := uint64(0)
	maxLatencyMS := uint64(0)
	finalized := 0
	seen := make(map[uint32]struct{}, len(ids))
	db.vlogGenerationObservedGCMu.Lock()
	for _, id := range ids {
		if id == 0 {
			continue
		}
		if _, exists := seen[id]; exists {
			continue
		}
		seen[id] = struct{}{}
		finalized++
		delete(db.vlogGenerationObservedGCRetryAttempts, id)
		if startUnixNano, exists := db.vlogGenerationObservedGCFirstQueuedUnixNano[id]; exists {
			delete(db.vlogGenerationObservedGCFirstQueuedUnixNano, id)
			if startUnixNano > 0 && nowUnixNano > startUnixNano {
				latencyMS := uint64((nowUnixNano - startUnixNano) / int64(time.Millisecond))
				totalLatencyMS += latencyMS
				if latencyMS > maxLatencyMS {
					maxLatencyMS = latencyMS
				}
			}
		}
	}
	db.vlogGenerationObservedGCMu.Unlock()
	if finalized == 0 {
		return
	}
	if dropped {
		db.vlogGenerationObservedGCLatencyDroppedIDs.Add(uint64(finalized))
	} else {
		db.vlogGenerationObservedGCLatencyCompletedIDs.Add(uint64(finalized))
	}
	if totalLatencyMS > 0 {
		db.vlogGenerationObservedGCLatencyTotalMS.Add(totalLatencyMS)
		updateAtomicMaxUint64(&db.vlogGenerationObservedGCLatencyMaxMS, maxLatencyMS)
	}
}

func (db *DB) retryVlogGenerationObservedSourceGCList(ids []uint32) (queuedIDs, droppedIDs int) {
	if db == nil || len(ids) == 0 {
		return 0, 0
	}
	retry := make([]uint32, 0, len(ids))
	dropped := make([]uint32, 0, len(ids))
	seen := make(map[uint32]struct{}, len(ids))
	db.vlogGenerationObservedGCMu.Lock()
	if db.vlogGenerationObservedGCRetryAttempts == nil {
		db.vlogGenerationObservedGCRetryAttempts = make(map[uint32]uint8, len(ids))
	}
	for _, id := range ids {
		if id == 0 {
			continue
		}
		if _, exists := seen[id]; exists {
			continue
		}
		seen[id] = struct{}{}
		attempts := db.vlogGenerationObservedGCRetryAttempts[id]
		if attempts >= vlogGenerationObservedGCRetryMaxAttempts {
			delete(db.vlogGenerationObservedGCRetryAttempts, id)
			dropped = append(dropped, id)
			continue
		}
		db.vlogGenerationObservedGCRetryAttempts[id] = attempts + 1
		retry = append(retry, id)
	}
	db.vlogGenerationObservedGCMu.Unlock()
	if len(retry) > 0 {
		db.vlogGenerationObservedGCRetryQueued.Add(1)
		db.queueVlogGenerationObservedSourceGCList(retry)
	}
	if len(dropped) > 0 {
		db.vlogGenerationObservedGCRetryDropped.Add(uint64(len(dropped)))
		db.finalizeVlogGenerationObservedSourceGCIDs(dropped, true)
	}
	return len(retry), len(dropped)
}

func (db *DB) scheduleRetainedValueLogPrune() {
	db.scheduleRetainedValueLogPruneWithForce(false)
}

func (db *DB) scheduleRetainedValueLogPruneForce() {
	db.scheduleRetainedValueLogPruneWithForce(true)
}

func (db *DB) scheduleRetainedValueLogPruneWithForce(force bool) {
	if db == nil || !db.valueLogEnabled() {
		return
	}
	db.retainedValueLogPruneScheduleRequests.Add(1)
	if force {
		db.retainedPruneForceRequested.Store(true)
		db.retainedValueLogPruneScheduleForcedRequests.Add(1)
	}
	if db.testSkipRetainedPrune {
		return
	}
	db.retainedPruneMu.Lock()
	if db.closing.Load() {
		db.retainedValueLogPruneScheduleSkipClosing.Add(1)
		db.retainedPruneMu.Unlock()
		db.observeRetainedValueLogPruneCloseAbort(force, false, 0)
		return
	}
	if db.retainedPruneDone != nil {
		inFlightDone := db.retainedPruneDone
		db.retainedValueLogPruneScheduleSkipInFlight.Add(1)
		db.retainedPruneMu.Unlock()
		if force && inFlightDone != nil {
			// Force requests that arrive while a prune is in-flight should get a
			// follow-up attempt immediately after the active prune exits.
			db.wg.Add(1)
			go func(done <-chan struct{}) {
				defer db.wg.Done()
				if done != nil {
					<-done
				}
				if db == nil || db.closing.Load() {
					return
				}
				if db.retainedPruneForceRequested.Load() {
					db.scheduleRetainedValueLogPruneWithForce(false)
				}
			}(inFlightDone)
		}
		return
	}
	done := make(chan struct{})
	db.retainedPruneDone = done
	db.retainedPruneMu.Unlock()
	go func() {
		var pruneCancel context.CancelCauseFunc
		defer func() {
			if pruneCancel != nil {
				pruneCancel(context.Canceled)
			}
			db.retainedPruneMu.Lock()
			close(done)
			if db.retainedPruneRunningDone == done {
				db.retainedPruneRunningDone = nil
				db.retainedPruneCancel = nil
			}
			db.retainedPruneDone = nil
			db.retainedPruneMu.Unlock()
		}()
		requestedForce := db.retainedPruneForceRequested.Swap(false)
		effectiveForce := force || requestedForce
		if !effectiveForce {
			quietWaitResult := db.waitForRetainedValueLogPruneQuietOrForce(retainedPruneQuietWindow)
			if hook := db.testRetainedPruneQuietWaitExitHook; hook != nil {
				hook(quietWaitResult)
			}
			switch quietWaitResult {
			case retainedPruneQuietWaitForced:
				effectiveForce = true
			case retainedPruneQuietWaitBelowPressure:
				db.retainedValueLogPruneScheduleSkipBelowPressure.Add(1)
				return
			case retainedPruneQuietWaitStopped:
				if db.closing.Load() {
					db.retainedValueLogPruneScheduleSkipClosing.Add(1)
					db.observeRetainedValueLogPruneCloseAbort(false, false, 0)
				}
				return
			}
		}
		if !db.shouldScheduleRetainedValueLogPruneWithForce(effectiveForce) {
			closed := db.valueLogRetainedClosedBytes.Load()
			if closed <= 0 {
				db.retainedValueLogPruneScheduleSkipNoClosedBytes.Add(1)
			} else if !effectiveForce && closed < db.retainedPrunePressureBytes() {
				db.retainedValueLogPruneScheduleSkipBelowPressure.Add(1)
			}
			return
		}
		// Retained prune is opportunistic reclaim; do not compete with checkpoint
		// cutovers or other backend maintenance windows. Mark it running only now,
		// after quiet-window admission and pressure checks have passed. Scheduled
		// quiet-wait sleepers must not block generational maintenance.
		pruneCtx, cancel := context.WithCancelCause(context.Background())
		pruneCancel = cancel
		db.retainedPruneMu.Lock()
		db.retainedPruneRunningDone = done
		db.retainedPruneCancel = cancel
		db.retainedPruneMu.Unlock()
		db.checkpointMu.Lock()
		for db.checkpointing.Load() || db.maintenanceActive.Load() {
			if db.closing.Load() {
				db.checkpointMu.Unlock()
				db.observeRetainedValueLogPruneCloseAbort(effectiveForce, false, 0)
				return
			}
			db.checkpointCond.Wait()
		}
		db.checkpointMu.Unlock()
		now := time.Now()
		minInterval := retainedPruneMinInterval
		if effectiveForce && db.retainedPruneObservedSourcePending() {
			minInterval = retainedPruneObservedMinInterval
		}
		last := db.retainedPruneLastStartUnixNano.Load()
		if last > 0 && now.Sub(time.Unix(0, last)) < minInterval {
			db.retainedValueLogPruneScheduleSkipMinInterval.Add(1)
			return
		}
		db.retainedPruneLastStartUnixNano.Store(now.UnixNano())
		db.retainedValueLogPruneRuns.Add(1)
		if effectiveForce {
			db.retainedValueLogPruneForcedRuns.Add(1)
		}
		db.retainedValueLogPruneLastUnixNano.Store(now.UnixNano())
		observedSourceIDs := db.takeRetainedPruneObservedSourceIDs()
		db.observeRetainedValueLogPruneStart(effectiveForce, len(observedSourceIDs), false, now)
		pruneStats := db.pruneRetainedValueLogsWithObservedContextOptions(pruneCtx, effectiveForce, observedSourceIDs, retainedValueLogPruneRunOptions{
			fullLiveIDScanBudget: db.retainedPruneBackgroundFullLiveIDScanBudget(),
		})
		pruneStats.ElapsedNanos = time.Since(now).Nanoseconds()
		db.observeRetainedValueLogPruneStats(pruneStats)
		if len(observedSourceIDs) > 0 && (pruneStats.ObservedSourceZombieMarkedSegments > 0 || pruneStats.ObservedSourceRemovedSegments > 0) {
			// When a retained prune processes rewrite-observed source segments,
			// queue a near-term maintenance pass so GC can re-check reclaim state.
			db.queueVlogGenerationObservedSourceGCIDs(observedSourceIDs)
			db.vlogGenerationCheckpointKickPending.Store(true)
		}
	}()
}

func (db *DB) retainedPruneActive() bool {
	if db == nil || !db.valueLogEnabled() {
		return false
	}
	db.retainedPruneMu.Lock()
	defer db.retainedPruneMu.Unlock()
	return db.retainedPruneRunningDone != nil
}

func (db *DB) cancelActiveRetainedValueLogPrune() {
	if db == nil || !db.valueLogEnabled() {
		return
	}
	db.retainedPruneMu.Lock()
	cancel := db.retainedPruneCancel
	db.retainedPruneMu.Unlock()
	if cancel != nil {
		cancel(errRetainedPruneCloseCanceled)
	}
	if db.checkpointCond != nil {
		db.checkpointMu.Lock()
		db.checkpointCond.Broadcast()
		db.checkpointMu.Unlock()
	}
}

func (db *DB) waitForRetainedValueLogPrune() {
	if db == nil || !db.valueLogEnabled() {
		return
	}
	db.retainedPruneMu.Lock()
	done := db.retainedPruneDone
	db.retainedPruneMu.Unlock()
	if done != nil {
		<-done
	}
}

func (db *DB) waitForActiveRetainedValueLogPrune() {
	if db == nil || !db.valueLogEnabled() {
		return
	}
	db.retainedPruneMu.Lock()
	done := db.retainedPruneRunningDone
	db.retainedPruneMu.Unlock()
	if done != nil {
		<-done
	}
}

func (db *DB) runRetainedValueLogPruneInline(force bool, observedSourceIDs map[uint32]struct{}) (retainedValueLogPruneStats, bool) {
	return db.runRetainedValueLogPruneInlineWithContext(context.Background(), force, observedSourceIDs)
}

func (db *DB) runRetainedValueLogPruneInlineWithContext(ctx context.Context, force bool, observedSourceIDs map[uint32]struct{}) (retainedValueLogPruneStats, bool) {
	var out retainedValueLogPruneStats
	if db == nil || !db.valueLogEnabled() {
		return out, false
	}
	if ctx == nil {
		ctx = context.Background()
	}
	db.retainedPruneMu.Lock()
	if db.closing.Load() {
		db.retainedPruneMu.Unlock()
		db.observeRetainedValueLogPruneCloseAbort(force, true, 0)
		return out, false
	}
	if db.retainedPruneDone != nil {
		db.retainedPruneMu.Unlock()
		return out, false
	}
	done := make(chan struct{})
	pruneCtx, pruneCancel := context.WithCancelCause(ctx)
	db.retainedPruneDone = done
	db.retainedPruneRunningDone = done
	db.retainedPruneCancel = pruneCancel
	db.retainedPruneMu.Unlock()
	defer func() {
		pruneCancel(context.Canceled)
		db.retainedPruneMu.Lock()
		close(done)
		if db.retainedPruneRunningDone == done {
			db.retainedPruneRunningDone = nil
			db.retainedPruneCancel = nil
		}
		db.retainedPruneDone = nil
		db.retainedPruneMu.Unlock()
	}()

	nowPrune := time.Now()
	db.retainedPruneLastStartUnixNano.Store(nowPrune.UnixNano())
	db.retainedValueLogPruneRuns.Add(1)
	if force {
		db.retainedValueLogPruneForcedRuns.Add(1)
	}
	db.retainedValueLogPruneLastUnixNano.Store(nowPrune.UnixNano())
	db.observeRetainedValueLogPruneStart(force, len(observedSourceIDs), true, nowPrune)
	out = db.pruneRetainedValueLogsWithObservedContext(pruneCtx, force, observedSourceIDs)
	out.ElapsedNanos = time.Since(nowPrune).Nanoseconds()
	db.observeRetainedValueLogPruneStats(out)
	return out, true
}

func (db *DB) checkpointForBackendMaintenance() error {
	return db.runWithBackendMaintenance(nil)
}

type backendMaintenanceOptions struct {
	skipCheckpoint        bool
	skipRetainedPruneWait bool
}

func (db *DB) runWithBackendMaintenance(fn func() error) error {
	return db.runWithBackendMaintenanceOptions(backendMaintenanceOptions{}, fn)
}

func (db *DB) runWithBackendMaintenanceOptions(opts backendMaintenanceOptions, fn func() error) error {
	if db == nil {
		if fn != nil {
			return fn()
		}
		return nil
	}
	db.checkpointMu.Lock()
	for db.checkpointing.Load() || db.maintenanceActive.Load() {
		db.checkpointCond.Wait()
	}
	// Publish the maintenance-active flag while checkpointMu is held so Checkpoint
	// and background maintenance serialize through the same mutex/cond state.
	db.maintenanceActive.Store(true)
	db.checkpointMu.Unlock()
	defer func() {
		db.checkpointMu.Lock()
		db.maintenanceActive.Store(false)
		db.checkpointCond.Broadcast()
		db.checkpointMu.Unlock()
	}()
	if !opts.skipCheckpoint {
		if err := db.Checkpoint(); err != nil {
			return err
		}
	}
	if refresher, ok := db.backend.(valueLogSetRefresher); ok {
		if err := refresher.RefreshValueLogSet(); err != nil {
			return err
		}
	}
	var fnErr error
	if fn != nil {
		fnErr = fn()
	}
	if db.closing.Load() {
		return fnErr
	}
	reconcileErr := db.reconcileSplitValueLogWritersAfterBackendMaintenance()
	if fnErr != nil {
		if reconcileErr != nil {
			return errors.Join(fnErr, reconcileErr)
		}
		return fnErr
	}
	return reconcileErr
}

// ReconcileAfterBackendMaintenance refreshes cached-mode value-log readers and
// advances split value-log writers past segments created directly by backend
// maintenance.
func (db *DB) ReconcileAfterBackendMaintenance() error {
	return db.reconcileSplitValueLogWritersAfterBackendMaintenance()
}

func (db *DB) reconcileSplitValueLogWritersAfterBackendMaintenance() error {
	if db == nil || db.closing.Load() {
		return nil
	}
	if db.valueLogReader != nil {
		if err := db.valueLogReader.Refresh(); err != nil {
			return err
		}
	}
	if !db.splitValueLogEnabled() || !db.valueLogEnabled() {
		return nil
	}
	// In cached mode DB.dir is the wal/ directory, not the DB root.
	walDir := db.dir
	segments, _ := listNonEmptySplitLogSegments(walDir, db.valueLogDir, db.leafLogDir)
	maxSeqByLane := make(map[int]int, len(db.lanes)+1)
	for _, seg := range segments {
		if !seg.valueLog {
			continue
		}
		if seg.seq > maxSeqByLane[seg.lane] {
			maxSeqByLane[seg.lane] = seg.seq
		}
	}
	for i := range db.lanes {
		if err := db.advanceValueLogWriterPastObservedSeq(&db.lanes[i], maxSeqByLane[db.lanes[i].id]); err != nil {
			return err
		}
	}
	if db.indexOuterLeavesInValueLog {
		observedMaxSeq := maxSeqByLane[leafLogLaneID]
		db.advanceLeafLogAppendSeqAtLeast(observedMaxSeq)
		for _, l := range db.leafLogAppendLanesSnapshot() {
			if err := db.advanceLeafLogAppendWriterPastObservedSeq(l, observedMaxSeq); err != nil {
				return err
			}
		}
	}
	return nil
}

func (db *DB) advanceLeafLogAppendWriterPastObservedSeq(l *lane, observedMaxSeq int) error {
	if db == nil || l == nil || observedMaxSeq <= 0 {
		return nil
	}
	l.vlogMu.Lock()
	defer l.vlogMu.Unlock()
	if observedMaxSeq <= l.vlogSeq {
		return nil
	}
	if l.vlog == nil {
		l.vlogSeq = observedMaxSeq
		l.vlogPath = ""
		l.vlogCaps = vlogWriterCaps{}
		l.vlogModeSet = false
		l.vlogModeWriter = nil
		return nil
	}
	nextSeq, err := db.nextLeafLogAppendSeq()
	if err != nil {
		return err
	}
	return db.rotateValueLogMuHeldToSeq(l, nextSeq)
}

func (db *DB) advanceValueLogWriterPastObservedSeq(l *lane, observedMaxSeq int) error {
	if db == nil || l == nil || observedMaxSeq <= 0 {
		return nil
	}
	l.vlogMu.Lock()
	defer l.vlogMu.Unlock()
	if observedMaxSeq <= l.vlogSeq {
		return nil
	}
	if l.vlog == nil {
		l.vlogSeq = observedMaxSeq
		l.vlogPath = ""
		l.vlogCaps = vlogWriterCaps{}
		l.vlogModeSet = false
		l.vlogModeWriter = nil
		return nil
	}
	return db.rotateValueLogMuHeldToSeq(l, observedMaxSeq+1)
}

func hashKey(key []byte) uint64 {
	if prefix, ok := mvcckey.VersionAffinityPrefix(key); ok {
		key = prefix
	}
	return xxhash.Sum64(key)
}

func (db *DB) shardIndex(key []byte) int {
	if len(db.mutableShards) <= 1 {
		return 0
	}
	return int(hashKey(key) & db.mutableShardMask)
}

func (db *DB) shardForKey(key []byte) *memShard {
	return &db.mutableShards[db.shardIndex(key)]
}

func (db *DB) laneForShardIndex(shardID int) int {
	if len(db.lanes) == 0 {
		return 0
	}
	if shardID < 0 {
		shardID = 0
	}
	if db.valueLogGenerationPolicy == uint8(backenddb.ValueLogGenerationHotWarmCold) && len(db.valueLogHotLanes) > 0 {
		return db.valueLogHotLanes[shardID%len(db.valueLogHotLanes)]
	}
	return shardID % len(db.lanes)
}

func (db *DB) rebuildGenerationLaneSets() {
	if db == nil {
		return
	}
	db.valueLogHotLanes = db.valueLogHotLanes[:0]
	db.valueLogWarmLanes = db.valueLogWarmLanes[:0]
	db.valueLogColdLanes = db.valueLogColdLanes[:0]
	for i := range db.lanes {
		switch db.lanes[i].vlogGenerationClass {
		case vlogGenerationClassWarm:
			db.valueLogWarmLanes = append(db.valueLogWarmLanes, i)
		case vlogGenerationClassCold:
			db.valueLogColdLanes = append(db.valueLogColdLanes, i)
		default:
			db.valueLogHotLanes = append(db.valueLogHotLanes, i)
		}
	}
	if len(db.valueLogHotLanes) == 0 && len(db.lanes) > 0 {
		db.valueLogHotLanes = append(db.valueLogHotLanes, 0)
	}
}

func (db *DB) valueLogMaxSegmentBytesForLane(l *lane) int64 {
	if db == nil {
		return 0
	}
	// Legacy cap still applies when generation class targets are unset.
	base := db.valueLogMaxSegmentBytes
	if db.valueLogGenerationPolicy != uint8(backenddb.ValueLogGenerationHotWarmCold) || l == nil {
		return base
	}
	target := int64(0)
	if db.isLeafLogAppendLane(l) && db.valueLogGenerationLeafTarget > 0 {
		target = db.valueLogGenerationLeafTarget
	} else {
		switch l.vlogGenerationClass {
		case vlogGenerationClassWarm:
			target = db.valueLogGenerationWarmTarget
		case vlogGenerationClassCold:
			target = db.valueLogGenerationColdTarget
		default:
			target = db.valueLogGenerationHotTarget
		}
	}
	if target <= 0 {
		return base
	}
	if base > 0 && base < target {
		return base
	}
	return target
}

func (db *DB) shardExceedsLimit(shard *memShard, addBytes int64) bool {
	if maxMemtableBytesPerShard <= 0 {
		return false
	}
	return shard.bytes+addBytes > maxMemtableBytesPerShard
}

func (db *DB) newBackendBatchWithSize(size int) batch.Interface {
	if db == nil || db.backend == nil {
		return nil
	}
	type batchSizer interface {
		NewBatchWithSize(size int) batch.Interface
	}
	if size < 0 {
		size = 0
	}
	maxSize := flushBackendBatchInitEntries
	if db != nil && db.flushBackendInitEntries > 0 {
		maxSize = db.flushBackendInitEntries
	}
	if maxSize > 0 && size > maxSize {
		size = maxSize
	}
	if physical, ok := db.backend.(physicalBackendBatchSizer); ok {
		return physical.NewPhysicalBatchWithSize(size)
	}
	if size == 0 {
		if physical, ok := db.backend.(physicalBackendBatcher); ok {
			return physical.NewPhysicalBatch()
		}
	}
	if sizer, ok := db.backend.(batchSizer); ok {
		return sizer.NewBatchWithSize(size)
	}
	return db.backend.NewBatch()
}

// BackendDB defines the subset of treedb.DB needed by CachingDB.
type BackendDB interface {
	Get(key []byte) ([]byte, error)
	GetUnsafe(key []byte) ([]byte, error)
	GetAppend(key, dst []byte) ([]byte, error)
	Has(key []byte) (bool, error)
	Iterator(start, end []byte) (iterator.UnsafeIterator, error)
	ReverseIterator(start, end []byte) (iterator.UnsafeIterator, error)
	NewBatch() batch.Interface
	Close() error
	Print() error
	Stats() map[string]string
}

