type backendStateReader interface {
	State() *backenddb.DBState
}

type backendStateTokenReader interface {
	StateToken() (backenddb.StateToken, bool)
}

func backendMaxEntryRevision(backend BackendDB) page.EntryRevision {
	if backend == nil {
		return page.LegacyEntryRevision
	}
	if reader, ok := backend.(backendStateTokenReader); ok {
		if state, available := reader.StateToken(); available {
			return state.MaxEntryRevision
		}
	}
	if reader, ok := backend.(backendStateReader); ok {
		if state := reader.State(); state != nil {
			return state.MaxEntryRevision
		}
	}
	return page.EntryRevision(parseUintStat(backend.Stats(), "treedb.max_entry_revision"))
}

type backendCheckpointer interface {
	Checkpoint() error
}

func backendSyncBoundary(backend BackendDB) error {
	if backend == nil {
		return errors.New("cachingdb: missing backend")
	}
	if checkpointer, ok := backend.(backendCheckpointer); ok {
		err := checkpointer.Checkpoint()
		// Backend checkpointing establishes the durable boundary before it
		// attempts command-WAL cleanup. Monotonic appends and rotations retain
		// newer generations while old covered segments can still be deleted;
		// only unsafe publication or ownership changes stale the proof.
		if errors.Is(err, backenddb.ErrDurableWALCleanupProofStale) {
			return nil
		}
		return err
	}
	b := backend.NewBatch()
	if b == nil {
		return errors.New("cachingdb: missing backend batch")
	}
	err := b.WriteSync()
	if cerr := b.Close(); err == nil {
		err = cerr
	}
	return err
}

