func resetTimer(t *time.Timer, d time.Duration) {
	if t == nil {
		return
	}
	if !t.Stop() {
		select {
		case <-t.C:
		default:
		}
	}
	t.Reset(d)
}

func (db *DB) effectiveWALBytes() int64 {
	if db == nil {
		return 0
	}
	var total int64
	for i := range db.lanes {
		l := &db.lanes[i]
		total += l.walClosedBytes.Load() + l.walLiveBytes.Load()
	}
	if fn := db.loadAutoCheckpointBytesHook(); fn != nil {
		if external := fn(); external > 0 {
			total += external
		}
	}
	return total
}

func (db *DB) reclaimableWALBytes() int64 {
	if db == nil {
		return 0
	}
	external := int64(0)
	if fn := db.loadAutoCheckpointBytesHook(); fn != nil {
		if v := fn(); v > 0 {
			external = v
		}
	}
	total := int64(0)
	for i := range db.lanes {
		l := &db.lanes[i]
		total += l.walClosedBytes.Load() + l.walLiveBytes.Load()
	}
	if total <= 0 {
		return external
	}
	if !db.walUsesValueLog() {
		return total + external
	}
	_, retained := db.valueLogRetainedStats()
	if retained >= total {
		return external
	}
	return total - retained + external
}

func (db *DB) minIdleCheckpointWALBytes() int64 {
	if db == nil {
		return autoCheckpointMinIdleWALBytesMin
	}
	db.mu.RLock()
	ft := db.flushThreshold
	db.mu.RUnlock()
	min := ft / 16
	if min < autoCheckpointMinIdleWALBytesMin {
		min = autoCheckpointMinIdleWALBytesMin
	}
	if min > autoCheckpointMinIdleWALBytesMax {
		min = autoCheckpointMinIdleWALBytesMax
	}
	return min
}

const (
	commitLogSegmentHeaderBytes        = 8
	commitLogBatchHeaderBytes          = 1 + 4
	commitLogRecordHeaderBytes         = 1 + 2 + 4 + 8 + 8
	commitLogRevisionRecordHeaderBytes = commitLogRecordHeaderBytes + 8
)

func (db *DB) logRecordSize(key, value []byte) int64 {
	return int64(commitLogSegmentHeaderBytes + commitLogBatchHeaderBytes + commitLogRecordHeaderBytes + len(key) + len(value))
}

func (db *DB) logBatchSize(records []logRecord) int64 {
	if len(records) == 0 {
		return 0
	}
	total := commitLogSegmentHeaderBytes + commitLogBatchHeaderBytes
	for _, r := range records {
		total += commitLogRecordHeaderBytesFor(r) + len(r.Key) + len(r.Value)
	}
	return int64(total)
}

func commitLogRecordHeaderBytesFor(record logRecord) int {
	if record.Revision != 0 && record.Revision != record.Seq {
		return commitLogRevisionRecordHeaderBytes
	}
	return commitLogRecordHeaderBytes
}

func (db *DB) assignCommitSeq(records []logRecord) {
	if len(records) == 0 {
		return
	}
	seq := db.nextCommitSeq.Add(1)
	for i := range records {
		records[i].Seq = seq
	}
}

func (db *DB) advanceEntryRevisionFloor(revision page.EntryRevision) {
	if db == nil || revision == page.LegacyEntryRevision {
		return
	}
	target := uint64(revision)
	for {
		cur := db.nextCommitSeq.Load()
		if cur >= target {
			return
		}
		if db.nextCommitSeq.CompareAndSwap(cur, target) {
			return
		}
	}
}

func (db *DB) nextEntryRevision() page.EntryRevision {
	if db == nil {
		return page.LegacyEntryRevision
	}
	return page.EntryRevision(db.nextCommitSeq.Add(1))
}

func (db *DB) prepareEntryRevisionAssignment(entries []batch.Entry) (page.EntryRevision, bool) {
	maxRevision, hasLegacy := pointEntryRevisionStats(entries)
	db.advanceEntryRevisionFloor(maxRevision)
	return maxRevision, hasLegacy
}

func allZeroBytes(p []byte) bool {
	for _, b := range p {
		if b != 0 {
			return false
		}
	}
	return true
}

func sameNonEmptyBytesData(a, b []byte) bool {
	return len(a) > 0 && len(a) == len(b) && &a[0] == &b[0]
}

