	// construction counter. It must stay zero because the point-successor path
	// has no general-merge fallback; any future fallback must increment it at
	// the construction site.
	stats["treedb.cache.point_successor.general_merge_iterators_total"] = fmt.Sprintf("%d", db.pointSuccessorGeneralMergeIteratorsTotal.Load())
	stats["treedb.cache.flush_apply.coordinator.active"] = fmt.Sprintf("%d", db.flushCoordinatorActive.Load())
	stats["treedb.cache.flush_apply.coordinator.active_workers"] = fmt.Sprintf("%d", db.flushCoordinatorActiveWorkers.Load())
	stats["treedb.cache.flush_apply.coordinator.in_flight_bytes"] = fmt.Sprintf("%d", db.flushCoordinatorInFlightBytes.Load())
	deleteRangeSnapshotIterators := db.deleteRangeIterators.Load()
	deleteRangeBackendIterators := db.deleteRangeBackendIterators.Load()
	deleteRangeMemtableIterators := db.deleteRangeMemtableIterators.Load()
	deleteRangeQueueIterators := db.deleteRangeQueueIterators.Load()
	stats["treedb.cache.delete_range.calls_total"] = fmt.Sprintf("%d", db.deleteRangeCalls.Load())
	stats["treedb.cache.delete_range.batch_calls_total"] = fmt.Sprintf("%d", db.deleteRangeBatchCalls.Load())
	stats["treedb.cache.delete_range.batch_writes_total"] = fmt.Sprintf("%d", db.deleteRangeBatchWrites.Load())
	stats["treedb.cache.delete_range.input_ranges_total"] = fmt.Sprintf("%d", db.deleteRangeInputRanges.Load())
	stats["treedb.cache.delete_range.effective_ranges_total"] = fmt.Sprintf("%d", db.deleteRangeEffectiveRanges.Load())
	stats["treedb.cache.delete_range.coalesced_ranges_total"] = fmt.Sprintf("%d", db.deleteRangeCoalescedRanges.Load())
	stats["treedb.cache.delete_range.iterators_total"] = fmt.Sprintf("%d", deleteRangeSnapshotIterators+deleteRangeBackendIterators+deleteRangeMemtableIterators+deleteRangeQueueIterators)
	stats["treedb.cache.delete_range.snapshot_iterators_total"] = fmt.Sprintf("%d", deleteRangeSnapshotIterators)
	stats["treedb.cache.delete_range.backend_iterators_total"] = fmt.Sprintf("%d", deleteRangeBackendIterators)
	stats["treedb.cache.delete_range.memtable_iterators_total"] = fmt.Sprintf("%d", deleteRangeMemtableIterators)
	stats["treedb.cache.delete_range.queue_iterators_total"] = fmt.Sprintf("%d", deleteRangeQueueIterators)
	stats["treedb.cache.delete_range.visited_keys_total"] = fmt.Sprintf("%d", db.deleteRangeVisitedKeys.Load())
	stats["treedb.cache.delete_range.tombstone_keys_total"] = fmt.Sprintf("%d", db.deleteRangeTombstoneKeys.Load())
	stats["treedb.cache.delete_range.materialized_keys_total"] = fmt.Sprintf("%d", db.deleteRangeMaterializedKeys.Load())
	stats["treedb.cache.delete_range.materialized_key_bytes_total"] = fmt.Sprintf("%d", db.deleteRangeMaterializedKeyBytes.Load())
	stats["treedb.cache.delete_range.fast_path_clears_total"] = fmt.Sprintf("%d", db.deleteRangeFastPathClears.Load())
	stats["treedb.cache.delete_range.backend_direct_batches_total"] = fmt.Sprintf("%d", db.deleteRangeBackendDirectBatches.Load())
	stats["treedb.cache.delete_range.backend_direct_keys_total"] = fmt.Sprintf("%d", db.deleteRangeBackendDirectKeys.Load())
	stats["treedb.cache.range_span.layers_total"] = fmt.Sprintf("%d", db.rangeSpanLayersTotal.Load())
	stats["treedb.cache.range_span.active_layers"] = fmt.Sprintf("%d", rangeSpanActiveLayers)
	stats["treedb.cache.range_span.active_spans"] = fmt.Sprintf("%d", rangeSpanActiveSpans)
	stats["treedb.cache.range_span.input_total"] = fmt.Sprintf("%d", db.rangeSpanInputTotal.Load())
	stats["treedb.cache.range_span.effective_total"] = fmt.Sprintf("%d", db.rangeSpanEffectiveTotal.Load())
	stats["treedb.cache.range_span.keys_materialized_total"] = fmt.Sprintf("%d", db.rangeSpanKeysMaterializedTotal.Load())
	stats["treedb.cache.range_span.point_overrides_total"] = fmt.Sprintf("%d", db.rangeSpanPointOverridesTotal.Load())
	stats["treedb.cache.range_span.point_probes_total"] = fmt.Sprintf("%d", db.rangeSpanPointProbes.Load())
	stats["treedb.cache.range_span.point_hits_total"] = fmt.Sprintf("%d", db.rangeSpanPointHits.Load())
	stats["treedb.cache.range_span.iterator_probes_total"] = fmt.Sprintf("%d", db.rangeSpanIteratorProbes.Load())
	stats["treedb.cache.range_span.iterator_skips_total"] = fmt.Sprintf("%d", db.rangeSpanIteratorSkips.Load())
	stats["treedb.cache.range_span.range_only_queued_units_total"] = fmt.Sprintf("%d", db.rangeSpanRangeOnlyQueuedUnits.Load())
	stats["treedb.cache.range_span.range_only_flushed_total"] = fmt.Sprintf("%d", db.rangeSpanRangeOnlyFlushed.Load())
	stats["treedb.cache.range_span.spans_flushed_total"] = fmt.Sprintf("%d", db.rangeSpanSpansFlushed.Load())
	stats["treedb.cache.range_span.flush_batches_total"] = fmt.Sprintf("%d", db.rangeSpanFlushBatches.Load())
	db.conditionalOracle.mu.Lock()
	conditionalActiveRecords := len(db.conditionalOracle.active)
	conditionalRetainedPoints := len(db.conditionalOracle.recent)
	conditionalRetainedRanges := len(db.conditionalOracle.ranges)
	conditionalRootConflictActive := db.conditionalOracle.rootSeq != 0
	db.conditionalOracle.mu.Unlock()
	stats["treedb.cache.conditional_txn.active"] = fmt.Sprintf("%d", db.conditionalActiveTxnCount.Load())
	stats["treedb.cache.conditional_txn.started_total"] = fmt.Sprintf("%d", db.conditionalTxnStarted.Load())
	stats["treedb.cache.conditional_txn.closed_total"] = fmt.Sprintf("%d", db.conditionalTxnClosed.Load())
	stats["treedb.cache.conditional_txn.commit_attempts_total"] = fmt.Sprintf("%d", db.conditionalTxnCommitAttempts.Load())
	stats["treedb.cache.conditional_txn.commits_total"] = fmt.Sprintf("%d", db.conditionalTxnCommits.Load())
	stats["treedb.cache.conditional_txn.conflicts_total"] = fmt.Sprintf("%d", db.conditionalTxnConflicts.Load())
	stats["treedb.cache.conditional_txn.read_set.samples_total"] = fmt.Sprintf("%d", db.conditionalTxnReadSetSamples.Load())
	stats["treedb.cache.conditional_txn.read_set.entries_total"] = fmt.Sprintf("%d", db.conditionalTxnReadSetEntries.Load())
	stats["treedb.cache.conditional_txn.read_set.max"] = fmt.Sprintf("%d", db.conditionalTxnReadSetMax.Load())
