func appendUniqueMemtable(dst []memtable.Table, mt memtable.Table) []memtable.Table {
	if mt == nil {
		return dst
	}
	for _, existing := range dst {
		if existing == mt {
			return dst
		}
	}
	return append(dst, mt)
}

func batchShardFirstLast(entries []batch.Entry, shardIdxs []int, shardIndex int) (first, last []byte) {
	for i := range entries {
		if i >= len(shardIdxs) || shardIdxs[i] != shardIndex {
			continue
		}
		key := entries[i].Key
		if first == nil {
			first = key
		}
		last = key
	}
	return first, last
}

func (b *Batch) canApplySmallSelectedSortedShard(shardCounts []int, allowBatchArenaBorrow, allowStableViewValueBorrow bool) bool {
	if b == nil || b.db == nil || !b.streamEligible || len(b.entries) == 0 || len(b.entries) > batchSelectedSortedShardMaxEntries {
		return false
	}
	for i, count := range shardCounts {
		if count <= 0 {
			continue
		}
		shard := &b.db.mutableShards[i]
		// Iterator rotation replaces shard.mem while holding db.mu then shard.mu.
		// This precheck takes only shard.mu, releases it before returning, and the
		// apply phase below locks the shard and rechecks the selected interface.
		shard.mu.Lock()
		mem := shard.mem
		useSteal, _ := cachedBatchWriteUseSteal(b.db, mem)
		useSteal = allowBatchArenaBorrow && useSteal
		eligible := false
		if !useSteal {
			switch {
			case allowStableViewValueBorrow:
				_, eligible = mem.(memtable.CopySelectedSortedBatchApplier)
			case !allowBatchArenaBorrow:
				_, eligible = mem.(memtable.CopySelectedSortedBatchValueCopier)
			default:
				_, eligible = mem.(memtable.CopySelectedSortedBatchApplier)
			}
		}
		shard.mu.Unlock()
		if !eligible {
			return false
		}
	}
	return true
}

func (b *Batch) tryApplySmallSelectedSortedShard(
	shardCounts []int,
	shardIdxs []int,
	allowBatchArenaBorrow bool,
	allowStableViewValueBorrow bool,
	retainMainMems *[]memtable.Table,
	retainStableViewValueMems *[]memtable.Table,
	failMemtableApply func(*memShard, error) error,
) (bool, error) {
	if !b.canApplySmallSelectedSortedShard(shardCounts, allowBatchArenaBorrow, allowStableViewValueBorrow) {
		return false, nil
	}
	storeInlinePtrValues := !b.db.memtableValueLogPointers
	for i, count := range shardCounts {
		if count <= 0 {
			continue
		}
		first, last := batchShardFirstLast(b.entries, shardIdxs, i)
		if first == nil {
			continue
		}
		shard := &b.db.mutableShards[i]
		shard.mu.Lock()
		reserveMemtableEntries(b.db, shard.mem, count)
		if allowStableViewValueBorrow {
			applier, ok := shard.mem.(memtable.CopySelectedSortedBatchApplier)
			if !ok {
				return true, failMemtableApply(shard, fmt.Errorf("cachingdb: memtable %T lost selected sorted batch support", shard.mem))
			}
			if borrowed := applier.ApplyCopySelectedSortedBatchTrusted(b.entries, shardIdxs, i, count, first, true, storeInlinePtrValues, nil); borrowed {
				*retainStableViewValueMems = appendUniqueMemtable(*retainStableViewValueMems, shard.mem)
			}
		} else if !allowBatchArenaBorrow {
			applier, ok := shard.mem.(memtable.CopySelectedSortedBatchValueCopier)
			if !ok {
				return true, failMemtableApply(shard, fmt.Errorf("cachingdb: memtable %T lost selected sorted batch value-copier support", shard.mem))
			}
			applier.ApplyCopySelectedSortedBatchWithValueCopierTrusted(b.entries, shardIdxs, i, count, first, b.appendOnlyDirectValueCopierForShard(shard), storeInlinePtrValues, nil)
			b.valueCopyShard = nil
		} else {
			applier, ok := shard.mem.(memtable.CopySelectedSortedBatchApplier)
			if !ok {
				return true, failMemtableApply(shard, fmt.Errorf("cachingdb: memtable %T lost selected sorted batch support", shard.mem))
			}
			if borrowed := applier.ApplyCopySelectedSortedBatchTrusted(b.entries, shardIdxs, i, count, first, allowBatchArenaBorrow, storeInlinePtrValues, nil); borrowed {
				*retainMainMems = appendUniqueMemtable(*retainMainMems, shard.mem)
			}
		}
		shard.rng.add(first)
		if count > 1 {
			shard.rng.add(last)
		}
		b.db.noteWriteSortedRun(first, last, count)
		newBytes := shard.mem.Size()
		delta := newBytes - shard.bytes
		shard.bytes = newBytes
		b.db.mutableBytes.Add(delta)
		shard.mu.Unlock()
	}
	return true, nil
}

func (b *Batch) appendOnlyDirectValueCopierForShard(shard *memShard) func([]byte) []byte {
	if b == nil || shard == nil {
		return nil
	}
	b.valueCopyShard = shard
	if b.appendOnlyDirectValueCopier == nil {
		b.appendOnlyDirectValueCopier = b.copyValueToAppendOnlyDirectArena
	}
	return b.appendOnlyDirectValueCopier
}

func (b *Batch) copyValueToAppendOnlyDirectArena(value []byte) []byte {
	if b == nil || b.valueCopyShard == nil || len(value) == 0 {
		return nil
	}
	owned := b.valueCopyShard.appendOnlyDirectValueArena.alloc(len(value))
	copy(owned, value)
	return owned
}

// Reset clears the batch for reuse without closing it.
//
// This intentionally keeps internal buffers to avoid per-batch allocations in
// callers that frequently reset (e.g. geth benchmarks).
func (b *Batch) Reset() {
	if b == nil {
		return
	}
	if b.backend != nil {
		_ = b.backend.Close()
		b.backend = nil
	}
	if b.entries != nil {
		b.entries = b.entries[:0]
	}
	if b.shardIdxs != nil {
		b.shardIdxs = b.shardIdxs[:0]
	}
	if b.shardAdds != nil {
		b.shardAdds = b.shardAdds[:0]
	}
	if b.eligibleIdxs != nil {
		b.eligibleIdxs = b.eligibleIdxs[:0]
	}
	if b.shardCnts != nil {
		b.shardCnts = b.shardCnts[:0]
	}
	if b.shardEntries != nil {
		b.shardEntries = b.shardEntries[:0]
	}
	if b.shardIdxSets != nil {
		b.shardIdxSets = b.shardIdxSets[:0]
	}
	b.recycleCopyArenaChunks()
	b.recyclePtrCopyArenaChunks()
	if b.arenaInFlightBytes > 0 {
		b.subArenaInFlightBytes(b.arenaInFlightBytes)
	}
	if b.db != nil {
		b.copyArenaCap = b.db.batchCopyArenaInitCap(0)
	}
	b.size = 0
	b.walBuf = b.walBuf[:0]
	b.streamEligible = true
	b.streamTried = false
	b.streamBypassOff = false
	b.hasViewOps = false
	b.stableViewValueLeaseChunks = nil
	b.firstKey = nil
	b.lastKey = nil
	b.batchRange = keyRange{}
	b.resetBackendConditionalEntries()
	b.hasDeleteRanges = false
	b.entryRevision = page.LegacyEntryRevision
	b.maxEntries = 0
	b.commandWALAppend = nil
	b.commandWALPreparedRevision = false
	b.commandWALMaterializedRID = false
	b.valueCopyShard = nil
	b.commandWALCompactReplay = false
	b.commandWALCompactRanges = nil
	b.commandWALCompactPointStart = 0
	b.conditionalTxnID = 0
	if b.ptrValueIdxs != nil {
		b.ptrValueIdxs = b.ptrValueIdxs[:0]
	}
}

func (b *Batch) noteEntryAppend() {
	if b == nil {
		return
	}
	if n := len(b.entries); n > b.maxEntries {
		b.maxEntries = n
	}
}

func (b *Batch) updateBatchEntryHint() {
	if b == nil || b.db == nil {
		return
	}
	n := b.maxEntries
	if n <= 0 {
		n = len(b.entries)
	}
	if n > 0 {
		b.db.observeBatchEntries(n)
	}
}

func (b *Batch) drainCopyArenaChunks() [][]byte {
	if b == nil {
		return nil
	}
	if b.db != nil && cap(b.copyArena) > 0 {
		b.db.noteBatchArenaChunkFinalize(batchArenaKindMain, len(b.copyArena), cap(b.copyArena))
	}
	chunks := b.copyArenaChunks
	if bytes := batchArenaChunksCapBytes(chunks); bytes > 0 {
		b.subArenaInFlightBytes(bytes)
	}
	b.copyArenaChunks = nil
	b.copyArena = nil
	b.copyBytes = 0
	return chunks
}

func (b *Batch) recycleCopyArenaChunks() {
	if b == nil {
		return
	}
	chunks := b.drainCopyArenaChunks()
	if len(chunks) == 0 {
		return
	}
	putBatchArenas(chunks)
	if b.db != nil {
		b.db.putBatchArenaChunkListLease(chunks)
	}
}

func (b *Batch) drainPtrCopyArenaChunks() [][]byte {
	if b == nil {
		return nil
	}
	if b.db != nil && cap(b.ptrCopyArena) > 0 {
		b.db.noteBatchArenaChunkFinalize(batchArenaKindPtr, len(b.ptrCopyArena), cap(b.ptrCopyArena))
	}
	chunks := b.ptrCopyArenaChunks
	if bytes := batchArenaChunksCapBytes(chunks); bytes > 0 {
		b.subArenaInFlightBytes(bytes)
	}
	b.ptrCopyArenaChunks = nil
	b.ptrCopyArena = nil
	b.ptrCopyBytes = 0
	return chunks
}

func (b *Batch) recyclePtrCopyArenaChunks() {
	if b == nil {
		return
	}
	chunks := b.drainPtrCopyArenaChunks()
	if len(chunks) == 0 {
		return
	}
	putBatchArenas(chunks)
	if b.db != nil {
		b.db.putBatchArenaChunkListLease(chunks)
	}
}

func (b *Batch) releaseShardEntryGroups(groups [][]batch.Entry) {
	if b == nil || b.db == nil || cap(groups) == 0 {
		return
	}
	full := groups[:cap(groups)]
	for i := range full {
		if full[i] != nil {
			b.db.putBatchShardEntries(full[i])
			full[i] = nil
		}
	}
	b.db.putBatchShardEntryGroups(full[:0])
}

func (b *Batch) updateBatchCopyHint() {
	if b == nil || b.db == nil {
		return
	}
	if n := b.copyBytes; n > 0 {
		b.db.observeBatchCopyBytes(n)
	}
}

func (b *Batch) addArenaInFlightBytes(n int) {
	if b == nil || n <= 0 {
		return
	}
	b.arenaInFlightBytes += int64(n)
	cur := batchArenaInFlightBytes.Add(int64(n))
	noteBatchArenaInFlightBytesMax(cur)
}

func (b *Batch) subArenaInFlightBytes(n int64) {
	if b == nil || n <= 0 {
		return
	}
	if n > b.arenaInFlightBytes {
		n = b.arenaInFlightBytes
	}
	if n <= 0 {
		return
	}
	b.arenaInFlightBytes -= n
	if next := batchArenaInFlightBytes.Add(-n); next < 0 {
		batchArenaInFlightBytes.Store(0)
	}
}

func (b *Batch) arenaCopy(n int) []byte {
	return b.arenaCopyInto(batchArenaKindMain, &b.copyArena, &b.copyArenaChunks, &b.copyBytes, n, b.copyArenaCap)
}

func (b *Batch) arenaCopyPtr(n int) []byte {
	return b.arenaCopyInto(batchArenaKindPtr, &b.ptrCopyArena, &b.ptrCopyArenaChunks, &b.ptrCopyBytes, n, 0)
}

func (b *Batch) arenaCopyInto(kind batchArenaKind, arena *[]byte, chunks *[][]byte, copyBytes *int, n int, initialCap int) []byte {
	if n == 0 {
		return nil
	}
	if cap(*arena)-len(*arena) < n {
		if b != nil && b.db != nil && cap(*arena) > 0 {
			b.db.noteBatchArenaChunkFinalize(kind, len(*arena), cap(*arena))
		}
		chunkCap := cap(*arena) * 2
		if chunkCap < batchCopyArenaMinChunk {
			chunkCap = batchCopyArenaMinChunk
		}
		if cap(*arena) == 0 {
			// Keep unsized batches conservative. Entry-slice capacity can come from
			// pooled high-water marks and is not a reliable signal for copy payload.
			if initialCap > chunkCap {
				chunkCap = initialCap
			}
		}
		if chunkCap < n {
			chunkCap = n
		}
		// Avoid unbounded exponential growth once we reach the pooling limit. Large
		// restore batches can otherwise allocate a huge tail chunk (e.g. 8/16/32MB)
		// that is mostly unused, inflating RSS. Only allow larger chunks when a
		// *single* copy needs it.
		if n <= batchCopyArenaMaxRetain && chunkCap > batchCopyArenaMaxRetain {
			chunkCap = batchCopyArenaMaxRetain
		}
		if maxChunk := currentBatchCopyArenaMaxChunk(); maxChunk > 0 && chunkCap > maxChunk && n <= maxChunk {
			chunkCap = maxChunk
		}
		// Switch to a fresh chunk when exhausted so existing entry slices keep
		// their backing arrays without per-op allocations.
		chunk := getBatchArena(chunkCap)
		if cap(chunk) > 0 {
			b.addArenaInFlightBytes(cap(chunk))
		}
		if b != nil && b.db != nil {
			b.db.noteBatchArenaChunkAlloc(kind, chunkCap, cap(chunk))
		}
		*arena = chunk[:0]
		if b != nil && b.db != nil {
			*chunks = b.db.ensureBatchArenaChunkListAppendCap(*chunks)
		}
		*chunks = append(*chunks, *arena)
	}
	start := len(*arena)
	*arena = (*arena)[:start+n]
	*copyBytes += n
	return (*arena)[start : start+n : start+n]
}

func (b *Batch) cloneKey(key []byte) []byte {
	batchArenaCopyKeyCallsTotal.Add(1)
	if len(key) == 0 {
		return rawKVEmptyPointKey
	}
	batchArenaCopyKeyBytesTotal.Add(uint64(len(key)))
	dst := b.arenaCopy(len(key))
	copy(dst, key)
	return dst
}

func (b *Batch) cloneValue(value []byte) []byte {
	batchArenaCopyValueCallsTotal.Add(1)
	if len(value) == 0 {
		return rawKVEmptyValue
	}
	batchArenaCopyValueBytesTotal.Add(uint64(len(value)))
	dst := b.arenaCopy(len(value))
	copy(dst, value)
	return dst
}

func (b *Batch) cloneKeyValue(key, value []byte) ([]byte, []byte) {
	batchArenaCopyKeyValueCallsTotal.Add(1)
	if n := len(key) + len(value); n > 0 {
		batchArenaCopyKeyValueBytesTotal.Add(uint64(n))
	} else {
		return rawKVEmptyPointKey, rawKVEmptyValue
	}
	buf := b.arenaCopy(len(key) + len(value))
	keyCopy := buf[:len(key):len(key)]
	copy(keyCopy, key)
	valCopy := buf[len(key):]
	copy(valCopy, value)
	return keyCopy, valCopy
}

func (b *Batch) clonePtrValue(value []byte) []byte {
	batchArenaCopyPtrValueCallsTotal.Add(1)
	if len(value) > 0 {
		batchArenaCopyPtrValueBytesTotal.Add(uint64(len(value)))
	}
	dst := b.arenaCopyPtr(len(value))
	copy(dst, value)
	return dst
}

func shouldCompactBatchArenaTailWithPolicy(used, classCap, minWaste, maxFillNumerator, maxFillDenominator int) bool {
	if classCap < batchArenaTailCompactMinCap || used <= 0 || used >= classCap {
		return false
	}
	waste := classCap - used
	if waste < minWaste {
		return false
	}
	return used*maxFillDenominator <= classCap*maxFillNumerator
}

func shouldCompactBatchArenaTail(used, classCap int) bool {
	return shouldCompactBatchArenaTailWithPolicy(
		used,
		classCap,
		batchArenaTailCompactMinWaste,
		batchArenaTailCompactMaxFillNumerator,
		batchArenaTailCompactMaxFillDenominator,
	)
}

func (b *Batch) shouldCompactArenaTail(used, classCap int) bool {
	minWaste := batchArenaTailCompactMinWaste
	maxFillNumerator := batchArenaTailCompactMaxFillNumerator
	maxFillDenominator := batchArenaTailCompactMaxFillDenominator
	if b != nil && b.db != nil && b.db.memtableViewTelemetry.deferredViewsCurrent.Load() > 0 {
		if minWaste > batchArenaTailCompactPinnedMinWaste {
			minWaste = batchArenaTailCompactPinnedMinWaste
		}
		maxFillNumerator = batchArenaTailCompactPinnedMaxFillNumerator
		maxFillDenominator = batchArenaTailCompactPinnedMaxFillDenominator
	}
	return shouldCompactBatchArenaTailWithPolicy(used, classCap, minWaste, maxFillNumerator, maxFillDenominator)
}

func shouldCompactBatchArenaTailWithAliases(used, classCap, aliasedBytes, aliasedSlices int) bool {
	if !shouldCompactBatchArenaTail(used, classCap) || aliasedBytes <= 0 || aliasedSlices <= 0 {
		return false
	}
	return aliasedBytes < classCap
}

func (b *Batch) shouldCompactArenaTailWithAliases(used, classCap, aliasedBytes, aliasedSlices int) bool {
	if b == nil || b.db == nil || aliasedBytes <= 0 || aliasedSlices <= 0 {
		return false
	}
	if !b.shouldCompactArenaTail(used, classCap) {
		return false
	}
	return aliasedBytes < classCap
}

func sliceAliasesArenaTail(s, tail []byte) bool {
	if len(s) == 0 || len(tail) == 0 {
		return false
	}
	sPtr := uintptr(unsafe.Pointer(unsafe.SliceData(s)))
	tPtr := uintptr(unsafe.Pointer(unsafe.SliceData(tail)))
	if sPtr < tPtr {
		return false
	}
	offset := sPtr - tPtr
	if offset > uintptr(len(tail)) {
		return false
	}
	return uintptr(len(s)) <= uintptr(len(tail))-offset
}

func batchMainArenaTailAliasStats(entries []batch.Entry, tail []byte) (aliasedBytes, aliasedSlices int) {
	if len(entries) == 0 || len(tail) == 0 {
		return 0, 0
	}
	for i := range entries {
		op := &entries[i]
		if len(op.Key) > 0 && sliceAliasesArenaTail(op.Key, tail) {
			aliasedBytes += len(op.Key)
			aliasedSlices++
		}
		if len(op.Value) > 0 && sliceAliasesArenaTail(op.Value, tail) {
			aliasedBytes += len(op.Value)
			aliasedSlices++
		}
	}
	return aliasedBytes, aliasedSlices
}

func compactBatchMainArenaTailAliases(entries []batch.Entry, tail []byte, aliasedBytes int) int {
	if len(entries) == 0 || len(tail) == 0 || aliasedBytes <= 0 {
		return 0
	}
	packed := make([]byte, 0, aliasedBytes)
	for i := range entries {
		op := &entries[i]
		if len(op.Key) > 0 && sliceAliasesArenaTail(op.Key, tail) {
			start := len(packed)
			packed = append(packed, op.Key...)
			op.Key = packed[start:len(packed):len(packed)]
		}
		if len(op.Value) > 0 && sliceAliasesArenaTail(op.Value, tail) {
			start := len(packed)
			packed = append(packed, op.Value...)
			op.Value = packed[start:len(packed):len(packed)]
		}
	}
	return len(packed)
}

func (b *Batch) releaseCompactedBatchArenaTail(kind batchArenaKind, chunks *[][]byte, arena *[]byte, copiedBytes int) {
	if b == nil || chunks == nil || arena == nil || len(*chunks) == 0 || cap(*arena) == 0 {
		return
	}
	used := len(*arena)
	classCap := cap(*arena)
	last := len(*chunks) - 1
	tailChunk := (*chunks)[last]
	if tailChunk != nil {
		b.subArenaInFlightBytes(int64(cap(tailChunk)))
		putBatchArena(tailChunk)
	}
	(*chunks)[last] = nil
	*chunks = (*chunks)[:last]
	if b.db != nil {
		b.db.noteBatchArenaChunkFinalize(kind, used, classCap)
		b.db.noteBatchArenaTailCompact(copiedBytes, classCap)
	}
	*arena = nil
}

func (b *Batch) compactUnderfilledMainArenaTail() {
	if b == nil || len(b.entries) == 0 || cap(b.copyArena) == 0 || len(b.copyArenaChunks) == 0 {
		return
	}
	tail := b.copyArena
	aliasedBytes, aliasedSlices := batchMainArenaTailAliasStats(b.entries, tail)
	if !b.shouldCompactArenaTailWithAliases(len(tail), cap(tail), aliasedBytes, aliasedSlices) {
		return
	}
	copiedBytes := compactBatchMainArenaTailAliases(b.entries, tail, aliasedBytes)
	if copiedBytes == 0 {
		return
	}
	b.releaseCompactedBatchArenaTail(batchArenaKindMain, &b.copyArenaChunks, &b.copyArena, copiedBytes)
}

func (b *Batch) compactUnderfilledPtrArenaTail() {
	if b == nil || len(b.entries) == 0 || cap(b.ptrCopyArena) == 0 || len(b.ptrCopyArenaChunks) == 0 {
		return
	}
	tail := b.ptrCopyArena
	if !b.shouldCompactArenaTail(len(tail), cap(tail)) {
		return
	}
	copiedBytes := 0
	for i := range b.entries {
		op := &b.entries[i]
		if len(op.Value) == 0 || !sliceAliasesArenaTail(op.Value, tail) {
			continue
		}
		op.Value = bytes.Clone(op.Value)
		copiedBytes += len(op.Value)
	}
	if copiedBytes == 0 {
		return
	}
	b.releaseCompactedBatchArenaTail(batchArenaKindPtr, &b.ptrCopyArenaChunks, &b.ptrCopyArena, copiedBytes)
}

func (b *Batch) maybeCompactUnderfilledArenaTails() {
	b.compactUnderfilledMainArenaTail()
	b.compactUnderfilledPtrArenaTail()
}

func (b *Batch) resetBackendConditionalEntries() {
	if b == nil || b.backendConditionalEntries == nil {
		return
	}
	if cap(b.backendConditionalEntries) > batchEntriesPoolMaxRetain {
		putEntrySlice(b.backendConditionalEntries)
		b.backendConditionalEntries = nil
		return
	}
	clear(b.backendConditionalEntries[:cap(b.backendConditionalEntries)])
	b.backendConditionalEntries = b.backendConditionalEntries[:0]
}

func (b *Batch) reserveBackendConditionalEntries(additional int) {
	if b == nil || additional <= 0 {
		return
	}
	needed := len(b.backendConditionalEntries) + additional
	if cap(b.backendConditionalEntries) >= needed {
		return
	}
	next := getEntrySlice(needed)
	next = append(next, b.backendConditionalEntries...)
	putEntrySlice(b.backendConditionalEntries)
	b.backendConditionalEntries = next
}

func (b *Batch) appendBackendConditionalEntries(ops []batch.Entry) {
	if b == nil || len(ops) == 0 {
		return
	}
	b.reserveBackendConditionalEntries(len(ops))
	for i := range ops {
		op := ops[i]
		switch op.Type {
		case batch.OpPut, batch.OpDelete:
			b.backendConditionalEntries = append(b.backendConditionalEntries, batch.Entry{
				Type: op.Type,
				Key:  op.Key,
			})
		case batch.OpDeleteRange:
			if batch.IsDeleteRangeNoop(op.Key, op.Value) {
				continue
			}
			b.backendConditionalEntries = append(b.backendConditionalEntries, batch.Entry{
				Type:  op.Type,
				Key:   op.Key,
				Value: op.Value,
			})
		}
	}
}

func (b *Batch) appendBackendConditionalPoint(op batch.OpType, key []byte) {
	if b == nil {
		return
	}
	b.reserveBackendConditionalEntries(1)
	b.backendConditionalEntries = append(b.backendConditionalEntries, batch.Entry{
		Type: op,
		Key:  key,
	})
}

func (b *Batch) shouldCopyValueToPtrArena(key, value []byte) bool {
	if b == nil || b.db == nil || b.backend != nil {
		return false
	}
	// Only split when pointer-in-memtable mode is enabled, meaning the inline
	// value bytes will be discarded once the value-log pointer is assigned.
	if !b.db.memtableValueLogPointers || !b.db.valueLogEnabled() {
		return false
	}
	return b.db.shouldWriteViaValueLogForKeyValue(key, value)
}

func (b *Batch) assignLegacyPointRevisions(entries []batch.Entry) {
	if b == nil || b.db == nil || len(entries) == 0 {
		return
	}
	_, hasLegacy := b.db.prepareEntryRevisionAssignment(entries)
	if !hasLegacy {
		return
	}
	if b.entryRevision == page.LegacyEntryRevision {
		b.entryRevision = b.db.nextEntryRevision()
	}
	assignLegacyPointEntryRevisions(entries, b.entryRevision)
}

func (b *Batch) revisionForBackendPoint(revision page.EntryRevision) page.EntryRevision {
	if revision != page.LegacyEntryRevision {
		if b != nil && b.db != nil {
			b.db.advanceEntryRevisionFloor(revision)
		}
		return revision
	}
	if b == nil || b.db == nil {
		return page.LegacyEntryRevision
	}
	if b.entryRevision == page.LegacyEntryRevision {
		b.entryRevision = b.db.nextEntryRevision()
	}
	return b.entryRevision
}

func (b *Batch) Set(key, value []byte) error {
	return b.SetWithRevision(key, value, page.LegacyEntryRevision)
}

func (b *Batch) SetWithRevision(key, value []byte, revision page.EntryRevision) error {
	if b.closed {
		return ErrBatchClosed
	}
	key = normalizeRawKVPointKey(key)
	value = normalizeRawKVValue(value)
	if hotPathStatsEnabled {
		batchSetCallsTotal.Add(1)
		batchSetBytesTotal.Add(uint64(len(key) + len(value)))
	}
	maybeRecordBatchSetCallerSample(len(key) + len(value))

	idx := len(b.entries)
	var keyCopy, valCopy []byte
	if b.shouldCopyValueToPtrArena(key, value) {
		keyCopy = b.cloneKey(key)
		valCopy = b.clonePtrValue(value)
		b.ptrValueIdxs = append(b.ptrValueIdxs, idx)
	} else {
		keyCopy, valCopy = b.cloneKeyValue(key, value)
	}
	if b.backend != nil {
		b.batchRange.add(keyCopy)
		b.size += len(keyCopy) + len(valCopy)
		revision = b.revisionForBackendPoint(revision)
		var err error
		// Use the backend's view method with owned copies to avoid aliasing.
		if revision != page.LegacyEntryRevision {
			if sv, ok := b.backend.(interface {
				SetViewWithRevision(key, value []byte, revision page.EntryRevision) error
			}); ok {
				err = sv.SetViewWithRevision(keyCopy, valCopy, revision)
			} else if s, ok := b.backend.(interface {
				SetWithRevision(key, value []byte, revision page.EntryRevision) error
			}); ok {
				err = s.SetWithRevision(keyCopy, valCopy, revision)
			} else {
				single := [1]batch.Entry{{Type: batch.OpPut, Key: keyCopy, Value: valCopy, Revision: revision}}
				err = b.backend.SetOps(single[:])
			}
		} else if sv, ok := b.backend.(interface{ SetView(key, value []byte) error }); ok {
			err = sv.SetView(keyCopy, valCopy)
		} else {
			err = b.backend.Set(keyCopy, valCopy)
		}
		if err != nil {
			return err
		}
		b.appendBackendConditionalPoint(batch.OpPut, keyCopy)
		return nil
	}

	if b.streamEligible {
		if b.firstKey == nil {
			b.firstKey = keyCopy
			b.lastKey = keyCopy
		} else {
			if bytes.Compare(keyCopy, b.lastKey) <= 0 {
				b.streamEligible = false
			}
			b.lastKey = keyCopy
		}
	}
	// We don't know about value-log thresholds here, so we just store inline.
	// The backend will handle promotion to the value log if needed during
	// writeBypass, or standard write will handle it via the journal/memtable.
	b.entries = append(b.entries, batch.Entry{
		Type:     batch.OpPut,
		Key:      keyCopy,
		Value:    valCopy,
		Revision: revision,
	})
	b.noteEntryAppend()
	b.size += len(keyCopy) + len(valCopy)

	b.maybeSwitchToStreaming()
	return nil
}

// SetView records a Put without copying key/value bytes. Callers must treat
// key/value as immutable until the batch is written or closed.
func (b *Batch) SetView(key, value []byte) error {
	return b.SetViewWithRevision(key, value, page.LegacyEntryRevision)
}

func (b *Batch) SetViewWithRevision(key, value []byte, revision page.EntryRevision) error {
	if b.closed {
		return ErrBatchClosed
	}
	key = normalizeRawKVPointKey(key)
	value = normalizeRawKVValue(value)
	return b.SetViewValidatedWithRevision(key, value, revision)
}

// SetViewValidated is SetView for callers that already performed public input
// validation. The caller must still keep key/value immutable until Write/Close.
func (b *Batch) SetViewValidated(key, value []byte) error {
	return b.SetViewValidatedWithRevision(key, value, page.LegacyEntryRevision)
}

func (b *Batch) SetViewValidatedWithRevision(key, value []byte, revision page.EntryRevision) error {
	if hotPathStatsEnabled {
		batchSetViewCallsTotal.Add(1)
		batchSetViewBytesTotal.Add(uint64(len(key) + len(value)))
	}

	if b.backend != nil {
		b.batchRange.add(key)
		b.size += len(key) + len(value)
		revision = b.revisionForBackendPoint(revision)
		var err error
		if revision != page.LegacyEntryRevision {
			if sv, ok := b.backend.(interface {
				SetViewWithRevision(key, value []byte, revision page.EntryRevision) error
			}); ok {
				err = sv.SetViewWithRevision(key, value, revision)
			} else if s, ok := b.backend.(interface {
				SetWithRevision(key, value []byte, revision page.EntryRevision) error
			}); ok {
				err = s.SetWithRevision(key, value, revision)
			} else {
				single := [1]batch.Entry{{Type: batch.OpPut, Key: key, Value: value, Revision: revision}}
				err = b.backend.SetOps(single[:])
			}
		} else if sv, ok := b.backend.(interface{ SetView(key, value []byte) error }); ok {
			err = sv.SetView(key, value)
		} else {
			err = b.backend.Set(key, value)
		}
		if err != nil {
			return err
		}
		b.appendBackendConditionalPoint(batch.OpPut, key)
		return nil
	}

	if b.streamEligible {
		if b.firstKey == nil {
			b.firstKey = key
			b.lastKey = key
		} else {
			if bytes.Compare(key, b.lastKey) <= 0 {
				b.streamEligible = false
			}
			b.lastKey = key
		}
	}
	b.entries = append(b.entries, batch.Entry{
		Type:     batch.OpPut,
		Key:      key,
		Value:    value,
		Revision: revision,
	})
	b.hasViewOps = true
	b.noteEntryAppend()
	b.size += len(key) + len(value)

	b.maybeSwitchToStreaming()
	return nil
}

func (b *Batch) Delete(key []byte) error {
	return b.DeleteWithRevision(key, page.LegacyEntryRevision)
}

func (b *Batch) DeleteWithRevision(key []byte, revision page.EntryRevision) error {
	if b.closed {
		return ErrBatchClosed
	}
	key = normalizeRawKVPointKey(key)

	keyCopy := b.cloneKey(key)
	if b.backend != nil {
		b.batchRange.add(keyCopy)
		b.size += len(keyCopy)
		revision = b.revisionForBackendPoint(revision)
		var err error
		if revision != page.LegacyEntryRevision {
			if dv, ok := b.backend.(interface {
				DeleteViewWithRevision(key []byte, revision page.EntryRevision) error
			}); ok {
				err = dv.DeleteViewWithRevision(keyCopy, revision)
			} else if d, ok := b.backend.(interface {
				DeleteWithRevision(key []byte, revision page.EntryRevision) error
			}); ok {
				err = d.DeleteWithRevision(keyCopy, revision)
			} else {
				single := [1]batch.Entry{{Type: batch.OpDelete, Key: keyCopy, Revision: revision}}
				err = b.backend.SetOps(single[:])
			}
		} else if dv, ok := b.backend.(interface{ DeleteView(key []byte) error }); ok {
			err = dv.DeleteView(keyCopy)
		} else {
			err = b.backend.Delete(keyCopy)
		}
		if err != nil {
			return err
		}
		b.appendBackendConditionalPoint(batch.OpDelete, keyCopy)
		return nil
	}

	if b.streamEligible {
		if b.firstKey == nil {
			b.firstKey = keyCopy
			b.lastKey = keyCopy
		} else {
			if bytes.Compare(keyCopy, b.lastKey) <= 0 {
				b.streamEligible = false
			}
			b.lastKey = keyCopy
		}
	}
	b.entries = append(b.entries, batch.Entry{
		Type:     batch.OpDelete,
		Key:      keyCopy,
		Revision: revision,
	})
	b.noteEntryAppend()
	b.size += len(keyCopy)

	b.maybeSwitchToStreaming()
	return nil
}

func (b *Batch) DeleteRange(start, end []byte) error {
	if b.closed {
		return ErrBatchClosed
	}
	if batch.IsDeleteRangeNoop(start, end) {
		return nil
	}
	if b.db != nil {
		b.db.deleteRangeBatchCalls.Add(1)
	}
	var startCopy, endCopy []byte
	if start != nil {
		startCopy = b.cloneKey(start)
	}
	if end != nil {
		endCopy = b.cloneKey(end)
	}
	if b.backend != nil {
		single := [1]batch.Entry{{Type: batch.OpDeleteRange, Key: startCopy, Value: endCopy}}
		if err := b.backend.SetOps(single[:]); err != nil {
			return err
		}
		b.appendBackendConditionalEntries(single[:])
		if b.db != nil {
			b.db.recordDeleteRangePlan(1, 1)
		}
		b.size += len(startCopy) + len(endCopy)
		return nil
	}
	b.entries = append(b.entries, batch.Entry{Type: batch.OpDeleteRange, Key: startCopy, Value: endCopy})
	b.noteEntryAppend()
	b.size += len(startCopy) + len(endCopy)
	b.hasDeleteRanges = true
	b.streamEligible = false
	return nil
}

// DeleteView records a Delete without copying key bytes. Callers must treat
// key as immutable until the batch is written or closed.
func (b *Batch) DeleteView(key []byte) error {
	return b.DeleteViewWithRevision(key, page.LegacyEntryRevision)
}

func (b *Batch) DeleteViewWithRevision(key []byte, revision page.EntryRevision) error {
	if b.closed {
		return ErrBatchClosed
	}
	key = normalizeRawKVPointKey(key)
	return b.DeleteViewValidatedWithRevision(key, revision)
}

// DeleteViewValidated is DeleteView for callers that already performed public
// input validation. The caller must keep key immutable until Write/Close.
func (b *Batch) DeleteViewValidated(key []byte) error {
	return b.DeleteViewValidatedWithRevision(key, page.LegacyEntryRevision)
}

func (b *Batch) DeleteViewValidatedWithRevision(key []byte, revision page.EntryRevision) error {
	if hotPathStatsEnabled {
		batchDeleteViewCallsTotal.Add(1)
		batchDeleteViewBytesTotal.Add(uint64(len(key)))
	}

	if b.backend != nil {
		b.batchRange.add(key)
		b.size += len(key)
		revision = b.revisionForBackendPoint(revision)
		var err error
		if revision != page.LegacyEntryRevision {
			if dv, ok := b.backend.(interface {
				DeleteViewWithRevision(key []byte, revision page.EntryRevision) error
			}); ok {
				err = dv.DeleteViewWithRevision(key, revision)
			} else if d, ok := b.backend.(interface {
				DeleteWithRevision(key []byte, revision page.EntryRevision) error
			}); ok {
				err = d.DeleteWithRevision(key, revision)
			} else {
				single := [1]batch.Entry{{Type: batch.OpDelete, Key: key, Revision: revision}}
				err = b.backend.SetOps(single[:])
			}
		} else if dv, ok := b.backend.(interface{ DeleteView(key []byte) error }); ok {
			err = dv.DeleteView(key)
		} else {
			err = b.backend.Delete(key)
		}
		if err != nil {
			return err
		}
		b.appendBackendConditionalPoint(batch.OpDelete, key)
		return nil
	}

	if b.streamEligible {
		if b.firstKey == nil {
			b.firstKey = key
			b.lastKey = key
		} else {
			if bytes.Compare(key, b.lastKey) <= 0 {
				b.streamEligible = false
			}
			b.lastKey = key
		}
	}
	b.entries = append(b.entries, batch.Entry{
		Type:     batch.OpDelete,
		Key:      key,
		Revision: revision,
	})
	b.hasViewOps = true
	b.noteEntryAppend()
	b.size += len(key)

	b.maybeSwitchToStreaming()
	return nil
}

func (b *Batch) SetOps(ops []batch.Entry) error {
	if b.closed {
		return ErrBatchClosed
	}
	if b.backend != nil {
		copied := make([]batch.Entry, 0, len(ops))
		for _, op := range ops {
			copiedOp := op
			if op.Type == batch.OpDeleteRange {
				if batch.IsDeleteRangeNoop(op.Key, op.Value) {
					continue
				}
				if op.Key != nil {
					copiedOp.Key = b.cloneKey(op.Key)
				}
				if op.Value != nil {
					copiedOp.Value = b.cloneKey(op.Value)
				}
				copied = append(copied, copiedOp)
				b.size += len(copiedOp.Key) + len(copiedOp.Value)
				continue
			}
			copiedOp.Key = b.cloneKey(normalizeRawKVPointKey(op.Key))
			if op.Type == batch.OpPut && !op.IsPtr {
				copiedOp.Value = b.cloneValue(normalizeRawKVValue(op.Value))
			} else if op.Value != nil {
				copiedOp.Value = b.cloneValue(op.Value)
			}
			copied = append(copied, copiedOp)
			b.size += len(copiedOp.Key) + len(copiedOp.Value)
			b.batchRange.add(copiedOp.Key)
		}
		b.assignLegacyPointRevisions(copied)
		if err := b.backend.SetOps(copied); err != nil {
			return err
		}
		b.appendBackendConditionalEntries(copied)
		return nil
	}
	for _, op := range ops {
		copied := op
		if op.Type == batch.OpDeleteRange {
			if batch.IsDeleteRangeNoop(op.Key, op.Value) {
				continue
			}
			if op.Key != nil {
				copied.Key = b.cloneKey(op.Key)
			}
			if op.Value != nil {
				copied.Value = b.cloneKey(op.Value)
			}
			b.entries = append(b.entries, copied)
			b.noteEntryAppend()
			b.size += len(copied.Key) + len(copied.Value)
			b.hasDeleteRanges = true
			b.streamEligible = false
			continue
		}
		normalizedKey := normalizeRawKVPointKey(op.Key)
		if op.Type == batch.OpPut && !op.IsPtr {
			copied.Key, copied.Value = b.cloneKeyValue(normalizedKey, normalizeRawKVValue(op.Value))
		} else if op.Value != nil {
			copied.Key, copied.Value = b.cloneKeyValue(normalizedKey, op.Value)
		} else {
			copied.Key = b.cloneKey(normalizedKey)
			copied.Value = nil
		}
		if b.streamEligible {
			if b.firstKey == nil {
				b.firstKey = copied.Key
				b.lastKey = copied.Key
			} else {
				if bytes.Compare(copied.Key, b.lastKey) <= 0 {
					b.streamEligible = false
				}
				b.lastKey = copied.Key
			}
		}
		b.entries = append(b.entries, copied)
		b.noteEntryAppend()
		b.size += len(copied.Key) + len(copied.Value)
	}
	return nil
}

const (
	batchDefaultEntriesCap = 16
	// Keep the adaptive NewBatch reserve bounded so one huge batch cannot
	// permanently over-provision typical batch allocations.
	batchHintEntriesMax    = 8192
	streamSwitchMinEntries = 4096
	streamSwitchMinBytes   = 1 << 20 // 1MiB
	// Only fan out value-log appends across multiple lanes when a batch is large
	// enough to amortize per-lane setup and goroutine overhead.
	multiLaneValueLogMinRecords = 1024
	batchCopyArenaMinChunk      = 4 << 10
	batchCopyArenaUnsizedInit   = 8 << 10
	batchCopyArenaBytesPerEntry = 192
	batchCopyArenaInitMax       = 2 << 20
	// Keep retained batch-copy chunks bounded to 1MiB. Larger chunks are often
	// underfilled in restore-heavy traffic and can disproportionately inflate
	// peak RSS when multiple memtable views pin retired arenas.
	batchCopyArenaMaxRetain = 1 << 20

	defaultCachedBatchDeleteRangeMaterializeMaxEntries  = 1 << 20
	defaultCachedBatchDeleteRangeMaterializeMaxKeyBytes = 64 << 20
	batchArenaTailCompactMinCap                         = 256 << 10
	// Only compact tails with meaningful waste so we avoid churn on tiny chunks.
	batchArenaTailCompactMinWaste = 256 << 10
	// Under deferred-view pressure, compact earlier so retired memtable leases
	// don't pin large half-used tail chunks for iterator lifetimes.
	batchArenaTailCompactPinnedMinWaste = 128 << 10
	// Require at least 50% slack in the tail chunk before compacting borrowed
	// slices. This keeps the path focused on pathological underfill.
	batchArenaTailCompactMaxFillNumerator   = 1
	batchArenaTailCompactMaxFillDenominator = 2
	// Under deferred-view pressure, compact tails once fill is at most 75%.
	batchArenaTailCompactPinnedMaxFillNumerator   = 3
	batchArenaTailCompactPinnedMaxFillDenominator = 4
	batchEntriesPoolMaxRetain                     = 16 << 10
	batchIntSlicePoolMaxRetain                    = 16 << 10
	batchAuxEntryLeaseMaxCount                    = 256
	batchAuxEntryLeaseMaxBytes                    = 8 << 20
	batchAuxIntLeaseMaxCount                      = 256
	batchAuxIntLeaseMaxBytes                      = 1 << 20
	batchAuxChunkLeaseMaxCount                    = 256
	batchAuxChunkLeaseMaxBytes                    = 1 << 20
	batchAuxEntryGroupLeaseMaxCount               = 256
	batchAuxEntryGroupLeaseMaxBytes               = 1 << 20
	batchSelectedSortedShardMaxEntries            = 128
	batchArenaChunkListInitialCap                 = 4
	batchArenaChunkListMaxRetain                  = 256
	batchShardEntryGroupsMaxRetain                = 1024
	batchMemtableRetainStackCap                   = 64
	// When deferred iterator views pin retired memtables, reduce retained
	// batch-arena headroom to limit extra lease growth under that pressure.
	batchArenaDeferredPressureThresholdBytes = int64(512 << 20)
	batchArenaDeferredPressureHardCapDivisor = int64(2)
)

var (
	cachedBatchDeleteRangeMaterializeMaxEntries  = defaultCachedBatchDeleteRangeMaterializeMaxEntries
	cachedBatchDeleteRangeMaterializeMaxKeyBytes = defaultCachedBatchDeleteRangeMaterializeMaxKeyBytes
)

func batchCopyArenaInitCapForEntries(entries int) int {
	if entries <= 0 {
		return batchCopyArenaUnsizedInit
	}
	if entries > batchCopyArenaInitMax/batchCopyArenaBytesPerEntry {
		return batchCopyArenaInitMax
	}
	capHint := entries * batchCopyArenaBytesPerEntry
	if capHint < batchCopyArenaMinChunk {
		return batchCopyArenaMinChunk
	}
	if capHint > batchCopyArenaInitMax {
		return batchCopyArenaInitMax
	}
	return capHint
}

func (b *Batch) maybeSwitchToStreaming() {
	if b.streamBypassOff || b.streamTried || !b.streamEligible || b.backend != nil {
		return
	}
	// Streaming writes directly to the backend batch and therefore bypasses the
	// journal/value-log orchestration. Only enable it when the journal is
	// disabled and value-log pointers are disabled.
	if !b.db.disableJournal || b.db.valueLogEnabled() {
		return
	}
	// Switch to streaming (direct-to-backend batch) once a batch is "big enough"
	// that keeping all entries in memory provides little benefit.
	//
	// Why this exists:
	// - The cached/memtable path is great for small/random batches because it
	//   aggregates updates and reduces backend write amplification.
	// - For large strictly-increasing batches that start beyond the max key in
	//   the in-memory layers, we don't benefit from memtable aggregation; we just
	//   pay extra overhead storing the batch entries slice until Write().
	//
	// We intentionally use a small threshold (rather than flushThreshold) so
	// "BatchWrite1M" style workloads can switch early and avoid materializing the
	// entire batch in memory before Write().
	// Require both entry-count and byte-size thresholds to avoid switching tiny-value
	// batches to backend streaming solely due to key count.
	if len(b.entries) < streamSwitchMinEntries || b.size < streamSwitchMinBytes {
		return
	}

	// Only attempt streaming if the batch is strictly increasing and starts beyond
	// the maximum key present in the in-memory layers. Active range spans are
	// barriers for later point writes, so direct-to-backend streaming must stay off
	// while any span-only queued unit is visible.
	b.db.mu.RLock()
	if rangeSpanLayerHasSpans(b.db.queueRangeSpans) {
		b.db.mu.RUnlock()
		return
	}
	queueRanges := append([]keyRange(nil), b.db.queueRanges...)
	b.db.mu.RUnlock()

	var maxKey []byte
	mutableRange := b.db.snapshotMutableRange()
	if mutableRange.valid {
		maxKey = mutableRange.max
	}
	for _, r := range queueRanges {
		if !r.valid {
			continue
		}
		if maxKey == nil || bytes.Compare(r.max, maxKey) > 0 {
			maxKey = r.max
		}
	}

	b.streamTried = true
	if maxKey != nil && bytes.Compare(b.firstKey, maxKey) <= 0 {
		return
	}

	backendBatch := b.db.backend.NewBatch()
	if b.firstKey != nil && b.lastKey != nil {
		// Streaming is strictly increasing and starts beyond the max key in memory,
		// so the batch range is simply [first,last]. Keep copies for backend range
		// tracking after commit.
		b.batchRange.valid = true
		b.batchRange.min = cloneKeyRangePointKey(b.firstKey)
		b.batchRange.max = cloneKeyRangePointKey(b.lastKey)
	}
	b.assignLegacyPointRevisions(b.entries)
	if err := backendBatch.SetOps(b.entries); err != nil {
		_ = backendBatch.Close()
		return
	}
	b.appendBackendConditionalEntries(b.entries)
	b.backend = backendBatch
	b.entries = b.entries[:0]
}

func (b *Batch) Write() error {
	return b.write(false)
}

func (b *Batch) WriteSync() error {
	return b.write(true)
}

// CommandWALBatchWriteTiming is a request-scoped partition of the cached work
// around a command-WAL public batch callback. The callback itself is reported
// separately so its command-journal subphases can be partitioned by the caller.
type CommandWALBatchWriteTiming struct {
	CheckpointGate           time.Duration
	PreflightMaterialization time.Duration
	CommandCallback          time.Duration
	MemtablePublicationReset time.Duration
}

// WriteAfterCommandWALAppend writes a cached batch by running appendCommand
// after cached write preflight succeeds and before the mutation becomes
// visible in the mutable table. This is intentionally limited to command-WAL
// public mode, where the cached redo log is disabled.
func (b *Batch) WriteAfterCommandWALAppend(sync bool, appendCommand func() error) error {
	if b == nil || b.db == nil {
		return backenddb.ErrClosed
	}
	if b.closed {
		return ErrBatchClosed
	}
	if appendCommand == nil {
		return fmt.Errorf("cachingdb: missing command wal append callback")
	}
	if !b.db.externalCommandWAL {
		return fmt.Errorf("cachingdb: command wal batch writes require external command wal cached mode")
	}
	b.db.waitForCheckpointForWrite()
	if b.backend != nil {
		return fmt.Errorf("cachingdb: command wal batch writes require cached memtable path")
	}

	prevAppend := b.commandWALAppend
	b.commandWALAppend = appendCommand
	defer func() {
		b.commandWALAppend = prevAppend
	}()
	if b.hasDeleteRanges {
		return b.writeRangeBatch(sync)
	}
	return b.writeRegular(sync)
}

// WriteAfterCommandWALAppendWithPreparedRevision is the ordered-revision
// variant used by the public command-WAL adapter. Legacy point revisions remain
// unassigned through preflight; appendCommand must arrange their assignment
// while holding the command-WAL append serialization boundary.
func (b *Batch) WriteAfterCommandWALAppendWithPreparedRevision(sync bool, appendCommand func() error) error {
	if b == nil || b.db == nil {
		return backenddb.ErrClosed
	}
	if b.closed {
		return ErrBatchClosed
	}
	if appendCommand == nil {
		return fmt.Errorf("cachingdb: missing command wal append callback")
	}
	if !b.db.externalCommandWAL {
		return fmt.Errorf("cachingdb: command wal batch writes require external command wal cached mode")
	}
	b.db.waitForCheckpointForWrite()
	if b.backend != nil {
		return fmt.Errorf("cachingdb: command wal batch writes require cached memtable path")
	}

	prevAppend := b.commandWALAppend
	prevPreparedRevision := b.commandWALPreparedRevision
	b.commandWALPreparedRevision = true
	b.commandWALAppend = appendCommand
	defer func() {
		b.commandWALAppend = prevAppend
		b.commandWALPreparedRevision = prevPreparedRevision
	}()
	if b.hasDeleteRanges {
		return b.writeRangeBatch(sync)
	}
	return b.writeRegular(sync)
}

// WriteAfterCommandWALAppendMeasured is the opt-in diagnostic counterpart to
// WriteAfterCommandWALAppend. It preserves the same write ordering while
// measuring non-overlapping request phases. Normal writes use the unmeasured
// method above and do not pay these clock reads.
func (b *Batch) WriteAfterCommandWALAppendMeasured(sync bool, appendCommand func() error) (timing CommandWALBatchWriteTiming, err error) {
	if b == nil || b.db == nil {
		return timing, backenddb.ErrClosed
	}
	if b.closed {
		return timing, ErrBatchClosed
	}
	if appendCommand == nil {
		return timing, fmt.Errorf("cachingdb: missing command wal append callback")
	}
	if !b.db.externalCommandWAL {
		return timing, fmt.Errorf("cachingdb: command wal batch writes require external command wal cached mode")
	}

	checkpointStart := time.Now()
	b.db.waitForCheckpointForWrite()
	phaseStart := time.Now()
	timing.CheckpointGate = phaseStart.Sub(checkpointStart)
	if b.backend != nil {
		return timing, fmt.Errorf("cachingdb: command wal batch writes require cached memtable path")
	}

	callbackInvoked := false
	postCallbackStart := time.Time{}
	measuredAppend := func() error {
		callbackStart := time.Now()
		timing.PreflightMaterialization = callbackStart.Sub(phaseStart)
		callbackInvoked = true
		appendErr := appendCommand()
		postCallbackStart = time.Now()
		timing.CommandCallback = postCallbackStart.Sub(callbackStart)
		return appendErr
	}
	prevAppend := b.commandWALAppend
	b.commandWALAppend = measuredAppend
	defer func() {
		b.commandWALAppend = prevAppend
	}()
	if b.hasDeleteRanges {
		err = b.writeRangeBatch(sync)
	} else {
		err = b.writeRegular(sync)
	}
	writeEnd := time.Now()
	if callbackInvoked {
		timing.MemtablePublicationReset = writeEnd.Sub(postCallbackStart)
	} else {
		timing.PreflightMaterialization = writeEnd.Sub(phaseStart)
	}
	return timing, err
}

// WriteAfterCommandWALAppendWithPreparedRevisionMeasured preserves the prepared
// revision ordering while exposing the same phase diagnostics as the ordinary
// measured command-WAL batch path.
func (b *Batch) WriteAfterCommandWALAppendWithPreparedRevisionMeasured(sync bool, appendCommand func() error) (timing CommandWALBatchWriteTiming, err error) {
	if b == nil || b.db == nil {
		return timing, backenddb.ErrClosed
	}
	if b.closed {
		return timing, ErrBatchClosed
	}
	if appendCommand == nil {
		return timing, fmt.Errorf("cachingdb: missing command wal append callback")
	}
	if !b.db.externalCommandWAL {
		return timing, fmt.Errorf("cachingdb: command wal batch writes require external command wal cached mode")
	}

	checkpointStart := time.Now()
	b.db.waitForCheckpointForWrite()
	phaseStart := time.Now()
	timing.CheckpointGate = phaseStart.Sub(checkpointStart)
	if b.backend != nil {
		return timing, fmt.Errorf("cachingdb: command wal batch writes require cached memtable path")
	}

	callbackInvoked := false
	postCallbackStart := time.Time{}
	measuredAppend := func() error {
		callbackStart := time.Now()
		timing.PreflightMaterialization = callbackStart.Sub(phaseStart)
		callbackInvoked = true
		appendErr := appendCommand()
		postCallbackStart = time.Now()
		timing.CommandCallback = postCallbackStart.Sub(callbackStart)
		return appendErr
	}
	prevAppend := b.commandWALAppend
	prevPreparedRevision := b.commandWALPreparedRevision
	b.commandWALPreparedRevision = true
	b.commandWALAppend = measuredAppend
	defer func() {
		b.commandWALAppend = prevAppend
		b.commandWALPreparedRevision = prevPreparedRevision
	}()
	if b.hasDeleteRanges {
		err = b.writeRangeBatch(sync)
	} else {
		err = b.writeRegular(sync)
	}
	writeEnd := time.Now()
	if callbackInvoked {
		timing.MemtablePublicationReset = writeEnd.Sub(postCallbackStart)
	} else {
		timing.PreflightMaterialization = writeEnd.Sub(phaseStart)
	}
	return timing, err
}

func (b *Batch) write(sync bool) error {
	if b.closed {
		return ErrBatchClosed
	}
	b.db.waitForCheckpointForWrite()

	if b.hasDeleteRanges {
		return b.writeRangeBatch(sync)
	}

	if b.backend != nil {
		err := b.writeBackendBatchSerialized(b.backend, sync, func() {
			b.db.conditionalRecordCommittedEntries(b.backendConditionalEntries, nil, 0)
		}, func() {
			if b.batchRange.valid {
				b.db.mu.Lock()
				b.db.backendRange.add(b.batchRange.min)
				b.db.backendRange.add(b.batchRange.max)
				b.db.mu.Unlock()
			}
		})
		if cerr := b.backend.Close(); cerr != nil && err == nil {
			err = cerr
		}
		b.backend = nil
		if err == nil && b.size > 0 {
			b.db.noteWrite()
		}
		b.updateBatchEntryHint()
		b.updateBatchCopyHint()
		b.Reset()
		return err
	}

	if ok, err := b.tryWriteWALOffStreamBypass(sync); err != nil {
		return err
	} else if ok {
		return nil
	}

	// WAL-off sync writes are common on versioned append-heavy workloads such as
	// IAVL commit. Use the direct backend bypass path for those publish
	// boundaries so we avoid rotating/flushing unrelated mutable state.
	if sync && b.db.disableJournal {
		return b.writeBypass(sync)
	}

	// Optimization: Bypass for Large Batches
	// Generalization: Only bypass if the batch is large enough to be comparable
	// to a memtable flush. Small/Medium random batches cause high write amplification
	// if written directly to the COW backend.
	if b.size >= int(b.db.flushThreshold) {
		return b.writeBypass(sync)
	}
	return b.writeRegular(sync)
}

func (b *Batch) writeBackendBatchSerialized(backendBatch batch.Interface, sync bool, recordBeforePublish, recordCommitted func()) error {
	if b == nil || b.db == nil || backendBatch == nil {
		return backenddb.ErrClosed
	}
	b.db.flushMu.Lock()
	if err := b.db.beginDirectWriteWithFlushMuHeld(); err != nil {
		b.db.flushMu.Unlock()
		return err
	}
	defer b.db.flushMu.Unlock()
	defer b.db.writeMu.RUnlock()

	if recordBeforePublish != nil {
		recordBeforePublish()
	}
	var err error
	if sync && !b.db.relaxedSync {
		err = backendBatch.WriteSync()
	} else {
		err = backendBatch.Write()
	}
	if err == nil && recordCommitted != nil {
		recordCommitted()
	}
	return err
}

func (b *Batch) writeRangeBatch(sync bool) error {
	if b == nil || b.db == nil {
		return backenddb.ErrClosed
	}
	if !b.hasDeleteRanges {
		return b.write(sync)
	}
	inputRanges := 0
	for _, entry := range b.entries {
		if entry.Type == batch.OpDeleteRange && !batch.IsDeleteRangeNoop(entry.Key, entry.Value) {
			inputRanges++
		}
	}
	points, ranges := batch.BuildApplyPlanFromEntries(b.entries, true)
	b.db.deleteRangeBatchWrites.Add(1)
	b.db.recordDeleteRangePlan(inputRanges, len(ranges))
	if len(points) == 0 && len(ranges) == 0 {
		b.updateBatchEntryHint()
		b.updateBatchCopyHint()
		b.Reset()
		return nil
	}
	if b.commandWALAppend != nil && b.db.externalCommandWAL && len(points) == 0 && len(ranges) > 0 {
		return b.writeRangeSpanBatch(sync, ranges)
	}

	// Hold the writer gate across snapshot enumeration and publish. Without this,
	// a concurrent cached write can slip between the scan and the materialized
	// point-delete batch, producing a non-serializable mix of range-deleted old
	// keys and surviving newly inserted keys.
	if err := b.db.beginExclusiveWrite(); err != nil {
		return err
	}
	writeMuHeld := true
	unlockWriteMu := func() {
		if writeMuHeld {
			writeMuHeld = false
			b.db.writeMu.Unlock()
		}
	}
	defer unlockWriteMu()

	materialized := make([]batch.Entry, 0, len(points))
	deleteKeyBytes := 0
	var visitedKeys, materializedKeys, materializedKeyBytes uint64
	if len(ranges) > 0 {
		b.db.deleteRangeIterators.Add(uint64(len(ranges)))
	}
	for _, r := range ranges {
		it, err := b.db.Iterator(r.Start, r.End)
		if err != nil {
			return err
		}
		for it.Valid() {
			key := it.Key()
			visitedKeys++
			if cachedBatchDeleteRangeMaterializeMaxEntries >= 0 && len(materialized) >= cachedBatchDeleteRangeMaterializeMaxEntries {
				_ = it.Close()
				return fmt.Errorf("%w: keys=%d limit=%d", ErrBatchDeleteRangeTooLarge, len(materialized)+1, cachedBatchDeleteRangeMaterializeMaxEntries)
			}
			deleteKeyBytes += len(key)
			if cachedBatchDeleteRangeMaterializeMaxKeyBytes >= 0 && deleteKeyBytes > cachedBatchDeleteRangeMaterializeMaxKeyBytes {
				_ = it.Close()
				return fmt.Errorf("%w: key_bytes=%d limit=%d", ErrBatchDeleteRangeTooLarge, deleteKeyBytes, cachedBatchDeleteRangeMaterializeMaxKeyBytes)
			}
			materialized = append(materialized, batch.Entry{Type: batch.OpDelete, Key: append([]byte(nil), key...)})
			materializedKeys++
			materializedKeyBytes += uint64(len(key))
			it.Next()
		}
		if err := it.Error(); err != nil {
			_ = it.Close()
			return err
		}
		if err := it.Close(); err != nil {
			return err
		}
	}
	b.db.recordDeleteRangeKeys(visitedKeys, materializedKeys, materializedKeys, materializedKeyBytes)
	materialized = append(materialized, points...)

	origEntries := b.entries
	origHasRanges := b.hasDeleteRanges
	origStreamEligible := b.streamEligible
	origHasViewOps := b.hasViewOps
	origCommandWALCompactReplay := b.commandWALCompactReplay
	origCommandWALCompactRanges := b.commandWALCompactRanges
	origCommandWALCompactPointStart := b.commandWALCompactPointStart
	b.entries = materialized
	b.hasDeleteRanges = false
	b.streamEligible = false
	b.commandWALCompactReplay = len(ranges) > 0
	b.commandWALCompactRanges = ranges
	b.commandWALCompactPointStart = len(materialized) - len(points)
	// Materialization reallocates and reorders entries, so any ptrValueIdxs still
	// refer to the original entry indexes. Force the safe copy path for this write
	// instead of retaining batch arenas by stale indexes.
	b.hasViewOps = true
	err := b.writeRegularLocked(sync, unlockWriteMu)
	if err != nil {
		b.entries = origEntries
		b.hasDeleteRanges = origHasRanges
		b.streamEligible = origStreamEligible
		b.hasViewOps = origHasViewOps
		b.commandWALCompactReplay = origCommandWALCompactReplay
		b.commandWALCompactRanges = origCommandWALCompactRanges
		b.commandWALCompactPointStart = origCommandWALCompactPointStart
	}
	return err
}

func (b *Batch) writeRangeSpanBatch(sync bool, ranges []batch.DeleteRange) (err error) {
	_ = sync
	if b == nil || b.db == nil {
		return backenddb.ErrClosed
	}
	if len(ranges) == 0 {
		b.updateBatchEntryHint()
		b.updateBatchCopyHint()
		b.Reset()
		return nil
	}
	commandWALAppended := false
	defer func() {
		if err != nil && commandWALAppended {
			b.db.reportError(fmt.Errorf("cachingdb: post-command-wal range batch failed: %w", err))
		}
	}()

	b.db.waitForRangeSpanCheckpointDrain()
	b.db.flushMu.Lock()
	defer b.db.flushMu.Unlock()
	if err := b.db.beginExclusiveWriteWithFlushMuHeld(); err != nil {
		return err
	}
	defer b.db.writeMu.Unlock()

	b.db.mu.Lock()
	rotate := b.db.mutableBytes.Load() > 0
	if !rotate {
		for i := range b.db.mutableShards {
			mt := b.db.mutableShards[i].mem
			if mt != nil && mt.Len() != 0 {
				rotate = true
				break
			}
		}
	}
	if rotate {
		if err := b.db.rotateMutableShardsLocked(minMemtablePrealloc, false); err != nil {
			b.db.mu.Unlock()
			return err
		}
	}
	if b.commandWALAppend != nil {
		if err := b.commandWALAppend(); err != nil {
			b.db.mu.Unlock()
			return err
		}
		commandWALAppended = true
	}
	if err := b.db.enqueueRangeSpanLayerLocked(ranges); err != nil {
		b.db.mu.Unlock()
		return err
	}
	b.db.conditionalRecordCommittedEntries(nil, ranges, 0)
	b.db.publishMemtablesLocked()
	b.db.mu.Unlock()

	b.db.noteWrite()
	b.db.maybeAssistFlush()
	b.updateBatchEntryHint()
	b.updateBatchCopyHint()
	b.Reset()
	return nil
}

func (b *Batch) tryWriteWALOffStreamBypass(sync bool) (bool, error) {
	if b == nil || b.db == nil {
		return false, nil
	}
	if !b.db.deferredValueLogEnabled() {
		return false, nil
	}
	if b.backend != nil || b.streamBypassOff || !b.streamEligible {
		return false, nil
	}
	if b.firstKey == nil || b.lastKey == nil {
		return false, nil
	}
	// Mirror maybeSwitchToStreaming: bypass only when both dimensions are large.
	if len(b.entries) < streamSwitchMinEntries || b.size < streamSwitchMinBytes {
		return false, nil
	}

	// Only attempt streaming if the batch is strictly increasing and starts beyond
	// the maximum key present in the in-memory layers. Active range spans are
	// barriers for later point writes, so direct-to-backend streaming must stay off
	// while any span-only queued unit is visible.
	b.db.mu.RLock()
	hasRangeSpans := rangeSpanLayerHasSpans(b.db.queueRangeSpans)
	queueRanges := append([]keyRange(nil), b.db.queueRanges...)
	queueLen := len(b.db.queue)
	b.db.mu.RUnlock()
	if hasRangeSpans {
		return false, nil
	}
	if queueLen > 0 && len(queueRanges) == 0 {
		// Cannot reason about overlap without queue range tracking.
		return false, nil
	}

	var maxKey []byte
	mutableRange := b.db.snapshotMutableRange()
	if mutableRange.valid {
		maxKey = mutableRange.max
	}
	for _, r := range queueRanges {
		if !r.valid {
			continue
		}
		if maxKey == nil || bytes.Compare(r.max, maxKey) > 0 {
			maxKey = r.max
		}
	}
	if maxKey != nil && bytes.Compare(b.firstKey, maxKey) <= 0 {
		return false, nil
	}

	// WAL-off streaming bypass: append large values to the value log and commit
	// backend pointers directly, avoiding memtable ingestion costs for append-only
	// workloads.
	ops := getEntrySlice(len(b.entries))
	ops = append(ops, b.entries...)
	defer putEntrySlice(ops)

	b.assignLegacyPointRevisions(ops)
	ops, err := b.db.deferValueLogOps(ops, sync)
	if err != nil {
		return false, err
	}

	backendBatch := b.db.backend.NewBatch()
	if err := backendBatch.SetOps(ops); err != nil {
		_ = backendBatch.Close()
		return false, err
	}

	err = b.writeBackendBatchSerialized(backendBatch, sync, func() {
		b.db.conditionalRecordCommittedEntries(ops, nil, 0)
	}, nil)
	if cerr := backendBatch.Close(); cerr != nil && err == nil {
		err = cerr
	}
	if err != nil {
		return false, err
	}

	b.db.mu.Lock()
	b.db.backendRange.add(b.firstKey)
	b.db.backendRange.add(b.lastKey)
	b.db.mu.Unlock()

	if b.size > 0 {
		b.db.noteWrite()
	}
	b.updateBatchEntryHint()
	b.updateBatchCopyHint()
	b.Reset()
	return true, nil
}

func (b *Batch) writeRegular(syncWrite bool) error {
	if err := b.db.beginDirectWrite(); err != nil {
		return err
	}
	return b.writeRegularLocked(syncWrite, b.db.writeMu.RUnlock)
}

func (b *Batch) writeRegularLocked(syncWrite bool, unlockWriteMu func()) error {
	needRotate := false
	needSyncBarrier := false
	commandWALAppended := false
	b.commandWALMaterializedRID = false
	var retainStableViewValueMems []memtable.Table
	var stableViewValueLeaseBytes int64
	stableViewValueLeaseFinalized := false
	finalizeStableViewValueLease := func() {
		if stableViewValueLeaseFinalized || len(retainStableViewValueMems) == 0 {
			return
		}
		if stableViewValueLeaseBytes > 0 {
			b.db.retainExternalViewValueChunksForMemtables(b.stableViewValueLeaseChunks, retainStableViewValueMems)
		}
		b.stableViewValueLeaseConsumed = true
		b.stableViewValueLeaseChunks = nil
		stableViewValueLeaseFinalized = true
	}
	failMemtableApply := func(shard *memShard, err error) error {
		finalizeStableViewValueLease()
		shard.mu.Unlock()
		unlockWriteMu()
		if err == nil {
			return nil
		}
		if !b.db.disableJournal {
			b.db.reportError(fmt.Errorf("cachingdb: WAL apply failed: %w", err))
			b.db.walAckMu.Lock()
			if b.db.walErr == nil {
				b.db.walErr = err
			}
			b.db.walAckMu.Unlock()
		} else if commandWALAppended {
			b.db.reportError(fmt.Errorf("cachingdb: post-command-wal batch apply failed: %w", err))
		}
		return err
	}

	// 1. Memtable capacity pre-check
	shardCount := len(b.db.mutableShards)
	shardAdds := b.shardAdds
	if cap(shardAdds) < shardCount {
		if cap(shardAdds) > 0 {
			b.db.putBatchInt64Slice(shardAdds)
		}
		shardAdds = b.db.getBatchInt64Slice(shardCount)
		shardAdds = shardAdds[:shardCount]
	} else {
		shardAdds = shardAdds[:shardCount]
	}
	clear(shardAdds)
	b.shardAdds = shardAdds

	shardCounts := b.shardCnts
	if cap(shardCounts) < shardCount {
		if cap(shardCounts) > 0 {
			b.db.putBatchIntSlice(shardCounts)
		}
		shardCounts = b.db.getBatchIntSlice(shardCount)
		shardCounts = shardCounts[:shardCount]
	} else {
		shardCounts = shardCounts[:shardCount]
	}
	clear(shardCounts)
	b.shardCnts = shardCounts

	shardIdxs := b.shardIdxs
	if cap(shardIdxs) < len(b.entries) {
		if cap(shardIdxs) > 0 {
			b.db.putBatchIntSlice(shardIdxs)
		}
		shardIdxs = b.db.getBatchIntSlice(len(b.entries))
		shardIdxs = shardIdxs[:len(b.entries)]
	} else {
		shardIdxs = shardIdxs[:len(b.entries)]
	}
	b.shardIdxs = shardIdxs
	allDeletes := true
	zeroInlineWALBatch := !b.db.disableJournal
	zeroInlineValueLen := -1
	var zeroInlineValueRef []byte
	for i := range b.entries {
		op := &b.entries[i]
		if op.Type != batch.OpDelete {
			allDeletes = false
		}
		if zeroInlineWALBatch {
			if op.Type != batch.OpPut || op.IsPtr || len(op.Value) == 0 {
				zeroInlineWALBatch = false
			} else {
				if zeroInlineValueLen < 0 {
					zeroInlineValueLen = len(op.Value)
				} else if zeroInlineValueLen != len(op.Value) {
					zeroInlineWALBatch = false
				}
				if zeroInlineWALBatch {
					if sameNonEmptyBytesData(op.Value, zeroInlineValueRef) {
						// Same immutable value buffer as the first zero value in this batch.
					} else if allZeroBytes(op.Value) {
						zeroInlineValueRef = op.Value
					} else {
						zeroInlineWALBatch = false
					}
				}
			}
		}
		idx := b.db.shardIndex(op.Key)
		shardIdxs[i] = idx
		shardCounts[idx]++
		add := int64(len(op.Key))
		if op.Type == batch.OpPut {
			add += int64(len(op.Value))
		}
		shardAdds[idx] += add
	}
	var retainMainMemStack [batchMemtableRetainStackCap]memtable.Table
	retainMainMems := retainMainMemStack[:0]
	if shardCount > len(retainMainMemStack) {
		retainMainMems = make([]memtable.Table, 0, shardCount)
	}
	var retainStableViewValueMemStack [batchMemtableRetainStackCap]memtable.Table
	retainStableViewValueMems = retainStableViewValueMemStack[:0]
	if shardCount > len(retainStableViewValueMemStack) {
		retainStableViewValueMems = make([]memtable.Table, 0, shardCount)
	}
	for i, add := range shardAdds {
		if add == 0 {
			continue
		}
		shard := &b.db.mutableShards[i]
		shard.mu.Lock()
		over := b.db.shardExceedsLimit(shard, add)
		shard.mu.Unlock()
		if over {
			unlockWriteMu()
			return ErrMemtableFull
		}
	}
	stableViewValueLeaseBytes = batchArenaChunksCapBytes(b.stableViewValueLeaseChunks)
	prospectiveRetainBytes := batchArenaChunksCapBytes(b.copyArenaChunks) + batchArenaChunksCapBytes(b.ptrCopyArenaChunks) + stableViewValueLeaseBytes
	allowBatchArenaBorrow, preflightBlocked := shouldBorrowBatchArenaBytesForWriteWithHardCap(
		prospectiveRetainBytes,
		b.db.currentBatchArenaRetainedHardCapEffectiveBytes(),
	)
	allowStableViewValueBorrow := false
	// SetView/DeleteView callers provide externally-owned slices that are only
	// guaranteed immutable until Write/Close returns. Do not retain or steal
	// those slices into memtables unless the owner attaches an explicit stable
	// value lease that can outlive this batch.
	if b.hasViewOps {
		allowStableViewValueBorrow = len(b.stableViewValueLeaseChunks) > 0 && allowBatchArenaBorrow
		allowBatchArenaBorrow = false
		batchArenaBorrowViewOpsBlockedTotal.Add(1)
	}
	if !allowBatchArenaBorrow {
		batchArenaBorrowBlockedTotal.Add(1)
		if preflightBlocked {
			batchArenaBorrowPreflightBlockedTotal.Add(1)
			if prospectiveRetainBytes > 0 {
				batchArenaBorrowPreflightBlockedBytesTotal.Add(uint64(prospectiveRetainBytes))
			}
		}
	}

	// 2. Optional value-log + journal append loop.
	//
	// The value log (value store) and journal (redo log) are decoupled:
	// - When DisableWAL=true, we still append large values to the value log
	//   and store pointers in memory; there is simply no redo log for crash replay.
	// - When DisableWAL=false, we also append commit-intent records that can
	//   be replayed to recover unflushed writes.
	durability := journalDurabilityNone
	if syncWrite {
		if b.db.relaxedSync {
			durability = journalDurabilityFlush
		} else {
			durability = journalDurabilitySync
		}
	} else if b.db.disableJournal && b.db.relaxedSync && b.db.indexOuterLeavesInValueLog {
		// In WAL-off fast profiles, staged importer batches can publish pointer
		// metadata via later sync writes before a fresh logical reader reloads the
		// version. Keep unsynced batch commits cheap, but flush value-log writer
		// buffers so pointer-backed payload bytes are visible to subsequent readers.
		durability = journalDurabilityFlush
	}
	debugPtr := b.db.debugFlushPointers
	valueLogEnabled := b.db.valueLogEnabled()

	var (
		eligibleIdxs                  []int
		eligibleCountTotal            int
		allowPointers                 bool
		eligibleCount                 int
		multiLanePointers             bool
		materializeCommandWALPointers bool
	)
	if !allDeletes {
		eligibleIdxs = b.eligibleIdxs
		if cap(eligibleIdxs) < len(b.entries) {
			if cap(eligibleIdxs) > 0 {
				b.db.putBatchIntSlice(eligibleIdxs)
			}
			eligibleIdxs = b.db.getBatchIntSlice(len(b.entries))
		}
		eligibleIdxs = eligibleIdxs[:0]
		b.eligibleIdxs = eligibleIdxs
		if valueLogEnabled || debugPtr {
			for i := range b.entries {
				op := &b.entries[i]
				if op.Type != batch.OpPut || !b.db.shouldWriteViaValueLogForKeyValue(op.Key, op.Value) {
					continue
				}
				eligibleIdxs = append(eligibleIdxs, i)
			}
		}
		eligibleCountTotal = len(eligibleIdxs)
		allowPointers = eligibleCountTotal > 0 && valueLogEnabled && b.db.allowValueLogPointers()
		if allowPointers && b.db.disableJournal && !b.db.memtableValueLogPointers {
			// WAL-off: when the journal is disabled, defer value-log appends to the flush boundary
			// so repeated overwrites can coalesce in the memtable before hitting disk.
			allowPointers = false
		}
		eligibleCount = len(eligibleIdxs)
		materializeCommandWALPointers = durability == journalDurabilitySync &&
			allowPointers &&
			b.commandWALCanMaterializeValueLogPointers(eligibleIdxs)
		if debugPtr && eligibleCountTotal > 0 {
			b.db.debugPtrEligible.Add(int64(eligibleCountTotal))
			if !valueLogEnabled {
				b.db.debugPtrDisabled.Add(int64(eligibleCountTotal))
			} else if !allowPointers {
				b.db.debugPtrDenied.Add(int64(eligibleCountTotal))
			}
		}
		multiLanePointers = allowPointers &&
			!materializeCommandWALPointers &&
			b.db.disableJournal &&
			// journalDurabilityFlush is still an unsynced fast-path write. We widen
			// multi-lane pointer batching to include it so unsynced importer batches
			// can flush pointer payload bytes without collapsing back to a single lane.
			(durability == journalDurabilityNone || durability == journalDurabilityFlush) &&
			len(b.db.lanes) > 1 &&
			eligibleCount >= multiLaneValueLogMinRecords
	}

	var (
		lane *lane
		rids []uint64
	)
	needLaneForPointers := !allDeletes && !multiLanePointers && allowPointers
	needLaneForJournal := !b.db.disableJournal
	reserveLane := durability == journalDurabilitySync || materializeCommandWALPointers
	if needLaneForPointers || needLaneForJournal {
		l, err := b.db.pickLane(reserveLane, -1)
		if err != nil {
			unlockWriteMu()
			return err
		}
		lane = l
		if reserveLane {
			defer b.db.releaseLaneSync(lane)
		}
		if !b.db.disableJournal && allowPointers {
			rids = make([]uint64, len(b.entries))
		}
	}
	if materializeCommandWALPointers {
		materializeCommandWALPointers = b.commandWALMaterializedRIDFitsCurrentValueLogSegment(lane, eligibleIdxs)
		if materializeCommandWALPointers {
			// The command frame carries both the reserved RID and the value
			// bytes, so the value-log append is recoverable without becoming a
			// stable dependency before the command-WAL acknowledgement.
			durability = journalDurabilityNone
		}
	}
	b.commandWALMaterializedRID = materializeCommandWALPointers

	if !allDeletes && allowPointers && eligibleCount > 0 {
		if multiLanePointers {
			type laneValueLogBatch struct {
				laneID      int
				idxs        []int
				records     []valuelog.Record
				safeNoClear bool
				ptrs        []page.ValuePtr
				err         error
			}

			laneCounts := make([]int, len(b.db.lanes))
			for _, idx := range eligibleIdxs {
				laneID := b.db.laneForShardIndex(shardIdxs[idx])
				if laneID < 0 || laneID >= len(b.db.lanes) {
					laneID = 0
				}
				laneCounts[laneID]++
			}

			laneBatches := make([]laneValueLogBatch, len(b.db.lanes))
			activeLaneIDs := make([]int, 0, len(b.db.lanes))
			for laneID, count := range laneCounts {
				if count == 0 {
					continue
				}
				lb := &laneBatches[laneID]
				lb.laneID = laneID
				lb.idxs = make([]int, 0, count)
				lb.records = getValueLogRecordsCap(count)
				lb.safeNoClear = true
				activeLaneIDs = append(activeLaneIDs, laneID)
			}

			defer func() {
				for _, laneID := range activeLaneIDs {
					lb := &laneBatches[laneID]
					if lb.records != nil {
						if lb.safeNoClear {
							putValueLogRecordsNoClear(lb.records)
						} else {
							putValueLogRecords(lb.records)
						}
						lb.records = nil
					}
					if lb.ptrs != nil {
						putValueLogPtrs(lb.ptrs)
						lb.ptrs = nil
					}
				}
			}()

			for _, idx := range eligibleIdxs {
				op := &b.entries[idx]
				rid := b.db.nextRID.Add(1)
				if rids != nil {
					rids[idx] = rid
				}
				laneID := b.db.laneForShardIndex(shardIdxs[idx])
				if laneID < 0 || laneID >= len(b.db.lanes) {
					laneID = 0
				}
				lb := &laneBatches[laneID]
				payload := op.Value
				if lb.safeNoClear && (len(payload) > 64 || cap(payload) > 64) {
					lb.safeNoClear = false
				}
				lb.idxs = append(lb.idxs, idx)
				lb.records = append(lb.records, valuelog.Record{RID: rid, Value: payload})
			}

			var wg sync.WaitGroup
			for _, laneID := range activeLaneIDs {
				lb := &laneBatches[laneID]
				wg.Add(1)
				go func(batch *laneValueLogBatch) {
					defer wg.Done()
					batch.ptrs, batch.err = b.db.appendValueLogForRecords(&b.db.lanes[batch.laneID], batch.records, durability)
				}(lb)
			}
			wg.Wait()

			for _, laneID := range activeLaneIDs {
				lb := &laneBatches[laneID]
				if lb.err != nil {
					unlockWriteMu()
					return lb.err
				}
			}

			for _, laneID := range activeLaneIDs {
				lb := &laneBatches[laneID]
				if len(lb.ptrs) != len(lb.idxs) {
					if debugPtr {
						b.db.debugPtrNoPtr.Add(int64(len(lb.idxs)))
					}
					continue
				}
				for i, idx := range lb.idxs {
					op := &b.entries[idx]
					op.ValuePtr = lb.ptrs[i]
					op.IsPtr = true
					if b.db.memtableValueLogPointers && !materializeCommandWALPointers {
						op.Value = nil
					}
				}
				if debugPtr {
					b.db.debugPtrUsed.Add(int64(len(lb.idxs)))
				}
				retainPath := b.db.currentValueLogPath(&b.db.lanes[lb.laneID])
				if retainPath != "" {
					b.db.markValueLogRetain(retainPath)
				}
				putValueLogPtrs(lb.ptrs)
				lb.ptrs = nil
			}
		} else {
			keys := getValueLogKeys(eligibleCount)
			defer putValueLogKeys(keys)
			values := getValueLogKeys(eligibleCount)
			defer putValueLogKeys(values)
			for _, idx := range eligibleIdxs {
				op := &b.entries[idx]
				keys = append(keys, op.Key)
				values = append(values, op.Value)
			}
			var (
				ptrs         []page.ValuePtr
				groups       []outerLeafRecordGroup
				valueRecords []valuelog.Record
				outerArena   []byte
			)
			valueRecords, groups, outerArena, buildErr := b.db.buildOuterLeafValueRecords(keys, values)
			if buildErr != nil {
				unlockWriteMu()
				return buildErr
			}
			if len(valueRecords) == 0 {
				putValueLogRecordsNoClear(valueRecords)
				putOuterLeafArena(outerArena)
				unlockWriteMu()
				return fmt.Errorf("cachingdb: empty value-log record set for %d eligible ops", eligibleCount)
			}
			defer putValueLogRecordsNoClear(valueRecords)
			defer putOuterLeafArena(outerArena)
			startRID := b.db.nextRID.Add(uint64(len(valueRecords))) - uint64(len(valueRecords)) + 1
			for i := range valueRecords {
				rid := startRID + uint64(i)
				valueRecords[i].RID = rid
				if rids != nil {
					group := groups[i]
					if group.start < 0 || group.end < group.start || group.end > len(eligibleIdxs) {
						unlockWriteMu()
						return fmt.Errorf("cachingdb: value-log group out of range [%d,%d) len=%d", group.start, group.end, len(eligibleIdxs))
					}
					for srcPos := group.start; srcPos < group.end; srcPos++ {
						idx := eligibleIdxs[srcPos]
						rids[idx] = rid
					}
				}
			}
			ptrs, buildErr = b.db.appendValueLogForRecords(lane, valueRecords, durability)
			if buildErr != nil {
				unlockWriteMu()
				return buildErr
			}
			if len(ptrs) != len(groups) {
				putValueLogPtrs(ptrs)
				unlockWriteMu()
				return fmt.Errorf("cachingdb: value-log pointer group count mismatch expected=%d got=%d", len(groups), len(ptrs))
			}
			defer putValueLogPtrs(ptrs)

			used := 0
			for i := range groups {
				ptr := ptrs[i]
				group := groups[i]
				if group.start < 0 || group.end < group.start || group.end > len(eligibleIdxs) {
					unlockWriteMu()
					return fmt.Errorf("cachingdb: value-log pointer group out of range [%d,%d) len=%d", group.start, group.end, len(eligibleIdxs))
				}
				for srcPos := group.start; srcPos < group.end; srcPos++ {
					idx := eligibleIdxs[srcPos]
					op := &b.entries[idx]
					op.ValuePtr = ptr
					op.IsPtr = true
					if b.db.memtableValueLogPointers && !materializeCommandWALPointers {
						op.Value = nil
					}
					used++
				}
			}
			if debugPtr && used > 0 {
				b.db.debugPtrUsed.Add(int64(used))
			}
			retainPath := b.db.currentValueLogPath(lane)
			if retainPath != "" {
				b.db.markValueLogRetain(retainPath)
			}
		}
	}

	_, hasLegacyRevisions := b.db.prepareEntryRevisionAssignment(b.entries)
	if b.db.disableJournal && hasLegacyRevisions && !b.commandWALPreparedRevision {
		assignLegacyPointEntryRevisions(b.entries, b.db.nextEntryRevision())
	}

	if !b.db.disableJournal {
		seq := b.db.nextCommitSeq.Add(1)
		if hasLegacyRevisions {
			assignLegacyPointEntryRevisions(b.entries, page.EntryRevision(seq))
		}
		handledZeroInline := false
		needsWALRevisionEncoding := batchEntriesNeedWALRevisionEncoding(b.entries, seq)
		if zeroInlineWALBatch && !needsWALRevisionEncoding && rids == nil && zeroInlineValueLen > 0 {
			var err error
			handledZeroInline, err = b.db.appendWALZeroInlineEntries(lane, b.entries, seq, zeroInlineValueLen, durability)
			if err != nil {
				unlockWriteMu()
				return err
			}
			if handledZeroInline {
				b.walBuf = b.walBuf[:0]
			}
		}
		if !handledZeroInline {
			records := b.walBuf[:0]
			if cap(records) < len(b.entries) {
				records = make([]logRecord, 0, len(b.entries))
			}
			for i := range b.entries {
				op := &b.entries[i]
				recordRevision := batchEntryWALRevision(op, seq)
				switch op.Type {
				case batch.OpDelete:
					records = append(records, logRecord{Op: logOpDelete, Key: op.Key, Seq: seq, Revision: recordRevision})
				case batch.OpPut:
					if rids != nil && rids[i] != 0 {
						records = append(records, logRecord{Op: logOpSetRID, Key: op.Key, RID: rids[i], Seq: seq, Revision: recordRevision})
					} else {
						records = append(records, logRecord{Op: logOpSetInline, Key: op.Key, Value: op.Value, Seq: seq, Revision: recordRevision})
					}
				}
			}
			b.walBuf = records
			if err := b.db.appendWALAssigned(lane, records, durability); err != nil {
				unlockWriteMu()
				return err
			}
		}
	}

	if b.commandWALAppend != nil {
		if b.commandWALMaterializedRID && b.db.memtableValueLogPointers {
			for _, idx := range b.ptrValueIdxs {
				if idx < 0 || idx >= len(b.entries) {
					unlockWriteMu()
					return fmt.Errorf("cachingdb: ptr value entry index %d out of range", idx)
				}
			}
		}
		if err := b.commandWALAppend(); err != nil {
			unlockWriteMu()
			return err
		}
		commandWALAppended = true
		if b.commandWALMaterializedRID && b.db.memtableValueLogPointers {
			// SetMaterializedRID needs the value through the callback above. The
			// pointer-in-memtable representation needs only ValuePtr, so clear the
			// serialization copy before any sorted/steal publication path can take
			// ownership of it.
			for _, idx := range b.ptrValueIdxs {
				if b.entries[idx].IsPtr {
					b.entries[idx].Value = nil
				}
			}
		}
	}

	if !allDeletes {
		// Before borrowing batch arena chunks into memtables, compact
		// pathologically underfilled tail chunks by cloning only the aliased
		// entry slices. This converts a large retained tail into tight slices.
		b.maybeCompactUnderfilledArenaTails()
	}
	b.db.conditionalRecordCommittedEntries(b.entries, nil, b.conditionalTxnID)

	if allDeletes {
		shardIdxSets := b.shardIdxSets
		if cap(shardIdxSets) < shardCount {
			shardIdxSets = make([][]int, shardCount)
		} else {
			shardIdxSets = shardIdxSets[:shardCount]
			for i := range shardIdxSets {
				shardIdxSets[i] = shardIdxSets[i][:0]
			}
		}
		b.shardIdxSets = shardIdxSets
		for i, count := range shardCounts {
			if count <= 0 {
				continue
			}
			idxs := shardIdxSets[i]
			if cap(idxs) < count {
				if cap(idxs) > 0 {
					b.db.putBatchIntSlice(idxs)
				}
				idxs = b.db.getBatchIntSlice(count)
			} else {
				idxs = idxs[:0]
			}
			shardIdxSets[i] = idxs
		}
		for i := range b.entries {
			idx := shardIdxs[i]
			shardIdxSets[idx] = append(shardIdxSets[idx], i)
		}

		// 3. Memtable Update (delete-only fast path)
		for i := range shardIdxSets {
			idxs := shardIdxSets[i]
			if len(idxs) == 0 {
				continue
			}
			shard := &b.db.mutableShards[i]
			shard.mu.Lock()
			reserveMemtableEntries(b.db, shard.mem, len(idxs))
			useSteal, stealSuppressedDeferred := cachedBatchWriteUseSteal(b.db, shard.mem)
			useSteal = allowBatchArenaBorrow && useSteal
			if stealSuppressedDeferred && allowBatchArenaBorrow {
				batchArenaStealSuppressedDeferredTotal.Add(1)
				batchArenaStealSuppressedDeferredEntriesTotal.Add(uint64(len(idxs)))
			}
			if useSteal && cachedBatchWriteNeedsBatchArenaRetention(shard.mem) {
				retainMainMems = appendUniqueMemtable(retainMainMems, shard.mem)
			}
			if b.streamEligible {
				first := b.entries[idxs[0]].Key
				last := first
				for _, entryIdx := range idxs {
					key := b.entries[entryIdx].Key
					last = key
					if err := memtableBatchDelete(shard.mem, useSteal, key, b.entries[entryIdx].Revision); err != nil {
						return failMemtableApply(shard, err)
					}
				}
				shard.rng.add(first)
				if len(idxs) > 1 {
					shard.rng.add(last)
				}
				b.db.noteWriteSortedRun(first, last, len(idxs))
			} else {
				for _, entryIdx := range idxs {
					key := b.entries[entryIdx].Key
					if err := memtableBatchDelete(shard.mem, useSteal, key, b.entries[entryIdx].Revision); err != nil {
						return failMemtableApply(shard, err)
					}
					shard.rng.add(key)
					b.db.noteWriteKey(key)
				}
			}
			newBytes := shard.mem.Size()
			delta := newBytes - shard.bytes
			shard.bytes = newBytes
			b.db.mutableBytes.Add(delta)
			shard.mu.Unlock()
		}
	} else {
		appliedSmallSorted, err := b.tryApplySmallSelectedSortedShard(
			shardCounts,
			shardIdxs,
			allowBatchArenaBorrow,
			allowStableViewValueBorrow,
			&retainMainMems,
			&retainStableViewValueMems,
			failMemtableApply,
		)
		if err != nil {
			return err
		}
		if !appliedSmallSorted {
			shardEntries := b.shardEntries
			if cap(shardEntries) < shardCount {
				if cap(shardEntries) > 0 {
					b.releaseShardEntryGroups(shardEntries)
				}
				shardEntries = b.db.getBatchShardEntryGroups(shardCount)
				shardEntries = shardEntries[:shardCount]
			} else {
				shardEntries = shardEntries[:shardCount]
				for i := range shardEntries {
					shardEntries[i] = shardEntries[i][:0]
				}
			}
			b.shardEntries = shardEntries
			for i, count := range shardCounts {
				if count > 0 {
					entries := shardEntries[i]
					if cap(entries) < count {
						if cap(entries) > 0 {
							b.db.putBatchShardEntries(entries)
						}
						entries = b.db.getBatchShardEntries(count)
					} else {
						entries = entries[:0]
					}
					shardEntries[i] = entries
				}
			}
			for i, op := range b.entries {
				idx := shardIdxs[i]
				shardEntries[idx] = append(shardEntries[idx], op)
			}

			// 3. Memtable Update
			for i := range shardEntries {
				entries := shardEntries[i]
				if len(entries) == 0 {
					continue
				}
				shard := &b.db.mutableShards[i]
				shard.mu.Lock()
				reserveMemtableEntries(b.db, shard.mem, len(entries))
				useStream := b.streamEligible
				useSteal, stealSuppressedDeferred := cachedBatchWriteUseSteal(b.db, shard.mem)
				useSteal = allowBatchArenaBorrow && useSteal
				if stealSuppressedDeferred && allowBatchArenaBorrow {
					batchArenaStealSuppressedDeferredTotal.Add(1)
					batchArenaStealSuppressedDeferredEntriesTotal.Add(uint64(len(entries)))
				}
				if useSteal && cachedBatchWriteNeedsBatchArenaRetention(shard.mem) {
					retainMainMems = appendUniqueMemtable(retainMainMems, shard.mem)
				}
				storeInlinePtrValues := !b.db.memtableValueLogPointers
				appliedSortedRun := false
				if useStream {
					if useSteal {
						if applier, ok := shard.mem.(memtable.TrustedSortedBatchApplier); ok {
							applier.ApplyStealSortedBatchTrusted(entries, nil)
						} else if applier, ok := shard.mem.(memtable.SortedBatchApplier); ok {
							applier.ApplyStealSortedBatch(entries, nil)
						} else {
							for _, op := range entries {
								if op.Type == batch.OpDelete {
									if err := memtableBatchDelete(shard.mem, true, op.Key, op.Revision); err != nil {
										return failMemtableApply(shard, err)
									}
								} else {
									memtableBatchSet(shard.mem, true, allowBatchArenaBorrow, storeInlinePtrValues, op)
								}
							}
						}
						appliedSortedRun = true
					} else {
						if allowStableViewValueBorrow {
							if applier, ok := shard.mem.(memtable.CopySortedBatchApplier); ok {
								if borrowed := applier.ApplyCopySortedBatchTrusted(entries, true, storeInlinePtrValues, nil); borrowed {
									retainStableViewValueMems = appendUniqueMemtable(retainStableViewValueMems, shard.mem)
								}
								appliedSortedRun = true
							}
						}
						if !appliedSortedRun && !allowBatchArenaBorrow {
							if applier, ok := shard.mem.(memtable.CopySortedBatchValueCopier); ok {
								applier.ApplyCopySortedBatchWithValueCopierTrusted(entries, b.appendOnlyDirectValueCopierForShard(shard), storeInlinePtrValues, nil)
								b.valueCopyShard = nil
								appliedSortedRun = true
							}
						}
						if !appliedSortedRun {
							if applier, ok := shard.mem.(memtable.CopySortedBatchApplier); ok {
								if borrowed := applier.ApplyCopySortedBatchTrusted(entries, allowBatchArenaBorrow, storeInlinePtrValues, nil); borrowed {
									retainMainMems = appendUniqueMemtable(retainMainMems, shard.mem)
								}
								appliedSortedRun = true
							}
						}
					}
				}
				if !appliedSortedRun {
					for _, op := range entries {
						if op.Type == batch.OpDelete {
							if err := memtableBatchDelete(shard.mem, useSteal, op.Key, op.Revision); err != nil {
								return failMemtableApply(shard, err)
							}
						} else {
							borrowedMainArena := false
							borrowedStableViewValue := false
							allowValueBorrow := allowBatchArenaBorrow
							if !allowValueBorrow && allowStableViewValueBorrow && !useSteal {
								allowValueBorrow = true
								if _, ok := shard.mem.(memtable.ValueBorrower); ok {
									if op.IsPtr {
										borrowedStableViewValue = storeInlinePtrValues && len(op.Value) > 0
									} else {
										borrowedStableViewValue = len(op.Value) > 0
									}
								}
							}
							if allowBatchArenaBorrow && !useSteal {
								if _, ok := shard.mem.(memtable.ValueBorrower); ok {
									if op.IsPtr {
										borrowedMainArena = storeInlinePtrValues && len(op.Value) > 0
									} else {
										borrowedMainArena = len(op.Value) > 0
									}
								}
							}
							memtableBatchSet(shard.mem, useSteal, allowValueBorrow, storeInlinePtrValues, op)
							if borrowedMainArena {
								retainMainMems = appendUniqueMemtable(retainMainMems, shard.mem)
							}
							if borrowedStableViewValue {
								retainStableViewValueMems = appendUniqueMemtable(retainStableViewValueMems, shard.mem)
							}
						}
						if useStream {
							// Preserve sorted-run accounting even when no sorted batch applier is available.
							continue
						}
						shard.rng.add(op.Key)
						b.db.noteWriteKey(op.Key)
					}
				}
				if useStream {
					first := entries[0].Key
					last := entries[len(entries)-1].Key
					shard.rng.add(first)
					if len(entries) > 1 {
						shard.rng.add(last)
					}
					b.db.noteWriteSortedRun(first, last, len(entries))
				}
				newBytes := shard.mem.Size()
				delta := newBytes - shard.bytes
				shard.bytes = newBytes
				b.db.mutableBytes.Add(delta)
				shard.mu.Unlock()
			}
		}
	}

	// 3. Threshold Check
	if b.db.mutableBytes.Load() > b.db.mutableFlushThreshold() {
		needRotate = true
	}
	// Command-WAL public writes already made the command frame durable before
	// publishing to the mutable table; the cached backend checkpoint is not the
	// per-WriteSync durability boundary for that path.
	if syncWrite && b.db.disableJournal && b.commandWALAppend == nil {
		needSyncBarrier = true
	}
	b.updateBatchEntryHint()
	b.updateBatchCopyHint()
	mainChunks := b.drainCopyArenaChunks()
	retainPtrArena := false
	var ptrTouchedMemStack [batchMemtableRetainStackCap]memtable.Table
	ptrTouchedMems := ptrTouchedMemStack[:0]
	if allowBatchArenaBorrow && len(b.ptrValueIdxs) > 0 {
		for _, idx := range b.ptrValueIdxs {
			if idx < 0 || idx >= len(b.entries) || idx >= len(shardIdxs) {
				unlockWriteMu()
				return fmt.Errorf("cachingdb: ptr value entry index %d out of range", idx)
			}
			if b.entries[idx].Value == nil {
				continue
			}
			retainPtrArena = true
			shardIdx := shardIdxs[idx]
			if shardIdx < 0 || shardIdx >= len(b.db.mutableShards) {
				unlockWriteMu()
				return fmt.Errorf("cachingdb: ptr value shard index %d out of range for entry %d", shardIdx, idx)
			}
			mt := b.db.mutableShards[shardIdx].mem
			if mt == nil {
				continue
			}
			ptrTouchedMems = appendUniqueMemtable(ptrTouchedMems, mt)
		}
	}
	if b.ptrValueIdxs != nil {
		b.ptrValueIdxs = b.ptrValueIdxs[:0]
	}
	ptrChunks := b.drainPtrCopyArenaChunks()
	b.db.retainBatchArenaChunksForMemtables(mainChunks, retainMainMems)
	finalizeStableViewValueLease()
	if !stableViewValueLeaseFinalized {
		b.stableViewValueLeaseChunks = nil
	}
	if retainPtrArena {
		b.db.retainBatchArenaChunksForMemtables(ptrChunks, ptrTouchedMems)
	} else {
		putBatchArenas(ptrChunks)
		b.db.putBatchArenaChunkListLease(ptrChunks)
	}
	unlockWriteMu()

	if needRotate {
		if err := b.db.maybeRotateMemtable(true); err != nil {
			if commandWALAppended {
				b.db.reportError(fmt.Errorf("cachingdb: post-command-wal batch rotate failed: %w", err))
			} else {
				return err
			}
		}
	}
	if needSyncBarrier {
		if err := b.db.syncBarrierAfterWrite(true); err != nil {
			if commandWALAppended {
				b.db.reportError(fmt.Errorf("cachingdb: post-command-wal batch sync barrier failed: %w", err))
			} else {
				return err
			}
		}
	}

	if b.size > 0 {
		b.db.noteWrite()
	}
	b.db.maybeAssistFlush()
	b.Reset()
	return nil
}

func (b *Batch) commandWALCanMaterializeValueLogPointers(eligibleIdxs []int) bool {
	if b == nil || b.db == nil || b.commandWALAppend == nil || !b.db.externalCommandWAL ||
		len(eligibleIdxs) == 0 || len(b.entries) == 0 || len(b.entries) > commandWALMaterializedRIDMaxOps {
		return false
	}
	capBytes := b.db.walMaxSegmentBytes
	if capBytes <= 0 {
		capBytes = commandWALDefaultMaxSegmentBytes
	}
	if capBytes > commandWALMaterializedRIDMaxBatchBytes {
		capBytes = commandWALMaterializedRIDMaxBatchBytes
	}
	estimated := int64(commandWALMaterializedRIDFrameReserve)
	for i, idx := range eligibleIdxs {
		if idx < 0 || idx >= len(b.entries) {
			return false
		}
		if i > 0 && idx <= eligibleIdxs[i-1] {
			return false
		}
		if len(b.entries[idx].Value) == 0 || len(b.entries[idx].Value) > commandWALMaterializedRIDMaxValueBytes {
			return false
		}
	}
	eligibleCursor := 0
	for i := range b.entries {
		entry := &b.entries[i]
		delta := int64(commandWALMaterializedRIDOpOverhead) + int64(len(entry.Key))
		if entry.Type == batch.OpPut {
			delta += int64(len(entry.Value))
			if eligibleCursor < len(eligibleIdxs) && eligibleIdxs[eligibleCursor] == i {
				eligibleCursor++
			}
		} else if entry.Type == batch.OpDeleteRange {
			delta += int64(len(entry.Value))
		}
		if delta > capBytes-estimated {
			return false
		}
		estimated += delta
	}
	return eligibleCursor == len(eligibleIdxs) && estimated <= capBytes
}

func (b *Batch) commandWALMaterializedRIDFitsCurrentValueLogSegment(l *lane, eligibleIdxs []int) bool {
	if b == nil || b.db == nil || l == nil || len(eligibleIdxs) == 0 {
		return false
	}
	maxBytes := b.db.valueLogMaxSegmentBytesForLane(l)
	if maxBytes <= 0 {
		return true
	}
	estimated := int64(commandWALMaterializedRIDVLogReserve)
	for _, idx := range eligibleIdxs {
		if idx < 0 || idx >= len(b.entries) {
			return false
		}
		entry := &b.entries[idx]
		delta := int64(commandWALMaterializedRIDVLogOpOverhead) + int64(len(entry.Key)) + int64(len(entry.Value))
		if delta > maxBytes-estimated {
			return false
		}
		estimated += delta
	}
	l.vlogMu.Lock()
	defer l.vlogMu.Unlock()
	if l.vlog == nil {
		return true
	}
	size := l.vlog.Size()
	return size <= maxBytes-estimated
}

type logSegmentInfo struct {
	path     string
	size     int64
	seq      int
	lane     int
	valueLog bool
}

func listNonEmptyLogSegments(walDir string) (segments []logSegmentInfo, nonEmptyBytes int64) {
	entries, err := os.ReadDir(walDir)
	if err != nil {
		return nil, 0
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		lane, seq, valueLog, ok := parseLogSeq(name)
		if !ok {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			continue
		}
		path := filepath.Join(walDir, name)
		segments = append(segments, logSegmentInfo{path: path, size: info.Size(), seq: seq, lane: lane, valueLog: valueLog})
		if info.Size() > 0 {
			nonEmptyBytes += info.Size()
		}
	}
	return segments, nonEmptyBytes
}

func ensureNoLegacyMixedWALValueSegments(walDir string) error {
	entries, err := os.ReadDir(walDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		for _, pattern := range []string{"value-*.log", "vlog-*.log"} {
			matched, err := filepath.Match(pattern, entry.Name())
			if err != nil {
				return err
			}
			if matched {
				return fmt.Errorf("cachingdb: legacy value-log segments found in %s; rebuild required for split wal/value_vlog layout", walDir)
			}
		}
	}
	return nil
}

func listNonEmptySplitLogSegments(walDir, valueLogDir, leafLogDir string) (segments []logSegmentInfo, nonEmptyBytes int64) {
	walSegments, walBytes := listNonEmptyLogSegments(walDir)
	for _, seg := range walSegments {
		if seg.valueLog {
			continue
		}
		segments = append(segments, seg)
	}
	nonEmptyBytes += walBytes
	for _, dir := range []string{valueLogDir, leafLogDir} {
		vlogSegments, vlogBytes := listNonEmptyLogSegments(dir)
		for _, seg := range vlogSegments {
			if !seg.valueLog {
				continue
			}
			segments = append(segments, seg)
		}
		nonEmptyBytes += vlogBytes
	}
	sort.Slice(segments, func(i, j int) bool {
		if segments[i].lane != segments[j].lane {
			return segments[i].lane < segments[j].lane
		}
		if segments[i].seq != segments[j].seq {
			return segments[i].seq < segments[j].seq
		}
		if segments[i].valueLog != segments[j].valueLog {
			return !segments[i].valueLog && segments[j].valueLog
		}
		return segments[i].path < segments[j].path
	})
	return segments, nonEmptyBytes
}

func maxValueLogRIDFromSegments(segments []logSegmentInfo) (uint64, error) {
	var maxRID uint64
	for _, seg := range segments {
		if !seg.valueLog || seg.size <= 0 || seg.lane < 0 || seg.seq < 0 {
			continue
		}
		fileID, err := valuelog.EncodeFileID(uint32(seg.lane), uint32(seg.seq))
		if err != nil {
			return 0, err
		}
		reader, err := valuelog.NewReader(seg.path, fileID)
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				continue
			}
			return 0, err
		}
		reader.DisableValueDecode()
		for {
			rid, _, err := reader.ReadNextMeta()
			if err == nil {
				if rid > maxRID {
					maxRID = rid
				}
				continue
			}
			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
				break
			}
			_ = reader.Close()
			return 0, err
		}
		if err := reader.Close(); err != nil {
			return 0, err
		}
	}
	return maxRID, nil
}

func tailValueLogSegmentsByLane(segments []logSegmentInfo) []logSegmentInfo {
	return tailValueLogSegmentsByLaneExcept(segments, -1)
}

func tailValueLogSegmentsByLaneExcept(segments []logSegmentInfo, exceptLane int) []logSegmentInfo {
	if len(segments) == 0 {
		return nil
	}
	tailByLane := make(map[int]logSegmentInfo)
	for _, seg := range segments {
		if !seg.valueLog || seg.size <= 0 || seg.lane < 0 || seg.seq < 0 || seg.lane == exceptLane {
			continue
		}
		prev, ok := tailByLane[seg.lane]
		if !ok || seg.seq > prev.seq {
			tailByLane[seg.lane] = seg
		}
	}
	if len(tailByLane) == 0 {
		return nil
	}
	tails := make([]logSegmentInfo, 0, len(tailByLane))
	for _, seg := range tailByLane {
		tails = append(tails, seg)
	}
	sort.Slice(tails, func(i, j int) bool {
		if tails[i].lane != tails[j].lane {
			return tails[i].lane < tails[j].lane
		}
		return tails[i].seq < tails[j].seq
	})
	return tails
}

func parseLogSeq(name string) (int, int, bool, bool) {
	const (
		commitPrefix = "commit-"
		valuePrefix  = "value-"
		walPrefix    = "wal-"
		vlogPrefix   = "vlog-"
	)
	if filepath.Ext(name) != ".log" {
		return 0, 0, false, false
	}
	base := strings.TrimSuffix(name, ".log")

	parseLaneSeq := func(rest string) (int, int, bool) {
		parts := strings.SplitN(rest, "-", 2)
		if len(parts) != 2 {
			return 0, 0, false
		}
		lane, err := strconv.Atoi(parts[0])
		if err != nil || lane < 0 {
			return 0, 0, false
		}
		seq, err := strconv.Atoi(parts[1])
		if err != nil || seq < 0 {
			return 0, 0, false
		}
		return lane, seq, true
	}

	if strings.HasPrefix(base, "commit-l") {
		lane, seq, ok := parseLaneSeq(strings.TrimPrefix(base, "commit-l"))
		return lane, seq, false, ok
	}
	if strings.HasPrefix(base, "value-l") {
		lane, seq, ok := parseLaneSeq(strings.TrimPrefix(base, "value-l"))
		return lane, seq, true, ok
	}
	if strings.HasPrefix(base, commitPrefix) {
		core := strings.TrimPrefix(base, commitPrefix)
		if core == "" {
			return 0, 0, false, false
		}
		seq, err := strconv.Atoi(core)
		if err != nil {
			return 0, 0, false, false
		}
		return 0, seq, false, true
	}
	if strings.HasPrefix(base, valuePrefix) {
		core := strings.TrimPrefix(base, valuePrefix)
		if core == "" {
			return 0, 0, false, false
		}
		seq, err := strconv.Atoi(core)
		if err != nil {
			return 0, 0, false, false
		}
		return 0, seq, true, true
	}
	if strings.HasPrefix(base, walPrefix) {
		core := strings.TrimPrefix(base, walPrefix)
		if core == "" {
			return 0, 0, false, false
		}
		seq, err := strconv.Atoi(core)
		if err != nil {
			return 0, 0, false, false
		}
		return 0, seq, false, true
	}
	if strings.HasPrefix(base, vlogPrefix) {
		core := strings.TrimPrefix(base, vlogPrefix)
		if core == "" {
			return 0, 0, false, false
		}
		seq, err := strconv.Atoi(core)
		if err != nil {
			return 0, 0, false, false
		}
		return 0, seq, true, true
	}
	return 0, 0, false, false
}

func (b *Batch) writeBypass(sync bool) (err error) {
	// WAL-off + outer-leaf-in-vlog workloads are highly sensitive to write
	// coalescing. Direct backend sync writes can preserve correctness but still
	// explode the live leaf-page count because each batch mutates the backend tree
	// incrementally instead of letting the cached flush path rebuild denser pages.
	// Keep the direct bypass for other cases, but route this profile through the
	// regular cached path.
	if sync && b.db.disableJournal && b.db.indexOuterLeavesInValueLog {
		return b.writeRegular(sync)
	}
	// Fast path: if none of these keys exist in mutable/queue, we can write directly
	// to the backend without flushing (no in-memory shadowing possible).
	// Cheap append-only check: if the batch key range does not overlap with any
	// in-memory key ranges, it cannot be shadowed.
	batchRange := keyRange{}
	for _, op := range b.entries {
		key := op.Key
		batchRange.add(key)
	}

	mutableRange := b.db.snapshotMutableRange()

	var (
		mutables      []memtable.Table
		queue         []memtable.Table
		queueShardIDs []uint16
		queueRanges   []keyRange
		overlaps      bool
	)
	view := b.db.retainMemtableView()
	if view != nil {
		if memtableViewHasRangeSpans(view) {
			b.db.releaseMemtableView(view)
			return b.writeRegular(sync)
		}
		defer b.db.releaseMemtableView(view)
	}

	b.db.mu.RLock()
	hasRangeSpans := view == nil && rangeSpanLayerHasSpans(b.db.queueRangeSpans)
	overlaps = rangesOverlap(batchRange, mutableRange)
	if view != nil {
		mutables = view.mutables
		queue = view.queue
		queueShardIDs = view.queueShardIDs
		queueRanges = view.queueRanges
	} else {
		// Defensive fallback: should not happen after Open(), but keep safe
		// behavior for zero-value DBs and tests.
		if len(b.db.mutableShards) > 0 {
			mutables = make([]memtable.Table, len(b.db.mutableShards))
			for i := range b.db.mutableShards {
				mutables[i] = b.db.mutableShards[i].mem
			}
		}
		if len(b.db.queue) > 0 {
			queue = append([]memtable.Table(nil), b.db.queue...)
		}
		if len(b.db.queueShardIDs) > 0 {
			queueShardIDs = append([]uint16(nil), b.db.queueShardIDs...)
		}
		if len(b.db.queueRanges) > 0 {
			queueRanges = append([]keyRange(nil), b.db.queueRanges...)
		}
	}
	b.db.mu.RUnlock()
	if hasRangeSpans {
		return b.writeRegular(sync)
	}

	if !overlaps {
		if len(queueRanges) == 0 && len(queue) > 0 {
			overlaps = true
		} else {
			for _, r := range queueRanges {
				if rangesOverlap(batchRange, r) {
					overlaps = true
					break
				}
			}
		}
	}

	if overlaps {
		// Slow path: verify no individual key exists in memory (handles sparse overlap).
		for _, op := range b.entries {
			key := op.Key
			if len(mutables) > 0 {
				idx := b.db.shardIndex(key)
				if idx < len(mutables) && mutables[idx] != nil {
					if _, _, found := mutables[idx].Get(key); found {
						return b.writeRegular(sync)
					}
				}
			}
			for i := len(queue) - 1; i >= 0; i-- {
				if len(queueShardIDs) > i && len(mutables) > 0 {
					idx := b.db.shardIndex(key)
					if int(queueShardIDs[i]) != idx {
						continue
					}
				}
				if _, _, found := queue[i].Get(key); found {
					return b.writeRegular(sync)
				}
			}
		}
	}

	// Write directly to backend
	backendBatch := b.db.backend.NewBatch()
	defer func() {
		if backendBatch != nil {
			if cerr := backendBatch.Close(); err == nil {
				err = cerr
			}
		}
	}()

	ops := getEntrySlice(len(b.entries))
	ops = append(ops, b.entries...)
	releaseOps := true
	defer func() {
		if releaseOps {
			putEntrySlice(ops)
		}
	}()

	_, hasLegacyRevisions := b.db.prepareEntryRevisionAssignment(ops)
	if hasLegacyRevisions {
		assignLegacyPointEntryRevisions(ops, b.db.nextEntryRevision())
	}

	if rewritten, err := b.db.prepareBypassValueLogOps(ops, sync); err != nil {
		return err
	} else {
		ops = rewritten
	}

	// Use SetOps for bulk transfer (backend will resolve value-log pointers).
	if err := backendBatch.SetOps(ops); err != nil {
		if errors.Is(err, batch.ErrValueTooLarge) {
			origEntries := b.entries
			b.entries = ops
			err = b.writeRegular(sync)
			if err != nil {
				b.entries = origEntries
				return err
			}
			if origEntries != nil {
				b.entries = origEntries[:0]
			} else {
				b.entries = nil
			}
			return nil
		}
		return err
	}

	err = b.writeBackendBatchSerialized(backendBatch, sync, func() {
		b.db.conditionalRecordCommittedEntries(ops, nil, 0)
	}, nil)

	if err != nil {
		return err
	}
	backendBatch = nil

	b.db.mu.Lock()
	if batchRange.valid {
		b.db.backendRange.add(batchRange.min)
		b.db.backendRange.add(batchRange.max)
	}
	b.db.mu.Unlock()

	if b.size > 0 {
		b.db.noteWrite()
	}
	b.updateBatchEntryHint()
	b.updateBatchCopyHint()
	b.Reset()
	return nil
}

func (b *Batch) Close() error {
	if b.closed {
		return nil
	}
	b.closed = true
	if b.backend != nil {
		_ = b.backend.Close()
		b.backend = nil
	}
	if b.db != nil && b.entries != nil {
		b.db.putBatchEntries(b.entries)
	}
	if b.db != nil && b.shardIdxs != nil {
		b.db.putBatchIntSlice(b.shardIdxs)
	}
	if b.db != nil && b.eligibleIdxs != nil {
		b.db.putBatchIntSlice(b.eligibleIdxs)
	}
	if b.db != nil && b.shardAdds != nil {
		b.db.putBatchInt64Slice(b.shardAdds)
	}
	if b.db != nil && b.shardCnts != nil {
		b.db.putBatchIntSlice(b.shardCnts)
	}
	if b.db != nil && b.shardIdxSets != nil && cap(b.shardIdxSets) > 0 {
		full := b.shardIdxSets[:cap(b.shardIdxSets)]
		for i := range full {
			if full[i] != nil {
				b.db.putBatchIntSlice(full[i])
				full[i] = nil
			}
		}
	}
	if b.db != nil && b.shardEntries != nil {
		b.releaseShardEntryGroups(b.shardEntries)
	}
	b.recycleCopyArenaChunks()
	b.recyclePtrCopyArenaChunks()
	b.entries = nil
	b.walBuf = nil
	b.shardIdxs = nil
	b.eligibleIdxs = nil
	b.shardAdds = nil
	b.shardCnts = nil
	b.shardEntries = nil
	b.shardIdxSets = nil
	b.firstKey = nil
	b.lastKey = nil
	b.entryRevision = page.LegacyEntryRevision
	b.ptrValueIdxs = nil
	b.stableViewValueLeaseChunks = nil
	b.conditionalTxnID = 0
	b.valueCopyShard = nil
	b.appendOnlyDirectValueCopier = nil
	b.commandWALCompactReplay = false
	b.commandWALCompactRanges = nil
	b.commandWALCompactPointStart = 0
	b.commandWALMaterializedRID = false
	return nil
}

func (b *Batch) Replay(fn func(batch.Entry) error) error {
	if b.closed {
		return ErrBatchClosed
	}
	if b.backend != nil {
		return b.backend.Replay(fn)
	}

	if b.commandWALCompactReplay {
		for _, r := range b.commandWALCompactRanges {
			if batch.IsDeleteRangeNoop(r.Start, r.End) {
				continue
			}
			if err := fn(batch.Entry{Type: batch.OpDeleteRange, Key: r.Start, Value: r.End}); err != nil {
				return err
			}
		}
		pointStart := b.commandWALCompactPointStart
		if pointStart < 0 {
			pointStart = 0
		}
		if pointStart > len(b.entries) {
			pointStart = len(b.entries)
		}
		for _, entry := range b.entries[pointStart:] {
			if entry.IsPtr && !b.commandWALMaterializedRID {
				entry.Value = nil
			}
			if err := fn(entry); err != nil {
				return err
			}
		}
		return nil
	}

	for _, entry := range b.entries {
		if entry.IsPtr && !b.commandWALMaterializedRID {
			entry.Value = nil
		}
		if err := fn(entry); err != nil {
			return err
		}
	}
	return nil
}

func (b *Batch) GetByteSize() (int, error) {
	if b.closed {
		return 0, ErrBatchClosed
	}
	return b.size, nil
}

// singleSourceIterator wraps a single UnsafeIterator to satisfy merging.Iterator,
// skipping tombstones.
type singleSourceIterator struct {
	iter    iterator.UnsafeIterator
	valid   bool
	start   []byte
	end     []byte
	reverse bool
}

func newSingleSourceIterator(iter iterator.UnsafeIterator, start, end []byte, reverse bool) merging.Iterator {
	it := &singleSourceIterator{
		iter:    iter,
		start:   start,
		end:     end,
		reverse: reverse,
	}
	// Iterator is already sought to start by the caller
	it.advance()
	return it
}

func (it *singleSourceIterator) advance() {
	it.valid = false
	for it.iter.Valid() {
		if it.reverse && it.start != nil && bytes.Compare(it.iter.UnsafeKey(), it.start) < 0 {
			return
		}
		if it.end != nil && bytes.Compare(it.iter.UnsafeKey(), it.end) >= 0 {
			return
		}
		if it.iter.IsDeleted() {
			it.iter.Next()
			continue
		}
		it.valid = true
		return
	}
}

func (it *singleSourceIterator) Next() {
	if !it.valid {
		panic("iterator invalid")
	}
	it.iter.Next()
	it.advance()
}

func (it *singleSourceIterator) Seek(key []byte) {
	it.valid = false
	if it.reverse && key != nil && it.start != nil && bytes.Compare(key, it.start) < 0 {
		return
	}
	if !it.reverse && it.start != nil && (key == nil || bytes.Compare(key, it.start) < 0) {
		key = it.start
	}
	it.iter.Seek(key)
	it.advance()
}

func (it *singleSourceIterator) UnsafeKey() []byte {
	if !it.valid {
		return nil
	}
	return it.iter.UnsafeKey()
}

func (it *singleSourceIterator) UnsafeValue() []byte {
	if !it.valid {
		return nil
	}
	return it.iter.UnsafeValue()
}

func (it *singleSourceIterator) UnsafeEntryWithRevision() ([]byte, page.ValuePtr, byte, page.EntryRevision) {
	if it == nil || !it.valid {
		return nil, page.ValuePtr{}, 0, page.LegacyEntryRevision
	}
	return iterator.UnsafeEntryWithRevision(it.iter)
}

func (it *singleSourceIterator) Valid() bool               { return it.valid }
func (it *singleSourceIterator) Key() []byte               { return it.iter.Key() }
func (it *singleSourceIterator) Value() []byte             { return it.iter.Value() }
func (it *singleSourceIterator) KeyCopy(dst []byte) []byte { return it.iter.KeyCopy(dst) }
func (it *singleSourceIterator) ValueCopy(dst []byte) []byte {
	return it.iter.ValueCopy(dst)
}
func (it *singleSourceIterator) Close() error             { return it.iter.Close() }
func (it *singleSourceIterator) Error() error             { return it.iter.Error() }
func (it *singleSourceIterator) Domain() ([]byte, []byte) { return it.start, it.end }

// emptyIterator represents an iterator with no elements.
type emptyIterator struct {
	start, end []byte
}

func (it *emptyIterator) Next()                     { panic("iterator invalid") }
func (it *emptyIterator) Seek([]byte)               {}
func (it *emptyIterator) Valid() bool               { return false }
func (it *emptyIterator) Key() []byte               { panic("iterator invalid") }
func (it *emptyIterator) Value() []byte             { panic("iterator invalid") }
func (it *emptyIterator) KeyCopy(_ []byte) []byte   { panic("iterator invalid") }
func (it *emptyIterator) ValueCopy(_ []byte) []byte { panic("iterator invalid") }
func (it *emptyIterator) Close() error              { return nil }
func (it *emptyIterator) Error() error              { return nil }
func (it *emptyIterator) Domain() ([]byte, []byte)  { return it.start, it.end }
